window.__HSK_CHAPTER_DATA__['chapter_02'] = [{"meanings_summary": {"en": "bunch; cluster; string; skewer; to string together; to mix up", "es": "racimo; sarta; brocheta; ensartar; encadenar; confundir"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A vertical skewer (丨) piercing through two squares (口) creates a tasty kebab skewer or a string of keys (串).", "composite_memory_hook_es": "Una vara vertical (丨) atraviesa dos cuadrados (口) formando una brocheta o una sarta de llaves (串).", "cultural_and_cognitive_roots": "In ancient Chinese commerce and food culture, coins were strung on hemp cords (贯/串), and food was skewered over charcoal fire, giving 'chuàn' the core spatial imagery of connected alignment.", "tone_sandhi_and_pitch_modulation": "Pronounced in the 4th tone with a decisive falling contour (51). When preceded by '一' (yī), '一' changes tone to 2nd tone: 'yí chuàn' (35-51)."}, "semantic_boundary_contrasts": {"core_nuance": "串 emphasizes discrete physical items or events linked continuously along a single central axis or line.", "contrasts": [{"id": "1", "compared_word": "串 vs. 束", "pinyin": "shù", "analysis": "串 classifies items pierced or tied sequentially on a string (e.g. 钥匙, 烤肉), whereas 束 classifies bundled or tied stems held together in a cluster (e.g. 一束鲜花)."}, {"id": "2", "compared_word": "串 vs. 阵", "pinyin": "zhèn", "analysis": "串 implies a continuous linear succession of things or events (一连串), while 阵 signifies a sudden, intermittent burst or wave of sensation, wind, or sound (一阵风)."}, {"id": "3", "compared_word": "串 vs. 批", "pinyin": "pī", "analysis": "串 describes small sequential units strung together, whereas 批 designates large batches, groups, or shipments handled collectively (一批货, 一批游客)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "中", "pinyin": "zhōng", "meaning_en": "center; middle", "distinction_note": "Has only one box 口 pierced by 丨, whereas 串 has two stacked boxes"}, {"character": "申", "pinyin": "shēn", "meaning_en": "state; express; 9th earthly branch", "distinction_note": "Has one box with horizontal strokes intersecting 丨 inside"}, {"character": "吕", "pinyin": "lǚ", "meaning_en": "surname; musical pitch", "distinction_note": "Two stacked boxes without the vertical piercing line 丨"}, {"character": "患", "pinyin": "huàn", "meaning_en": "disaster; worry; suffer", "distinction_note": "Has 串 on top and 心 (heart) below; anxiety pierced through the heart"}], "etymological_cognates": [{"character": "贯", "pinyin": "guàn", "gloss_en": "thread together; pass through"}, {"character": "连", "pinyin": "lián", "gloss_en": "connect; link"}, {"character": "系", "pinyin": "xì", "gloss_en": "tie; fasten; relate"}, {"character": "穿", "pinyin": "chuān", "gloss_en": "pierce through; thread; wear"}]}, "id": "1", "hanzi": "串", "pinyin": "chuàn", "level": "HSK 5", "part_of_speech": "Measure Word", "senses": [{"sense_number": "1", "part_of_speech": "Measure Word", "register": "Standard", "definition_en": "classifier for things strung together, clusters, or series of items", "definition_es": "clasificador para cosas ensartadas, racimos o series", "example_phrase": "一串钥匙 (a bunch of keys)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to string together; to thread; to skewer", "definition_es": "ensartar; enhebrar; ensartar en brocheta", "example_phrase": "把肉串起来 (skewer the meat)"}, {"sense_number": "3", "part_of_speech": "Verb", "register": "Colloquial", "definition_en": "to mix up; to cross over; to visit neighbors", "definition_es": "cruzarse; mezclarse; pasar de visita", "example_phrase": "走街串巷 (wander through streets and alleys)"}], "example_sentences": [{"id": "#1", "hanzi": "母亲从老家带了一串串红辣椒挂在厨房门前，让新家多了几分乡村的温情。", "pinyin": "Mǔqīn cóng lǎojiā dài le yí chuànchuàn hóng làjiāo guà zài chúfáng ménqián, ràng xīn jiā duō le jǐ fèn xiāngcūn de wēnqíng.", "en": "Mother brought strings of red chili peppers from our hometown and hung them before the kitchen door, adding rustic warmth to the new house.", "es": "Mi madre trajo ristras de chiles rojos de nuestra tierra natal y las colgó ante la cocina, añadiendo calidez campestre al nuevo hogar."}, {"id": "#2", "hanzi": "这次供应链断裂引发了一连串连锁反应，导致数家制造企业的生产陷入停顿。", "pinyin": "Zhè cì gōngyìngliàn duànliè yǐnfā le yì liánchuàn liánsuǒ fǎnyìng, dǎozhì shù jiā zhìzàoqǐyè de shēngchǎn xiànrù tíngdùn.", "en": "This supply chain disruption triggered a string of chain reactions, bringing production in several manufacturers to a standstill.", "es": "Esta ruptura en la cadena de suministro desencadenó una serie de reacciones en cadena que paralizó la producción de varias fábricas."}], "collocations": [{"hanzi": "一串钥匙", "en": "a bunch of keys"}, {"hanzi": "羊肉串", "en": "lamb skewers / kebabs"}, {"hanzi": "一连串", "en": "a whole series of"}, {"hanzi": "串门", "en": "visit someone's home casually"}, {"hanzi": "串通", "en": "collude; conspire with"}, {"hanzi": "串味", "en": "tainted with another smell or flavor"}], "idioms": [{"hanzi": "一串骊珠", "pinyin": "yí chuàn lí zhū", "meaning_en": "a string of bright pearls; elegant words or exquisite singing"}, {"hanzi": "走街串巷", "pinyin": "zǒu jiē chuàn xiàng", "meaning_en": "roam streets and alleys; wander all around town"}, {"hanzi": "贯穿始终", "pinyin": "guàn chuān shǐ zhōng", "meaning_en": "run through from beginning to end"}, {"hanzi": "连珠合璧", "pinyin": "lián zhū hé bì", "meaning_en": "conjunction of pearls and jade; harmonious union of talents"}], "character_decomposition": [{"character": "串", "pinyin": "chuàn", "meaning_en": "string; bunch; skewer", "meaning_es": "sarta; racimo; brocheta", "radical": "丨", "radical_meaning_en": "vertical stroke / rod", "meaning_component": "丨 (rod or skewer piercing items)", "sound_component": "吕 (doubled boxes representing items)", "stroke_count": "7", "composition_type": "独体结构", "etymology_and_mnemonic": "Pictographic depiction of two discrete objects pierced through by a single vertical skewer.", "visual_mnemonic_story_en": "Two round meat chunks (口 口) skewered through the center by a single wooden stick (丨).", "visual_mnemonic_story_es": "Dos trozos de comida (口 口) ensartados por el centro mediante un palo vertical (丨).", "tone_mnemonic_anchor": "51", "cangjie": "LL", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "故乡院落里的记忆，总是伴随着房檐下一串串金黄的玉米与红透的干辣椒。秋风拂过，它们在阳光下轻轻碰撞，发出沙沙的声响。那一串串挂起的不只是丰收的粮食，更是母亲一整年无声的惦念与辛劳。", "pinyin": "Gùxiāng yuànluò lǐ de jìyì, zǒngshì bànsuí zhe fángyán xià yí chuànchuàn jīnhuáng de yùmǐ yǔ hóng tòu de gān làjiāo. Qiūfēng fúguò, tāmen zài yángguāng xià qīngqīng pèngzhuàng, fāchū shāshā de shēngxiǎng. Nà yí chuànchuàn guà qǐ de bù zhǐ shì fēngshōu de liángshi, gèng shì mǔqīn yì zhěng nián wúshēng de diànniàn yǔ xīnláo.", "en": "Memories of the courtyard in my hometown are always accompanied by golden corn and crimson dried peppers strung beneath the eaves. Swaying in the autumn breeze, they whisper rustling sounds in the sunlight. Those hanging strings carry not just a harvest, but mother's silent devotion throughout the year.", "es": "Los recuerdos del patio de mi pueblo natal siempre evocan mazorcas doradas y chiles secos ensartados bajo los aleros. Cuando el viento otoñal los agita bajo el sol, emiten un suave crujido. Esas sartas colgadas no solo representan la cosecha, sino la callada devoción materna durante todo el año."}, {"id": "#2", "hanzi": "城市化进程的加快催生了一连串社会变迁。从传统农耕宗族到现代都市公寓，生活空间的重构重塑了邻里关系。许多学者指出，社区治理的关键在于重建居民之间的情感纽带，避免人际关系碎片化。", "pinyin": "Chéngshìhuà jìnchéng de jiākuài cuīshēng le yì liánchuàn shèhuì biànqiān. Cóng chuántǒng nónggēng zōngzú dào xiàndài dūshì gōngyù, shēnghuó kōngjiān de chónggòu zhòngshù le línlǐ guānxì. Xǔduō xuézhě zhǐchū, shèqū zhìlǐ de guānjiàn zàiyú chóngjiàn jūmín zhījiān de qínggǎn niǔdài, bìmiǎn rénjì guānxì suìpiànhuà.", "en": "The acceleration of urbanization has spurred a whole series of societal transformations. Moving from agrarian clans to urban apartments, the reconfigured living space reshapes neighborhood dynamics. Scholars highlight that successful community governance relies on rebuilding emotional bonds among residents.", "es": "La aceleración urbanística ha desatado una serie de transformaciones sociales. Del clan agrícola al apartamento urbano, la reconfiguración espacial reformula la convivencia vecinal. Los sociólogos advierten que la cohesión comunitaria requiere reconstruir lazos afectivos vecinales."}]}, {"meanings_summary": {"en": "all one's life; a lifetime; throughout one's days", "es": "toda la vida; una vida entera; a lo largo de la vida"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Traveling through a single (一) continuous caravan of generations (辈) defines a person's entire lifetime (一辈子).", "composite_memory_hook_es": "Viajar en una sola (一) caravana de generaciones (辈) define toda la vida de una persona (一辈子).", "cultural_and_cognitive_roots": "Traditional Chinese kinship conceptualizes human existence within lineage tiers (辈分). '一辈子' captures individual existence as one complete generational cycle within the endless ancestral chain.", "tone_sandhi_and_pitch_modulation": "The headword undergoes tone sandhi: '一' changes to 2nd tone 'yí' before 4th tone 'bèi', and 'zi' is read in the neutral tone (轻声): yí bèi zi (35-51-0)."}, "semantic_boundary_contrasts": {"core_nuance": "一辈子 is a colloquial, emotionally warm term emphasizing personal lived human experience across a complete lifespan.", "contrasts": [{"id": "1", "compared_word": "一辈子 vs. 一生", "pinyin": "yìshēng", "analysis": "一辈子 carries a strong colloquial, affectionate oral tone (e.g. 念叨了一辈子), while 一生 is more formal and literary, favored in biographies and philosophical writing (e.g. 他的一生波澜壮阔)."}, {"id": "2", "compared_word": "一辈子 vs. 终身", "pinyin": "zhōngshēn", "analysis": "一辈子 stresses emotional duration and daily endurance, whereas 终身 carries legal, institutional, or solemn career connotations (e.g. 终身教授, 终身监禁)."}, {"id": "3", "compared_word": "一辈子 vs. 岁月", "pinyin": "suìyuè", "analysis": "一辈子 anchors strictly to the lifespan of an individual person, whereas 岁月 refers abstractly to the passage of time or historical eras (e.g. 峥嵘岁月)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "悲", "pinyin": "bēi", "meaning_en": "sad; sorrow", "distinction_note": "Has 心 (heart) at the bottom instead of 车 (cart)"}, {"character": "斐", "pinyin": "fěi", "meaning_en": "brilliant; elegant", "distinction_note": "Has 文 (literature) at the bottom instead of 车"}, {"character": "排", "pinyin": "pái", "meaning_en": "row; line up", "distinction_note": "Has 扌 (hand) radical on the left with 非 on the right"}, {"character": "翡", "pinyin": "fěi", "meaning_en": "jadeite; green kingfisher", "distinction_note": "Has 羽 (feathers) at the bottom under 非"}], "etymological_cognates": [{"character": "辈分", "pinyin": "bèi fen", "gloss_en": "generational rank in family hierarchy"}, {"character": "前辈", "pinyin": "qián bèi", "gloss_en": "predecessor; elder generation"}, {"character": "后辈", "pinyin": "hòu bèi", "gloss_en": "younger generation; junior"}, {"character": "平辈", "pinyin": "píng bèi", "gloss_en": "person of the same generation / peer"}]}, "id": "2", "hanzi": "一辈子", "pinyin": "yí bèi zi", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the entire duration of a human lifespan; a lifetime", "definition_es": "toda la vida; la vida entera de una persona", "example_phrase": "辛苦了一辈子 (worked hard all one's life)"}, {"sense_number": "2", "part_of_speech": "Adverb", "register": "Colloquial", "definition_en": "forever; for a lifetime (used to express deep commitment or unchanging state)", "definition_es": "para toda la vida; eternamente", "example_phrase": "记一辈子 (remember for a lifetime)"}], "example_sentences": [{"id": "#1", "hanzi": "父母在农村辛苦劳作了一辈子，终于在儿女成家后过上了安稳舒适的晚年生活。", "pinyin": "Fùmǔ zài nóngcūn xīnkǔ láozuò le yíbèizi, zhōngyú zài énnǚ chéngjiā hòu guò shàng le ānwěn shūshì de wǎnnián shēnghuó.", "en": "Having toiled in the countryside all their lives, the parents finally enjoyed a peaceful, comfortable old age after their children started families.", "es": "Habiendo trabajado duro en el campo toda su vida, los padres al fin disfrutaron de una vejez tranquila y cómoda tras casarse sus hijos."}, {"id": "#2", "hanzi": "一位优秀的工匠往往倾注一辈子的心血，只为将一门传统手艺传承并做到极致。", "pinyin": "Yí wèi yōuxiù de gōngjiàng wǎngwǎng qīngzhù yíbèizi de xīnxuè, zhǐ wèi jiāng yì mén chuántǒng shǒuyì chuánchéng bìng zuò dào jízhì.", "en": "A master craftsman often devotes a lifetime of effort solely to preserving and perfecting a single traditional craft.", "es": "Un maestro artesano a menudo consagra el esfuerzo de toda una vida solo para preservar y perfeccionar un oficio tradicional."}], "collocations": [{"hanzi": "辛苦一辈子", "en": "work hard all one's life"}, {"hanzi": "过一辈子", "en": "spend one's whole life"}, {"hanzi": "一辈子的幸福", "en": "a lifetime of happiness"}, {"hanzi": "爱一辈子", "en": "love for a lifetime"}, {"hanzi": "一辈子的心血", "en": "a lifetime of dedicated effort"}, {"hanzi": "受用一辈子", "en": "benefit for a lifetime"}], "idioms": [{"hanzi": "终生难忘", "pinyin": "zhōng shēng nán wàng", "meaning_en": "unforgettable for a lifetime; etched in memory forever"}, {"hanzi": "人才辈出", "pinyin": "rén cái bèi chū", "meaning_en": "talented people emerging in generation after generation"}, {"hanzi": "百代过客", "pinyin": "bǎi dài guò kè", "meaning_en": "transient travelers through a hundred generations; fleeting human life"}, {"hanzi": "承前启后", "pinyin": "chéng qián qǐ hòu", "meaning_en": "inherit the past and usher in the future across generations"}], "character_decomposition": [{"character": "一", "pinyin": "yī", "meaning_en": "one; single; whole", "meaning_es": "uno; único; entero", "radical": "一", "radical_meaning_en": "one / horizontal line", "meaning_component": "一 (the primal unity of heaven and earth)", "sound_component": "", "stroke_count": "1", "composition_type": "独体结构", "etymology_and_mnemonic": "The primordial horizontal stroke representing unified wholeness and singularity.", "visual_mnemonic_story_en": "A single unbroken horizon line (一) uniting earth and sky into a continuous whole.", "visual_mnemonic_story_es": "Una única línea horizontal continua (一) que une el cielo y la tierra.", "tone_mnemonic_anchor": "55", "cangjie": "M", "traditional": ""}, {"character": "辈", "pinyin": "bèi", "meaning_en": "generation; rank; lifetime", "meaning_es": "generación; rango; vida entera", "radical": "车", "radical_meaning_en": "cart / chariot", "meaning_component": "车 (line of carts denoting sequential generations)", "sound_component": "非 (fēi, phonetic marker)", "stroke_count": "12", "composition_type": "上下结构", "etymology_and_mnemonic": "Originally indicated a convoy of war chariots lined up sequentially, extended to ancestral generational tiers.", "visual_mnemonic_story_en": "Rows of carts (车) moving beneath parallel flags (非) represent ranks of ancestors advancing across generations.", "visual_mnemonic_story_es": "Filas de carros (车) bajo estandartes (非) representan generaciones sucesivas que avanzan en el tiempo.", "tone_mnemonic_anchor": "51", "cangjie": "LYSJ", "traditional": "輩"}, {"character": "子", "pinyin": "zi", "meaning_en": "noun suffix / offspring", "meaning_es": "sufijo nominal / hijo", "radical": "子", "radical_meaning_en": "child / infant", "meaning_component": "子 (pictograph of a swaddled infant)", "sound_component": "", "stroke_count": "3", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of a child with arms spread out wide and swaddled legs.", "visual_mnemonic_story_en": "A baby opening tiny arms wide (子), acting here as a lightweight colloquial noun suffix.", "visual_mnemonic_story_es": "Un pequeño bebé con los brazos extendidos (子), sirviendo aquí como sufijo nominal ligero.", "tone_mnemonic_anchor": "214", "cangjie": "ND", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "祖母在老屋的灶台前站了一辈子，柴火映红了她的笑脸。她总说，人这一辈子就像熬一锅粥，火候到了，滋味自然就出来了。那些漫长的岁月，都化作了饭菜里最深沉的关爱与温度。", "pinyin": "Zǔmǔ zài lǎowū de zàotái qián zhàn le yíbèizi, cháihuǒ yìng hóng le tā de xiàoliǎn. Tā zǒng shuō, rén zhè yíbèizi jiù xiàng áo yì guō zhōu, huǒhòu dào le, zīwèi zìrán jiù chūlái le. Nàxiē màncháng de suìyuè, dōu huàzuò le fàncài lǐ zuì shēnchén de guān'ài yǔ wēndù.", "en": "Grandmother stood before the hearth in the old house all her life, the fire glow warming her face. She often said a lifetime is like simmering porridge; when the heat is right, flavor emerges naturally. Those long years dissolved into deep affection and warmth in every meal.", "es": "Mi abuela pasó toda su vida ante el fogón de la casa vieja, con el rostro iluminado por las llamas. Decía que la vida es como cocer gachas a fuego lento: cuando el tiempo madura, brota el sabor. Esos largos años se transformaron en amor hondo en cada plato."}, {"id": "#2", "hanzi": "社会学研究表明，现代人对“一辈子”的职业规划正在发生深刻重构。与过去依靠单一单位度过终生不同，当代青年更倾向于多维度发展技能。终身学习已从一种理想愿景转化为个体应对时代变革的核心生存策略。", "pinyin": "Shèhuìxué yánjiū biǎomíng, xiàndài rén duì \"yíbèizi\" de zhíyè guīhuà zhèngzài fāshēng shēnkè chónggòu. Yǔ guòqù yīkào dānyī dānwèi dùguò zhōngshēng bùtóng, dāngdài qīngnián gèng qīngxiàng yú duō wéidù fāzhǎn jìnéng. Zhōngshēn xuéxí yǐ cóng yì zhǒng lǐxiǎng yuànjǐng zhuǎnhuà wéi gètǐ yìngduì shídài biàngé de héxīn shēngcún cèlüè.", "en": "Sociological research shows that modern people's lifelong career planning is undergoing profound restructuring. Unlike past generations relying on a single employer for life, today's youth favor multidimensional skill building. Lifelong learning has shifted from an ideal into a core survival strategy.", "es": "Los estudios sociológicos muestran que el proyecto profesional de toda una vida se transforma profundamente. Lejos de la fidelidad a una sola empresa, los jóvenes actuales diversifican competencias. El aprendizaje continuo ha pasado de aspiración a estrategia vital imprescindible."}]}, {"meanings_summary": {"en": "countryside; rural area; village community", "es": "campo; zona rural; aldea campesina"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Farmers cultivating the land (农) amidst wooden woodland cottages (村) form the peaceful countryside (农村).", "composite_memory_hook_es": "Campesinos cultivando la tierra (农) entre chozas de madera (村) componen el pacífico campo (农村).", "cultural_and_cognitive_roots": "China's historic agrarian civilization views the 'nóngcūn' not merely as land, but as the moral wellspring and emotional bedrock of ancestor veneration, kinship hospitality, and organic seasonal harmony.", "tone_sandhi_and_pitch_modulation": "Pronounced with a 35-55 pitch contour (2nd tone rising steadily, followed by 1st tone high and level). Maintain clear tonal elevation on 'cūn'."}, "semantic_boundary_contrasts": {"core_nuance": "农村 refers broadly to the socio-economic rural geographic realm opposite to cities (城市).", "contrasts": [{"id": "1", "compared_word": "农村 vs. 乡村", "pinyin": "xiāngcūn", "analysis": "农村 focuses on agricultural production, socio-economic demography, and administrative designation, whereas 乡村 emphasizes idyllic scenery, rustic nostalgia, and pastoral tranquility."}, {"id": "2", "compared_word": "农村 vs. 郊区", "pinyin": "jiāoqū", "analysis": "农村 refers to distant agricultural land and peasant villages, while 郊区 denotes the suburban fringe surrounding a metropolis."}, {"id": "3", "compared_word": "农村 vs. 乡镇", "pinyin": "xiāngzhèn", "analysis": "农村 encompasses sprawling agricultural fields and farming communities, whereas 乡镇 refers specifically to administrative townships and commercial market towns in rural regions."}]}, "traps_and_cognates": {"look_alikes": [{"character": "材", "pinyin": "cái", "meaning_en": "timber; talent", "distinction_note": "Has 才 (talent) on the right instead of 寸 (inch)"}, {"character": "付", "pinyin": "fù", "meaning_en": "pay; hand over", "distinction_note": "Has 亻 (person) radical on the left with 寸 on the right"}, {"character": "衣", "pinyin": "yī", "meaning_en": "clothes; garment", "distinction_note": "Top dot and horizontal line resemble simplified 农 upper strokes"}, {"character": "树", "pinyin": "shù", "meaning_en": "tree; plant", "distinction_note": "Contains 木 on left and 寸 on right, but intercalates 又 in the center"}], "etymological_cognates": [{"character": "农业", "pinyin": "nóng yè", "gloss_en": "agriculture; agricultural industry"}, {"character": "农民", "pinyin": "nóng mín", "gloss_en": "farmer; peasant"}, {"character": "乡村", "pinyin": "xiāng cūn", "gloss_en": "countryside; rural village"}, {"character": "村落", "pinyin": "cūn luò", "gloss_en": "rustic hamlet; rural settlement"}]}, "id": "3", "hanzi": "农村", "pinyin": "nóng cūn", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "rural area; agricultural region populated by farming households", "definition_es": "campo; área rural habitada por campesinos dedicados al agro", "example_phrase": "建设社会主义新农村 (build a socialist new countryside)"}], "example_sentences": [{"id": "#1", "hanzi": "每到周末，许多城里人都喜欢驾车前往周边的农村，呼吸新鲜空气并品尝农家菜肴。", "pinyin": "Měi dào zhōumò, xǔduō chénglǐ rén dōu xǐhuan jiàchē qiánwǎng zhōubiān de nóngcūn, hūxī xīnxiān kōngqì bìng pǐncháng nóngjiā càiyáo.", "en": "Every weekend, many urban residents love driving to nearby rural areas to breathe fresh air and savor farm-style dishes.", "es": "Cada fin de semana, muchos habitantes urbanos disfrutan conduciendo al campo cercano para respirar aire puro y degustar comida campesina."}, {"id": "#2", "hanzi": "近年来，国家加大对农村基础设施和教育资源的投入，有力推动了城乡一体化融合发展。", "pinyin": "Jìnnián lái, guójiā jiàdà duì nóngcūn jīchǔ shèshī hé jiàoyù zīyuán de tóurù, yǒulì tuīdòng le chéng-xiāng yìtǐhuà rónghé fāzhǎn.", "en": "In recent years, the state has boosted investment in rural infrastructure and educational resources, vigorously promoting urban-rural integration.", "es": "En los últimos años, el Estado ha incrementado la inversión en infraestructura y educación rural, impulsando la integración equilibrada de campo y ciudad."}], "collocations": [{"hanzi": "广大农村", "en": "vast countryside"}, {"hanzi": "农村人口", "en": "rural population"}, {"hanzi": "农村改革", "en": "rural reform"}, {"hanzi": "离开农村", "en": "leave the countryside"}, {"hanzi": "回到农村", "en": "return to the rural village"}, {"hanzi": "农村生活", "en": "countryside life"}], "idioms": [{"hanzi": "柳暗花明", "pinyin": "liǔ àn huā míng", "meaning_en": "dark willows and bright flowers; a promising turn after despair, reminiscent of rural paths"}, {"hanzi": "鸡犬相闻", "pinyin": "jī quǎn xiāng wén", "meaning_en": "crowing cocks and barking dogs heard all around; idyllic, peaceful village life"}, {"hanzi": "世外桃源", "pinyin": "shì wài táo yuán", "meaning_en": "the Peach Blossom Spring; idyllic, secluded haven away from worldly turmoil"}, {"hanzi": "晴耕雨读", "pinyin": "qíng gēng yǔ dú", "meaning_en": "plow when it's sunny and read when it rains; idyllic agrarian intellectual lifestyle"}], "character_decomposition": [{"character": "农", "pinyin": "nóng", "meaning_en": "agriculture; farming; peasant", "meaning_es": "agricultura; cultivar; campesino", "radical": "冖", "radical_meaning_en": "crown / cover", "meaning_component": "辰 (agricultural calendar / hoe implement)", "sound_component": "曲 (simplified phonetic contour)", "stroke_count": "6", "composition_type": "独体结构", "etymology_and_mnemonic": "Derived from ancient oracle script showing hands holding a tool to clear agricultural land during auspicious season (辰).", "visual_mnemonic_story_en": "A farmer under the morning sky (冖) bends over the field cultivating crops according to the seasons.", "visual_mnemonic_story_es": "Un agricultor bajo el cobertizo (冖) inclina su espalda para cultivar la tierra según el ciclo natural.", "tone_mnemonic_anchor": "35", "cangjie": "BHV", "traditional": "農"}, {"character": "村", "pinyin": "cūn", "meaning_en": "village; rustic settlement", "meaning_es": "aldea; poblado rural", "radical": "木", "radical_meaning_en": "tree / wood", "meaning_component": "木 (trees surrounding early settlements)", "sound_component": "寸 (cùn, inch / hand measurement)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where trees (木) represent natural shelter enclosing small settlements, with phonetic 寸.", "visual_mnemonic_story_en": "A cluster of wooden cottages (木) measured out carefully inch by inch (寸) forms a rural hamlet.", "visual_mnemonic_story_es": "Cabañas de madera (木) levantadas palmo a palmo (寸) en armonía con los árboles forman una aldea.", "tone_mnemonic_anchor": "55", "cangjie": "DDI", "traditional": "村"}], "extended_reading_passages": [{"id": "#1", "hanzi": "走在农村蜿蜒的田埂上，鼻尖总能嗅到泥土与青草混合的清香。远处的炊烟在落日余晖中袅袅升起，老人们坐在门槛上亲切交谈。这种淳朴悠缓的节奏，让久居喧嚣的人心神宁静。", "pinyin": "Zǒu zài nóngcūn wānyán de tiángěng shàng, bíjiān zǒng néng xiù dào nítǔ yǔ qīngcǎo hùnhé de qīngxiāng. Yuǎnchù de chuīyān zài luòrì yúhuī zhōng niǎoniǎo shēngqǐ, lǎorénmen zuò zài ménkǎn shàng qīnqiè jiāotán. Zhè zhǒng chúnpǔ yōuhuǎn de jiézòu, ràng jiǔjū xuānxiāo de rén xīnshén níngjìng.", "en": "Walking along winding field ridges in the countryside, one always breathes in the fresh aroma of earth and wild grass. Distant cooking smoke curls gently into the sunset as elders chat warmly on doorways. This unhurried rustic rhythm brings profound peace to restless urban minds.", "es": "Al caminar por los senderos serpenteantes del campo, se percibe el aroma fresco a tierra y hierba. El humo de las cocinas asciende suavemente en el ocaso mientras los ancianos charlan en los umbrales. Este compás sereno apacigua el espíritu agitado por la vida urbana."}, {"id": "#2", "hanzi": "伴随数字乡村建设的推进，中国农村展现出全新的发展面貌。电子商务让深山农特产品销往全国，现代农业科技提升了产出效益。农村正由传统的劳动力输出地，逐步转变为充满活力的创新创业沃土。", "pinyin": "Bànsuí shùzì xiāngcūn jiànshè de tuījìn, Zhōngguó nóngcūn zhǎnxiàn chū quánxīn de fāzhǎn miànmào. Diànzǐ shāngwù ràng shēnshān nóngtè chǎnpǐn xiāowǎng quánguó, xiàndài nóngyè kējì tíshēng le chǎnchū xiàoyì. Nóngcūn zhèng yóu chuántǒng de láodònglì shūchūdì, zhúbù zhuǎnbiàn wéi chōngmǎn huólì de chuàngxīn chuàngyè wòtǔ.", "en": "Driven by digital village initiatives, rural China presents a vibrant new development landscape. E-commerce connects specialty produce from remote mountains to nationwide markets, while agritech improves efficiency. The countryside is transforming from a labor exporter into fertile ground for entrepreneurship.", "es": "Con el avance de las aldeas digitales, el campo chino muestra una faz renovada. El comercio electrónico distribuye productos autóctonos a todo el país y la tecnología eleva la productividad. El medio rural deja de ser mero emisor de mano de obra para convertirse en foco de innovación."}]}, {"meanings_summary": {"en": "room; house; small building", "es": "habitación; cuarto; casa; vivienda"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Arriving (至) under a shelter frame (尸) with the family child (子) forms a warm and livable room (屋子).", "composite_memory_hook_es": "Llegar (至) bajo un tejado protector (尸) junto al niño (子) da lugar a una habitación acogedora (屋子).", "cultural_and_cognitive_roots": "In traditional Chinese vernacular culture, 'wū' is the intimate hearth where bodily shelter and family affection coalesce, distinguishing concrete emotional refuge from formal architectural facades.", "tone_sandhi_and_pitch_modulation": "Pronounced with high level tone followed by a light neutral tone: 'wū zi' (55-0). Do not pronounce 'zi' with an emphatic 3rd tone contour."}, "semantic_boundary_contrasts": {"core_nuance": "屋子 is an informal, vernacular everyday word for a physical enclosed domestic room or small dwelling.", "contrasts": [{"id": "1", "compared_word": "屋子 vs. 房间", "pinyin": "fángjiān", "analysis": "屋子 is colloquial and paints a vivid domestic living scene, whereas 房间 is the neutral standard term used in hotels, formal descriptions, and architectural layouts."}, {"id": "2", "compared_word": "屋子 vs. 房屋", "pinyin": "fángwū", "analysis": "屋子 refers to specific interior rooms or a cozy private home, while 房屋 is formal and collective, denoting physical residential real estate or urban building structures."}, {"id": "3", "compared_word": "屋子 vs. 卧室", "pinyin": "wòshì", "analysis": "屋子 can denote any room or the whole cottage, whereas 卧室 is specifically designated as a bedroom for sleeping."}]}, "traps_and_cognates": {"look_alikes": [{"character": "居", "pinyin": "jū", "meaning_en": "dwell; reside", "distinction_note": "Has 古 (ancient) inside 尸 instead of 至"}, {"character": "层", "pinyin": "céng", "meaning_en": "layer; floor", "distinction_note": "Has 云 (cloud) inside 尸 instead of 至"}, {"character": "屏", "pinyin": "píng", "meaning_en": "screen; shield", "distinction_note": "Has 并 (combine) inside 尸 instead of 至"}, {"character": "屁", "pinyin": "pì", "meaning_en": "flatulence; fart", "distinction_note": "Has 比 (compare) inside 尸 instead of 至"}], "etymological_cognates": [{"character": "房间", "pinyin": "fáng jiān", "gloss_en": "room; chamber"}, {"character": "房屋", "pinyin": "fáng wū", "gloss_en": "house; building; real estate"}, {"character": "木屋", "pinyin": "mù wū", "gloss_en": "wooden cabin; log cabin"}, {"character": "同屋", "pinyin": "tóng wū", "gloss_en": "roommate; cabin mate"}]}, "id": "4", "hanzi": "屋子", "pinyin": "wū zi", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "an enclosed room within a dwelling", "definition_es": "habitación; cuarto en una vivienda", "example_phrase": "走进屋子 (walk into the room)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Colloquial", "definition_en": "an entire house or cottage dwelling", "definition_es": "casa; casita; vivienda", "example_phrase": "盖了一座新屋子 (built a new house)"}], "example_sentences": [{"id": "#1", "hanzi": "母亲把屋子收拾得干干净净，窗台上还摆放着几盆绿意盎然的盆栽，让人倍感温馨。", "pinyin": "Mǔqīn bǎ wūzi shōushi de gāngānjìngjìng, chuāngtái shàng hái bǎifàng zhe jǐ pén lǜyì àngrán de pénzāi, ràng rén bèi gǎn wēnxīn.", "en": "Mother tidied the room spotless, and several lush potted plants on the windowsill made everyone feel exceptionally warm.", "es": "Mi madre dejó la habitación impecable, y varias macetas verdes en el alféizar creaban una atmósfera sumamente acogedora."}, {"id": "#2", "hanzi": "冬天窗外北风呼啸，但屋子里生着旺旺的炉火，一家人围坐在一起谈笑风生。", "pinyin": "Dōngtiān chuāngwài běifēng hūxiào, dàn wūzi lǐ shēng zhe wàngwàng de lúhuǒ, yì jiā rén wéizuò zài yìqǐ tánxiàofēngshēng.", "en": "In winter the north wind roared outside the window, but a brisk stove fire burned inside the room where the family sat chatting merrily.", "es": "En invierno el viento del norte rugía tras la ventana, pero en la habitación ardía la estufa y la familia charlaba animadamente reunida."}], "collocations": [{"hanzi": "收拾屋子", "en": "tidy up the room"}, {"hanzi": "满屋子", "en": "the entire room; whole room full of"}, {"hanzi": "进屋子", "en": "enter the house / room"}, {"hanzi": "屋子里", "en": "inside the room"}, {"hanzi": "空屋子", "en": "empty room"}, {"hanzi": "租屋子", "en": "rent a room / house"}], "idioms": [{"hanzi": "爱屋及乌", "pinyin": "ài wū jí wū", "meaning_en": "love for the house extends to the crow on the roof; love me, love my dog"}, {"hanzi": "屋上建瓴", "pinyin": "wū shàng jiàn líng", "meaning_en": "pour water from high roof tiles; operate from an overwhelmingly advantageous position"}, {"hanzi": "金屋藏娇", "pinyin": "jīn wū cáng jiāo", "meaning_en": "shelter a beauty in a gilded mansion; provide a luxurious haven for one's beloved"}, {"hanzi": "引狼入室", "pinyin": "yǐn láng rù shì", "meaning_en": "lead a wolf into the room; introduce a dangerous element into one's inner sanctum"}], "character_decomposition": [{"character": "屋", "pinyin": "wū", "meaning_en": "room; house; roof", "meaning_es": "habitación; casa; tejado", "radical": "尸", "radical_meaning_en": "corpse / reclining body / shelter", "meaning_component": "尸 (shelter frame)", "sound_component": "至 (zhì, arrive / reach)", "stroke_count": "9", "composition_type": "半包围结构", "etymology_and_mnemonic": "Ideogrammic and phono-semantic compound where a resting body (尸) reaches destination (至) under a roof.", "visual_mnemonic_story_en": "A person seeking rest reaches (至) shelter under a protective wooden roof frame (尸), creating a cozy room.", "visual_mnemonic_story_es": "Una persona llega (至) a guarecerse bajo el techo protector (尸) para descansar en una cálida habitación.", "tone_mnemonic_anchor": "55", "cangjie": "SMGI", "traditional": "屋"}, {"character": "子", "pinyin": "zi", "meaning_en": "noun suffix", "meaning_es": "sufijo nominal", "radical": "子", "radical_meaning_en": "child / infant", "meaning_component": "子 (infant pictograph)", "sound_component": "", "stroke_count": "3", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of a child, serving as a softening phonetic suffix in modern vernacular nouns.", "visual_mnemonic_story_en": "A tiny baby (子) serving as an everyday conversational affix attached to living objects and spaces.", "visual_mnemonic_story_es": "Una pequeña figura infantil (子) que actúa como sufijo coloquial cotidiano en sustantivos.", "tone_mnemonic_anchor": "214", "cangjie": "ND", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "无论是简陋的茅草房还是宽敞的楼房，只要有亲人在，屋子里就会弥漫着烟火气。每当黄昏归家，推开那扇熟悉的木门，扑面而来的饭菜香气总能抚平一整天的疲惫，让人安然入梦。", "pinyin": "Wúlùn shì jiǎnlòu de máocǎofáng háishì kuānchǎng de lóufáng, zhǐyào yǒu qīnrén zài, wūzi lǐ jiù huì mímàn zhe yānhuǒqì. Měidāng huánghūn guījiā, tuīkāi nà shàn shúxī de mùmén, pūmiàn ér lái de fàncài xiāngqì zǒng néng fǔpíng yì zhěng tiān de píbèi, ràng rén ānrán rùmèng.", "en": "Whether a rustic thatched hut or a spacious apartment, as long as loved ones are there, the room fills with the warmth of living. Opening that familiar wooden door at dusk, welcoming aromas of dinner dissolve exhaustion, inviting sweet dreams.", "es": "Sea una humilde choza o un piso amplio, mientras esté la familia, la habitación rebosa de vida entrañable. Al volver al anochecer y abrir la puerta familiar, los reconfortantes aromas culinarios disipan el cansancio e invitan al sosiego."}, {"id": "#2", "hanzi": "传统民居的空间布局蕴含着深刻的中国宗族伦理。正厅用于待客与祭祖，厢房则作为晚辈日常居住的屋子。这种等级分明的建筑形制，不仅反映了家庭内部的长幼有序，更强化了血缘纽带与道德规约。", "pinyin": "Chuántǒng mínjū de kōngjiān bùjú yùnhán zhe shēnkè de Zhōngguó zōngzú lúnlǐ. Zhèngtīng yòngyú dàikè yǔ jìzǔ, xiāngfáng zé zuòwéi wǎnbèi rìcháng jūzhù de wūzi. Zhè zhǒng děngjí fēnmíng de jiànzhù xíngzhì, bùjǐn fǎnyìng le jiātíng nèibù de zhǎngyòuyǒuxù, gèng qiánghuà le xiěyuán niǔdài yǔ dàodé guīyuē.", "en": "The spatial layout of traditional dwellings reflects Chinese ancestral ethics. The central hall hosted guests and rituals, while wing rooms served as living quarters for juniors. This hierarchical architecture reinforced generational respect and moral norms within the clan.", "es": "La disposición de las viviendas vernáculas refleja la ética familiar tradicional. El salón principal acogía rituales, y las estancias laterales eran habitaciones para los jóvenes. Esta estructura jerárquica fortalecía el respeto generacional y los lazos de linaje."}]}, {"meanings_summary": {"en": "to break; to snap; to cut off; to sever; to stop; to judge", "es": "romper; quebrar; cortar; suspender; juzgar; decidir"}, "mnemonics_and_roots": {"composite_memory_hook_en": "An axe (斤) swings down to slice through fibers and cleanly sever (断) the thread.", "composite_memory_hook_es": "Un hacha (斤) cae con fuerza para cortar las hebras y quebrar (断) el hilo de forma tajante.", "cultural_and_cognitive_roots": "In ancient Chinese legal and philosophical thought, 'duàn' originated from cutting physical cords to resolve disputes, evolving into the mental capacity to reach decisive judgments (决断).", "tone_sandhi_and_pitch_modulation": "Pronounced in the 4th tone with an abrupt, decisive downward pitch (51). When forming '不断', '不' undergoes tone sandhi to 2nd tone: 'bú duàn' (35-51)."}, "semantic_boundary_contrasts": {"core_nuance": "断 refers to an abrupt physical snapping or sudden cessation of continuity in time, relationship, or supply.", "contrasts": [{"id": "1", "compared_word": "断 vs. 停", "pinyin": "tíng", "analysis": "断 emphasizes complete physical breakage or rupture of a continuous link (e.g. 绳子断了, 断电), whereas 停 implies pausing or coming to rest with the potential to resume (e.g. 停车, 停雨)."}, {"id": "2", "compared_word": "断 vs. 破", "pinyin": "pò", "analysis": "断 denotes dividing an elongated object into discrete parts along its length, while 破 means shattering, tearing, or puncturing a surface (e.g. 衣服破了, 碗摔破了)."}, {"id": "3", "compared_word": "断 vs. 截", "pinyin": "jié", "analysis": "断 highlights the state of disruption or severance, whereas 截 emphasizes the deliberate physical action of cutting a section off or intercepting (e.g. 截断, 截获)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "折", "pinyin": "zhé", "meaning_en": "break; bend; fold", "distinction_note": "Has 扌 (hand) on the left instead of silk bundle remnants"}, {"character": "析", "pinyin": "xī", "meaning_en": "analyze; split wood", "distinction_note": "Has 木 (wood) on left with 斤 (axe) on right"}, {"character": "斩", "pinyin": "zhǎn", "meaning_en": "behead; chop off", "distinction_note": "Has 车 (chariot) on left with 斤 on right"}, {"character": "斤", "pinyin": "jīn", "meaning_en": "axe / half-kilogram", "distinction_note": "The standalone right radical of 断 without the left component"}], "etymological_cognates": [{"character": "折断", "pinyin": "zhé duàn", "gloss_en": "snap; break into pieces"}, {"character": "割断", "pinyin": "gē duàn", "gloss_en": "cut off; sever with a blade"}, {"character": "间断", "pinyin": "jiàn duàn", "gloss_en": "be interrupted; intermittent"}, {"character": "决断", "pinyin": "jué duàn", "gloss_en": "make a resolute decision; resolution"}]}, "id": "5", "hanzi": "断", "pinyin": "duàn", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to physically snap, break in two, or sever", "definition_es": "romperse; partirse en dos; quebrar", "example_phrase": "绳子断了 (the rope snapped)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to cut off, interrupt, or discontinue (relations, supply, habit)", "definition_es": "cortar; interrumpir; suspender", "example_phrase": "断绝往来 (sever contacts)"}, {"sense_number": "3", "part_of_speech": "Verb", "register": "Formal", "definition_en": "to judge; to determine; to arbitrate", "definition_es": "juzgar; dictaminar; resolver un litigio", "example_phrase": "判断是非 (judge right from wrong)"}], "example_sentences": [{"id": "#1", "hanzi": "暴风雨刮断了村口的几根电线，导致全村的电力供应中断了大半天。", "pinyin": "Bàofēngyǔ guā duàn le cūnkǒu de jǐ gēn diànxiàn, dǎozhì quán cūn de diànlì gōngyìng zhōngduàn le dàbàntiān.", "en": "The rainstorm snapped several power lines at the village entrance, causing electricity across the village to be interrupted for half a day.", "es": "La tormenta partió varios cables eléctricos a la entrada del pueblo, interrumpiendo el suministro eléctrico durante más de medio día."}, {"id": "#2", "hanzi": "无论离家多远、工作多忙，游子与故乡亲人之间的思念与牵挂永远都不会断。", "pinyin": "Wúlùn líjiā duō yuǎn, gōngzuò duō máng, yóuzǐ yǔ gùxiāng qīnrén zhījiān de sīniàn yǔ qiānguà yǒngyuǎn dōu bú huì duàn.", "en": "No matter how far one wanders or how busy work becomes, the affection and yearning between travelers and kin back home will never break.", "es": "Por lejos que se marche o por ocupado que esté el trabajo, el cariño y la añoranza entre el viajero y sus seres queridos nunca se romperán."}], "collocations": [{"hanzi": "中断", "en": "interrupt; suspend"}, {"hanzi": "不断", "en": "continuously; incessantly"}, {"hanzi": "断绝", "en": "sever; break off completely"}, {"hanzi": "推断", "en": "infer; deduce"}, {"hanzi": "断定", "en": "conclude; determine with certainty"}, {"hanzi": "断线", "en": "disconnected; broken line"}], "idioms": [{"hanzi": "藕断丝连", "pinyin": "ǒu duàn sī lián", "meaning_en": "lotus roots snap but fibers remain joined; lingering attachment despite separation"}, {"hanzi": "当机立断", "pinyin": "dāng jī lì duàn", "meaning_en": "make a prompt decision at the critical moment"}, {"hanzi": "源源不断", "pinyin": "yuán yuán bú duàn", "meaning_en": "flowing in a continuous, endless stream"}, {"hanzi": "优柔寡断", "pinyin": "yōu róu guǎ duàn", "meaning_en": "indecisive; hesitant and irresolute"}], "character_decomposition": [{"character": "断", "pinyin": "duàn", "meaning_en": "break; snap; sever; decide", "meaning_es": "romper; quebrar; cortar; decidir", "radical": "斤", "radical_meaning_en": "axe / adze", "meaning_component": "斤 (axe used for severing)", "sound_component": "𢆶 (silk skeins on left)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Depicts bundles of silk threads being cleaved in half by a sharp iron axe (斤).", "visual_mnemonic_story_en": "An axe (斤) chops down forcefully, severing twisted threads on the left into two separate halves.", "visual_mnemonic_story_es": "Un hacha afilada (斤) desciende cortando de un solo golpe los hilos trenzados de la izquierda.", "tone_mnemonic_anchor": "51", "cangjie": "VIDH", "traditional": "斷"}], "extended_reading_passages": [{"id": "#1", "hanzi": "游子离家千万里，但心中的牵挂宛如风筝的线，无论岁月怎样流转，也未曾真正断开。每当夜深人静仰望星空，母亲慈祥的目光仿佛穿越山海，将游子与故乡紧紧连在一起。", "pinyin": "Yóuzǐ líjiā qiānwàn lǐ, dàn xīnzhōng de qiānguà wǎnrú fēngzheng de xiàn, wúlùn suìyuè zěnyàng liúzhuǎn, yě wèicéng zhēnzhèng duànkāi. Měidāng yèshēn-rénjìng yǎngwàng xīngkōng, mǔqīn cíxiáng de mùguāng fǎngrú chuānyuè shānhǎi, jiāng yóuzǐ yǔ gùxiāng jǐnjǐn lián zài yìqǐ.", "en": "Wandering thousands of miles from home, one's thoughts resemble a kite string that never truly snaps, however years roll by. Gazing at stars in the silent night, mother's loving gaze traverses mountains and seas, binding traveler and home together.", "es": "Aunque el viajero marche a miles de leguas, el lazo afectivo es un hilo de cometa que el tiempo jamás logra quebrar. En la noche silenciosa mirando las estrellas, la mirada tierna de la madre cruza montes y mares, uniendo al hijo con su tierra."}, {"id": "#2", "hanzi": "现代城市供电与水务系统高度依赖智能调度网络。一旦关键枢纽发生物理损坏导致供电中断，应急机制将瞬间启动自愈算法，在毫秒级时间内重配路由，确保核心基础设施稳定运行。", "pinyin": "Xiàndài chéngshì gōngdiàn yǔ shuǐwù xìtǒng gāodù yīlài zhìnéng diàodù wǎngluò. Yídàn guānjiàn shūniǔ fāshēng wùlǐ sǔnhuài dǎozhì gōngdiàn zhōngduàn, yìngjí jīzhì jiāng shùnjiān qǐdòng zìyù suànfǎ, zài háomiǎo jí shíjiān nèi chóngpèi lùyóu, quèbǎo héxīn jīchǔ shèshī wěndìng yùnxíng.", "en": "Modern municipal power and water grids rely heavily on smart dispatch networks. If physical damage at a critical hub interrupts electrical supply, emergency mechanisms instantaneously trigger self-healing algorithms within milliseconds, re-routing power.", "es": "Las redes de abastecimiento urbano dependen de la gestión inteligente. Si un daño en un nudo clave interrumpe el suministro eléctrico, los protocolos de emergencia activan algoritmos de autorrecuperación en milisegundos para garantizar los servicios vitales."}]}, {"meanings_summary": {"en": "since (a past time); ever since; from... until now", "es": "desde (hace); a partir de entonces; desde aquel momento"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Taking a past moment as reference (以), time continuously flows forward and arrives (来) into the present (以来).", "composite_memory_hook_es": "Tomando un punto temporal de partida (以), el tiempo fluye y llega (来) hasta el presente (以来).", "cultural_and_cognitive_roots": "In classical Chinese cosmology, time is experienced as an ongoing arrival from ancestors to posterity; 'yǐlái' establishes a spatial-temporal continuum uniting history directly to current lived experience.", "tone_sandhi_and_pitch_modulation": "Pronounced with a 214-35 pitch contour (3rd tone dipping then rising smoothly, followed by 2nd tone rising cleanly). Keep the transition between syllables fluid."}, "semantic_boundary_contrasts": {"core_nuance": "以来 acts as a postposition indicating continuous elapsed duration starting from an event up to the present moment.", "contrasts": [{"id": "1", "compared_word": "以来 vs. 以后", "pinyin": "yǐhòu", "analysis": "以来 marks duration extending continuously from a past milestone all the way to now (e.g. 去年以来), whereas 以后 simply denotes the period after a specific event without requiring continuity to the present (e.g. 下课以后, 毕业以后)."}, {"id": "2", "compared_word": "以来 vs. 至今", "pinyin": "zhìjīn", "analysis": "以来 is placed after a noun or clause indicating the starting boundary (e.g. 结婚以来), while 至今 stands alone as a time adverb meaning 'to this day' or 'up until now' (e.g. 至今未归)."}, {"id": "3", "compared_word": "以来 vs. 自从", "pinyin": "zìcóng", "analysis": "自从 is a preposition placed before the clause or time point (e.g. 自从他离家), whereas 以来 is attached as a suffix at the end of the phrase (often paired: 自从……以来)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "已", "pinyin": "yǐ", "meaning_en": "already; stop", "distinction_note": "Closed at the top unlike 以 which has two distinct left and right components"}, {"character": "似", "pinyin": "sì", "meaning_en": "resemble; similar", "distinction_note": "Has 亻 (person) radical on the left with 以 on the right"}, {"character": "夹", "pinyin": "jiā", "meaning_en": "squeeze; clip;夾", "distinction_note": "Resembles 来 in overall simplified contour but lacks the upper horizontal canopy"}, {"character": "米", "pinyin": "mǐ", "meaning_en": "rice; meter", "distinction_note": "Resembles the lower half of 来 but lacks the upper horizontal bar"}], "etymological_cognates": [{"character": "以后", "pinyin": "yǐ hòu", "gloss_en": "after; afterwards; in the future"}, {"character": "以前", "pinyin": "yǐ qián", "gloss_en": "before; formerly; previously"}, {"character": "来历", "pinyin": "lái lì", "gloss_en": "origin; antecedent; background"}, {"character": "历来", "pinyin": "lì lái", "gloss_en": "always; through all ages"}]}, "id": "6", "hanzi": "以来", "pinyin": "yǐ lái", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "period following a specified starting point up to the present; ever since", "definition_es": "tiempo transcurrido desde un momento inicial hasta ahora", "example_phrase": "改革开放以来 (since the reform and opening up)"}], "example_sentences": [{"id": "#1", "hanzi": "搬到县城的新房以来，母亲总挂念着老家的菜园和那几只散养的母鸡。", "pinyin": "Bān dào xiànchéng de xīnfáng yǐlái, mǔqīn zǒng guàniàn zhe lǎojiā de càiyuán hé nà jǐ zhī sǎnyǎng de mǔjī.", "en": "Ever since moving to the new apartment in the county seat, mother constantly misses her vegetable garden and free-range hens back home.", "es": "Desde que nos mudamos al piso del pueblo, mi madre no deja de añorar su huerto y las gallinas camperas de la aldea."}, {"id": "#2", "hanzi": "自去年两国签署全面战略经贸协议以来，双边货物进出口总额实现了跨越式增长。", "pinyin": "Zì qùnián liǎng guó qiānshǔ quánmiàn zhànlüè jīngmào xiéyì yǐlái, shuāngbiān huòwù jìnchūkǒu zǒng'é shíxiàn le kuàyuè shì zēngzhǎng.", "en": "Ever since the two nations signed the comprehensive strategic trade pact last year, bilateral import-export volume has achieved leapfrog growth.", "es": "Desde que ambos países firmaron el acuerdo estratégico integral el año pasado, el volumen comercial bilateral ha crecido exponencialmente."}], "collocations": [{"hanzi": "长期以来", "en": "for a long time past"}, {"hanzi": "一直以来", "en": "all along; ever since"}, {"hanzi": "改革开放以来", "en": "since the reform and opening up"}, {"hanzi": "建厂以来", "en": "since the factory was founded"}, {"hanzi": "自古以来", "en": "since ancient times"}, {"hanzi": "有生以来", "en": "since birth; in all one's life"}], "idioms": [{"hanzi": "自古以来", "pinyin": "zì gǔ yǐ lái", "meaning_en": "since ancient times; throughout history"}, {"hanzi": "古往今来", "pinyin": "gǔ wǎng jīn lái", "meaning_en": "from ancient times to the present; down the ages"}, {"hanzi": "日往月来", "pinyin": "rì wǎng yuè lái", "meaning_en": "days depart and months arrive; the swift passage of time"}, {"hanzi": "源远流长", "pinyin": "yuán yuǎn liú cháng", "meaning_en": "having a distant source and long stream; deep-rooted and enduring"}], "character_decomposition": [{"character": "以", "pinyin": "yǐ", "meaning_en": "with; by means of; take from", "meaning_es": "mediante; con; a partir de", "radical": "人", "radical_meaning_en": "person / human", "meaning_component": "厶/人 (holding or using an implement)", "sound_component": "", "stroke_count": "4", "composition_type": "左右结构", "etymology_and_mnemonic": "Ancient pictograph of a person holding an agricultural implement, signifying 'taking this as an instrument or anchor'.", "visual_mnemonic_story_en": "A worker holding an instrument firmly in hand, using it as an established starting reference point.", "visual_mnemonic_story_es": "Un labrador empuñando una herramienta firme, tomándola como punto de partida y referencia.", "tone_mnemonic_anchor": "214", "cangjie": "VO", "traditional": ""}, {"character": "来", "pinyin": "lái", "meaning_en": "come; arrive; future", "meaning_es": "venir; llegar; futuro", "radical": "木", "radical_meaning_en": "tree / wood", "meaning_component": "禾 (cereal grain coming from heaven)", "sound_component": "一 (sky / origin)", "stroke_count": "7", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of wheat or cereal grain blowing in the wind, which came as a heaven-sent staple food to humanity.", "visual_mnemonic_story_en": "Wheat stalks swaying gracefully in the field, representing bountiful gifts that come from distant lands.", "visual_mnemonic_story_es": "Espigas de trigo que ondean con la brisa, representando los dones nutricios que llegan a los humanos.", "tone_mnemonic_anchor": "35", "cangjie": "DTI", "traditional": "來"}], "extended_reading_passages": [{"id": "#1", "hanzi": "自从搬离村庄以来，每逢秋雨绵绵的夜晚，母亲总会在灯下讲述过去的农事。那些关于麦浪与晚霞的记忆，在时光冲刷下愈发清晰，成为全家人心底最深沉的精神依托。", "pinyin": "Zìcóng bānlí cūnzhuāng yǐlái, měiféng qiūyǔ miánmián de yèwǎn, mǔqīn zǒng huì zài dēng xià jiǎngshù guòqù de nóngshì. Nàxiē guānyú màilàng yǔ wǎnxiá de jìyì, zài shíguāng chōngshuā xià yùfā qīngxī, chéngwéi quán jiā rén xīndǐ zuì shēnchén de jīngshén yītuō.", "en": "Ever since leaving the village, whenever autumn rain falls softly at night, mother sits beneath the lamp reminiscing about farming days. Those memories of wheat fields and glowing sunsets grow ever clearer, anchoring the whole family's spirit.", "es": "Desde que dejamos el pueblo, en las noches de lluvia otoñal, madre relata viejas labores agrícolas bajo la lámpara. Esos recuerdos de trigales dorados y crepúsculos se aclaran con el tiempo, convirtiéndose en el sostén afectivo de la familia."}, {"id": "#2", "hanzi": "伴随新一轮科技革命，该企业创立以来始终聚焦核心工业芯片的自主研制。历经十余年技术攻关，团队突破多项国际技术封锁，形成了覆盖设计制造全流程的完整产业链体系，为国家制造业转型筑牢了基石。", "pinyin": "Bànsuí xīn yì lún kējì gémìng, gāi qǐyè chuànglì yǐlái shǐzhōng jùjiāo héxīn gōngyè xīnpiàn de zìzhǔ yánzhì. Lìjīng shí yú nián jìshù gōngguān, tuánduì tūpò duō xiàng guójì jìshù fēngsuǒ, xíngchéng le fùgài shèjì zhìzào quán liúchéng de wánzhěng chǎnyèliàn tǐxì, wèi guójiā zhìzàoyè zhuǎnxíng zhùláo le jīshí.", "en": "Since its inception during the new technological revolution, the enterprise has focused on self-developed industrial chips. After a decade of breakthroughs overcoming international tech embargos, the team established a complete industry chain covering design and fabrication.", "es": "Desde su fundación en la nueva ola tecnológica, la empresa se ha centrado en el desarrollo de microchips industriales. Tras una década de superación tecnológica, el equipo construyó una cadena integral que apuntala la industria nacional."}]}, {"meanings_summary": {"en": "maternal grandmother; granny (Northern colloquial)", "es": "abuela materna; abuelita (coloquial norteño)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The venerable elderly (老) woman (女) who raised your mother with boundless love is your maternal grandmother (姥姥).", "composite_memory_hook_es": "La venerable anciana (老) mujer (女) que crio a tu madre con infinito amor es tu abuela materna (姥姥).", "cultural_and_cognitive_roots": "In Northern Chinese culture, '姥姥' embodies warm maternal kinship, celebrated in children's folklore and holiday reunions as a haven of indulgence and homemade delicacies.", "tone_sandhi_and_pitch_modulation": "Reduplicated kinship noun where the first syllable carries 3rd tone and the second is reduced to neutral tone: 'lǎo lao' (214-0)."}, "semantic_boundary_contrasts": {"core_nuance": "姥姥 specifically refers to maternal grandmother in Northern vernacular Chinese.", "contrasts": [{"id": "1", "compared_word": "姥姥 vs. 外婆", "pinyin": "wàipó", "analysis": "姥姥 is predominantly Northern Mandarin vernacular, whereas 外婆 is common in Southern China and standard formal written Chinese."}, {"id": "2", "compared_word": "姥姥 vs. 奶奶", "pinyin": "nǎinai", "analysis": "姥姥 designates the mother's mother (maternal), while 奶奶 designates the father's mother (paternal)."}, {"id": "3", "compared_word": "姥姥 vs. 姑姑", "pinyin": "gūgu", "analysis": "姥姥 belongs to the grandparent generation on the maternal side, whereas 姑姑 refers to the father's sister in the parental generation."}]}, "traps_and_cognates": {"look_alikes": [{"character": "奶", "pinyin": "nǎi", "meaning_en": "grandmother (paternal); milk", "distinction_note": "Has 乃 on the right instead of 老"}, {"character": "姑", "pinyin": "gū", "meaning_en": "paternal aunt", "distinction_note": "Has 古 (ancient) on the right instead of 老"}, {"character": "姨", "pinyin": "yí", "meaning_en": "maternal aunt", "distinction_note": "Has 夷 on the right instead of 老"}, {"character": "老", "pinyin": "lǎo", "meaning_en": "old; elderly", "distinction_note": "Standalone root without the left female radical 女"}], "etymological_cognates": [{"character": "姥爷", "pinyin": "lǎo ye", "gloss_en": "maternal grandfather (Northern colloquial)"}, {"character": "奶奶", "pinyin": "nǎi nai", "gloss_en": "paternal grandmother"}, {"character": "老人", "pinyin": "lǎo rén", "gloss_en": "elderly person; parents"}, {"character": "老师", "pinyin": "lǎo shī", "gloss_en": "teacher; mentor"}]}, "id": "7", "hanzi": "姥姥", "pinyin": "lǎo lao", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Colloquial", "definition_en": "mother's mother; maternal grandmother (predominantly Northern usage)", "definition_es": "abuela materna; madre de la madre (uso común en el norte de China)", "example_phrase": "去姥姥家 (go to maternal grandmother's house)"}, {"sense_number": "2", "part_of_speech": "Interjection", "register": "Slang", "definition_en": "expression of disbelief, defiance, or contempt (Northern dialect: 姥姥！)", "definition_es": "¡ni hablar!, ¡de ninguna manera! (interjección dialectal norteña)", "example_phrase": "姥姥，我才不信呢 (No way, I don't buy that at all!)"}], "example_sentences": [{"id": "#1", "hanzi": "小时候每逢放暑假，我最盼望的就是去乡下姥姥家，吃姥姥亲手包的热腾腾的猪肉茴香饺子。", "pinyin": "Xiǎoshíhou měiféng fàng shǔjià, wǒ zuì pànwàng de jiùshì qù xiāngxià lǎolao jiā, chī lǎolao qīnshǒu bāo de rètēngtēng de zhūròu huíxiāng jiǎozi.", "en": "In childhood whenever summer vacation arrived, what I looked forward to most was visiting granny's house in the country and eating steaming pork-fennel dumplings she made by hand.", "es": "En mi infancia, al llegar las vacaciones estivales, lo que más ansiaba era ir al pueblo de mi abuelita y saborear sus humeantes empanadillas caseras."}, {"id": "#2", "hanzi": "姥姥虽已年过八旬，但精神矍铄，经常在家庭聚会上给年轻一辈讲述家族百年来的奋斗故事。", "pinyin": "Lǎolao suī yǐ nián guò bāxún, dàn jīngshén juéshuò, jīngcháng zài jiātíng jùhuì shàng gěi niánqīng yíbèi jiǎngshù jiāzú bǎinián lái de fèndòu gùshì.", "en": "Although granny is over eighty years old, she remains in hale and hearty spirits, often recounting the family's century of perseverance at gatherings.", "es": "Pese a superar los ochenta años, mi abuelita conserva una salud admirable y a menudo relata en reuniones familiares las vicisitudes del linaje."}], "collocations": [{"hanzi": "姥姥家", "en": "maternal grandmother's home"}, {"hanzi": "看姥姥", "en": "visit maternal grandmother"}, {"hanzi": "接姥姥", "en": "welcome / pick up maternal grandmother"}, {"hanzi": "给姥姥拜年", "en": "wish maternal grandmother a Happy New Year"}, {"hanzi": "姥姥的手艺", "en": "grandmother's cooking or craft skills"}, {"hanzi": "想念姥姥", "en": "miss maternal grandmother"}], "idioms": [{"hanzi": "儿孙满堂", "pinyin": "ér sūn mǎn táng", "meaning_en": "surrounded by children and grandchildren; enjoy bountiful family blessings"}, {"hanzi": "尊老爱幼", "pinyin": "zūn lǎo ài yòu", "meaning_en": "respect the elderly and cherish the young"}, {"hanzi": "天伦之乐", "pinyin": "tiān lún zhī lè", "meaning_en": "family happiness; domestic bliss among kin"}, {"hanzi": "含饴弄孙", "pinyin": "hán yí nòng sūn", "meaning_en": "enjoy playing with one's grandchildren in old age"}], "character_decomposition": [{"character": "姥", "pinyin": "lǎo", "meaning_en": "maternal grandmother; old lady", "meaning_es": "abuela materna; anciana respetable", "radical": "女", "radical_meaning_en": "woman / female", "meaning_component": "女 (female elder)", "sound_component": "老 (lǎo, aged / venerable)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound combining female radical 女 with venerable elder 老 to designate the maternal matriarch.", "visual_mnemonic_story_en": "A loving woman (女) with white hair and ripe years (老) holding her grandchild with deep tenderness.", "visual_mnemonic_story_es": "Una mujer bondadosa (女) que ha alcanzado una edad venerable (老) acoge a sus nietos con infinito afecto.", "tone_mnemonic_anchor": "214", "cangjie": "VJP", "traditional": "姥"}], "extended_reading_passages": [{"id": "#1", "hanzi": "记忆中姥姥的身影总是系着一条洗得泛白的蓝布围裙。每当我奔跑着推开院门，她便立刻放下手中的活计，迈着小碎步迎上来，将热腾腾的烤红薯塞进我冰凉的手心，眼里溢满了关切。", "pinyin": "Jìyì zhōng lǎolao de shēnyǐng zǒngshì xì zhe yì tiáo xǐ de fānbái de lánbù wéiqún. Měidāng wǒ bēnpǎo zhe tuīkāi yuànmén, tā biàn lìkè fàngxià shǒuzhōng de huójì, màizhe xiǎosuìbù yíng shànglái, jiāng rètēngtēng de kǎohóngshǔ sāijìn wǒ bīngliáng de shǒuxīn, yǎnlǐ yìmǎn le guānqiè.", "en": "In my memory granny always wore a faded blue apron. Whenever I burst through the courtyard gate, she would set down her chores and rush out with tiny steps, pressing a steaming roasted sweet potato into my cold hands, her eyes overflowing with affection.", "es": "En mi memoria, mi abuela siempre llevaba un delantal azul desteñido. Al empujar yo la cancela del patio, dejaba su quehacer y salía a paso presuroso para poner un boniato asado en mis manos frías, con los ojos rebosantes de amor."}, {"id": "#2", "hanzi": "中国南北方亲属称谓的差异折射出丰富的方言文化。北方习惯以“姥姥”与“姥爷”称呼母系祖辈，而南方多使用“外婆”与“外公”。现代语言学学者指出，这类亲属词汇的传承强化了代际认同与地域文化归属感。", "pinyin": "Zhōngguó nánběifāng qīnshǔ chēngwèi de chāyì zhéshè chū fēngfù de fāngyán wénhuà. Běifāng xíguàn yǐ \"lǎolao\" yǔ \"lǎoye\" chēnghu mǔxì zǔbèi, ér nánfāng duō shǐyòng \"wàipó\" yǔ \"wàigōng\". Xiàndài yǔyánxué xuézhě zhǐchū, zhè lèi qīnshǔ cíhuì de chuánchéng qiánghuà le dàijì rèntóng yǔ dìyù wénhuà guīshǔgǎn.", "en": "Regional contrasts in Chinese kinship terms reflect dialectal richness. Northerners use 'lǎolao' and 'lǎoye' for maternal grandparents, while Southerners use 'wàipó' and 'wàigōng'. Linguists emphasize that preserving kinship lexicon reinforces intergenerational identity and regional belonging.", "es": "Las diferencias de parentesco entre el norte y el sur de China muestran una gran riqueza lingüística. El norte emplea \"lǎolao\" y el sur \"wàipó\". Los lingüistas sostienen que estos vocablos fortalecen la identidad intergeneracional y el arraigo cultural."}]}, {"meanings_summary": {"en": "maternal uncle; mother's brother", "es": "tío materno; hermano de la madre"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The capable man (男) who shares the household mortar (臼) with your mother is your maternal uncle (舅舅).", "composite_memory_hook_es": "El hombre laborioso (男) que comparte el mortero familiar (臼) con tu madre es tu tío materno (舅舅).", "cultural_and_cognitive_roots": "In traditional Chinese lineage laws, maternal uncles held supreme moral authority ('天上雷公，地下母舅') as objective mediators during clan property divisions and wedding arbitrations.", "tone_sandhi_and_pitch_modulation": "Reduplicated noun where the first syllable carries 4th tone and the second is read in the neutral tone: 'jiù jiu' (51-0)."}, "semantic_boundary_contrasts": {"core_nuance": "舅舅 strictly denotes the brother of one's mother (maternal line).", "contrasts": [{"id": "1", "compared_word": "舅舅 vs. 叔叔", "pinyin": "shūshu", "analysis": "舅舅 is the mother's brother, whereas 叔叔 is the father's younger brother (or an informal polite title for an unfamiliar adult male)."}, {"id": "2", "compared_word": "舅舅 vs. 伯伯", "pinyin": "bóbo", "analysis": "舅舅 is on the maternal side, whereas 伯伯 refers exclusively to the father's elder brother."}, {"id": "3", "compared_word": "舅舅 vs. 姑父", "pinyin": "gūfu", "analysis": "舅舅 is related by blood on the mother's side, while 姑父 is an uncle by marriage (husband of father's sister)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "男", "pinyin": "nán", "meaning_en": "male; man", "distinction_note": "The lower component of 舅 without the upper 臼"}, {"character": "臼", "pinyin": "jiù", "meaning_en": "mortar", "distinction_note": "The upper component of 舅 without the lower 男"}, {"character": "界", "pinyin": "jiè", "meaning_en": "boundary; scope", "distinction_note": "Has 田 over 介; distinct lower structure from 男"}, {"character": "留", "pinyin": "liú", "meaning_en": "remain; stay", "distinction_note": "Has 卯 on the left with 田 on the right"}], "etymological_cognates": [{"character": "舅母", "pinyin": "jiù mǔ", "gloss_en": "maternal uncle's wife; aunt"}, {"character": "外甥", "pinyin": "wài sheng", "gloss_en": "nephew (sister's son)"}, {"character": "表哥", "pinyin": "biǎo gē", "gloss_en": "older male cousin via maternal line"}, {"character": "亲戚", "pinyin": "qīn qi", "gloss_en": "relatives; kin"}]}, "id": "8", "hanzi": "舅舅", "pinyin": "jiù jiu", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "brother of one's mother (maternal uncle)", "definition_es": "tío materno; hermano de la madre", "example_phrase": "大舅舅 (eldest maternal uncle)"}], "example_sentences": [{"id": "#1", "hanzi": "每年春节初二回娘家，舅舅总会早早站在村口迎接我们，手里提着满满一篮刚摘的鲜果。", "pinyin": "Měinián chūnjié chū'èr huí niángjiā, jiùjiu zǒng huì zǎozǎo zhàn zài cūnkǒu yíngjiē wǒmen, shǒulǐ tí zhe mǎnmǎn yì lán gāng zhāi de xiānguǒ.", "en": "On the second day of Spring Festival when we visited my mother's family, uncle always stood early at the village entrance to welcome us, holding a basket of fresh fruit.", "es": "El segundo día de la Fiesta de la Primavera, al visitar a la familia materna, mi tío nos esperaba en la entrada del pueblo con una cesta de fruta recién cosechada."}, {"id": "#2", "hanzi": "舅舅早年在南方沿海城市打拼创业，如今不仅事业有成，还经常出资资助家乡兴建学校与道路。", "pinyin": "Jiùjiu zǎonián zài nánfāng yánhǎi chéngshì dǎpīn chuàngyè, rújīn bùjǐn shìyè yǒuchéng, hái jīngcháng chūzī zīzhù jiāxiāng xīngjiàn xuéxiào yǔ dàolù.", "en": "In his early years uncle worked hard building a business in southern coastal cities; today he is successful and frequently finances schools and roads in his hometown.", "es": "De joven mi tío emprendió en la costa sur; hoy, además de triunfar en los negocios, financia con frecuencia escuelas y caminos en su pueblo natal."}], "collocations": [{"hanzi": "大舅舅", "en": "eldest maternal uncle"}, {"hanzi": "小舅舅", "en": "youngest maternal uncle"}, {"hanzi": "舅舅家", "en": "maternal uncle's house"}, {"hanzi": "探望舅舅", "en": "visit one's maternal uncle"}, {"hanzi": "舅舅的嘱咐", "en": "maternal uncle's advice or exhortation"}, {"hanzi": "亲舅舅", "en": "maternal uncle by blood"}], "idioms": [{"hanzi": "姑舅表亲", "pinyin": "gū jiù biǎo qīn", "meaning_en": "cousins through paternal aunt and maternal uncle; cross-cousin kin"}, {"hanzi": "骨肉相连", "pinyin": "gǔ ròu xiāng lián", "meaning_en": "flesh and blood inextricably linked; intimate familial ties"}, {"hanzi": "情同手足", "pinyin": "qíng tóng shǒu zú", "meaning_en": "loving each other like brothers; close affection"}, {"hanzi": "安居乐业", "pinyin": "ān jū lè yè", "meaning_en": "live in peace and work happily"}], "character_decomposition": [{"character": "舅", "pinyin": "jiù", "meaning_en": "maternal uncle; mother's brother", "meaning_es": "tío materno; hermano de la madre", "radical": "臼", "radical_meaning_en": "mortar", "meaning_component": "臼 (mortar, representing domestic work alliance)", "sound_component": "男 (nán, male worker in the fields)", "stroke_count": "13", "composition_type": "上下结构", "etymology_and_mnemonic": "Ancient compound of mortar (臼) and man (男), indicating the male member of the maternal household.", "visual_mnemonic_story_en": "A strong man (男) working alongside the maternal clan's grain mortar (臼) serves as your protective uncle.", "visual_mnemonic_story_es": "Un hombre recio (男) que ayuda con el mortero de grano (臼) en la casa materna es el tío protector.", "tone_mnemonic_anchor": "51", "cangjie": "HXWS", "traditional": "舅"}], "extended_reading_passages": [{"id": "#1", "hanzi": "小时候每次去舅舅家，他都会领着我们去小溪边捉鱼捉虾。傍晚归来，舅舅在院里生起柴火，用大铁锅煎出焦黄酥脆的杂鱼，那份爽朗豁达的笑声至今仍留在我的耳畔。", "pinyin": "Xiǎoshíhou měicì qù jiùjiu jiā, tā dōu huì lǐng zhe wǒmen qù xiǎoxī biān zhuō yú zhuō xiā. Bàngwǎn guīlái, jiùjiu zài yuàn lǐ shēng qǐ cháihuǒ, yòng dà tiěguō jiān chū jiāohuáng sūcuì de záyú, nà fèn shuǎnglǎng huòdá de xiàoshēng zhìjīn réng liú zài wǒ de ěrpàn.", "en": "In childhood whenever visiting uncle's house, he would lead us to the creek catching fish and shrimp. Returning at dusk, uncle lit a wood fire in the yard and fried crispy fish in a large iron wok, his hearty laughter lingering in my ears to this day.", "es": "De niño, al visitar a mi tío, nos llevaba al arroyo a pescar peces y camarones. Al caer la tarde encendía el fuego del patio y freía pescado crujiente en la sartén de hierro, con una risa franca que aún resuena en mi memoria."}, {"id": "#2", "hanzi": "在中国传统乡土社会中，“娘舅”往往承担着调节宗族纠纷与见证家庭分产的重要伦理职能。这种独特的亲属制度安排，不仅为外甥一代提供了强有力的情感支撑，也成为维系乡村宗族和谐的制度纽带。", "pinyin": "Zài Zhōngguó chuántǒng xiāngtǔ shèhuì zhōng, \"niángjiù\" wǎngwǎng chéngdān zhe tiáojié zōngzú jiūfēn yǔ jiànzhèng jiātíng fēnchǎn de zhòngyào lúnlǐ zhínéng. Zhè zhǒng dútè de qīnshǔ zhìdù ānpái, bùjǐn wèi wàisheng yídài tígōng le qiángyǒulì de qínggǎn zhīchēng, yě chéngwéi wéixì xiāngcūn zōngzú héxié de zhìdù niǔdài.", "en": "In traditional Chinese rural society, maternal uncles often fulfilled vital ethical duties mediating disputes and witnessing property divisions. This unique kinship arrangement provided emotional support for nephews and acted as an institutional bond sustaining clan harmony.", "es": "En la sociedad rural tradicional, el tío materno ejercía la función de mediar en disputas y avalar repartos hereditarios. Esta institución no solo ofrecía respaldo a los sobrinos, sino que constituía un lazo civil que salvaguardaba la concordia comunitaria."}]}, {"meanings_summary": {"en": "paternal aunt; father's sister", "es": "tía paterna; hermana del padre"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The loving woman (女) linked to your father's ancient (古) household lineage is your paternal aunt (姑姑).", "composite_memory_hook_es": "La mujer (女) del linaje antiguo (古) de tu padre que te colma de mimos es tu tía paterna (姑姑).", "cultural_and_cognitive_roots": "In Chinese kinship geography, '姑' represents the out-marrying daughter of the paternal family who maintains intimate sentimental ties, serving as an affectionate link between extended families.", "tone_sandhi_and_pitch_modulation": "Reduplicated noun where the first syllable carries 1st tone (high level 55) and the second syllable is softened into neutral tone: 'gū gu' (55-0)."}, "semantic_boundary_contrasts": {"core_nuance": "姑姑 is exclusively the father's sister (paternal blood relative).", "contrasts": [{"id": "1", "compared_word": "姑姑 vs. 阿姨", "pinyin": "āyí", "analysis": "姑姑 strictly designates the father's sister, whereas 阿姨 can be the mother's sister (maternal) or a polite title for any woman of one's mother's generation."}, {"id": "2", "compared_word": "姑姑 vs. 舅妈", "pinyin": "jiùmā", "analysis": "姑姑 is related by paternal blood, while 舅妈 is related by marriage (wife of mother's brother)."}, {"id": "3", "compared_word": "姑姑 vs. 婶婶", "pinyin": "shěnshen", "analysis": "姑姑 is father's sister, whereas 婶婶 is father's younger brother's wife (aunt by marriage)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "姨", "pinyin": "yí", "meaning_en": "maternal aunt", "distinction_note": "Has 夷 on the right instead of 古"}, {"character": "娘", "pinyin": "niáng", "meaning_en": "mother; woman", "distinction_note": "Has 良 on the right instead of 古"}, {"character": "妹", "pinyin": "mèi", "meaning_en": "younger sister", "distinction_note": "Has 未 on the right instead of 古"}, {"character": "估", "pinyin": "gū", "meaning_en": "estimate; assess", "distinction_note": "Has 亻 (person) radical on the left instead of 女"}], "etymological_cognates": [{"character": "姑娘", "pinyin": "gū niang", "gloss_en": "girl; young woman"}, {"character": "姑妈", "pinyin": "gū mā", "gloss_en": "paternal aunt (married elder sister/sister of father)"}, {"character": "姑父", "pinyin": "gū fu", "gloss_en": "paternal aunt's husband; uncle-in-law"}, {"character": "姑且", "pinyin": "gū qiě", "gloss_en": "tentatively; for the time being"}]}, "id": "9", "hanzi": "姑姑", "pinyin": "gū gu", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "sister of one's father (paternal aunt)", "definition_es": "tía paterna; hermana del padre", "example_phrase": "小姑姑 (youngest paternal aunt)"}], "example_sentences": [{"id": "#1", "hanzi": "姑姑手巧得很，每年入冬前都会给几个晚辈织一件厚实暖和的羊毛衫。", "pinyin": "Gūgu shǒuqiǎo de hěn, měinián rùdōng qián dōu huì gěi jǐ gè wǎnbèi zhī yí jiàn hòushi nuǎnhuo de yángmáoshān.", "en": "Aunt is very skillful with her hands; before each winter she knits a thick, warm woolen sweater for each of the youngsters.", "es": "Mi tía tiene manos primorosas; antes de cada invierno teje un jersey de lana grueso y abrigado para cada uno de los sobrinos."}, {"id": "#2", "hanzi": "每次回老家看望父亲，姑姑总要详细询问家里的各项琐事，处处流露出对大家庭的深情关怀。", "pinyin": "Měicì huí lǎojiā kànwàng fùqīn, gūgu zǒng yào xiángxì xùnwèn jiālǐ de gè xiàng suǒshì, chùchù liúlù chū duì dàjiātíng de shēnqíng guānhuái.", "en": "Whenever visiting father back home, aunt inquires in detail about household affairs, revealing deep devotion to the extended family.", "es": "Cada vez que regresa al pueblo a visitar a mi padre, mi tía se interesa por los pormenores del hogar, derrochando afecto hacia toda la familia."}], "collocations": [{"hanzi": "大姑姑", "en": "eldest paternal aunt"}, {"hanzi": "小姑姑", "en": "youngest paternal aunt"}, {"hanzi": "姑姑家", "en": "paternal aunt's home"}, {"hanzi": "看望姑姑", "en": "visit paternal aunt"}, {"hanzi": "姑姑的礼物", "en": "aunt's gift"}, {"hanzi": "堂姑", "en": "father's female cousin"}], "idioms": [{"hanzi": "姑息养奸", "pinyin": "gū xī yǎng jiān", "meaning_en": "tolerate evil and abet crimes; overly indulge wrongdoing"}, {"hanzi": "和睦相处", "pinyin": "hé mù xiāng chǔ", "meaning_en": "live in harmony and mutual affection with one another"}, {"hanzi": "情深似海", "pinyin": "qíng shēn sì hǎi", "meaning_en": "affection as deep as the boundless ocean"}, {"hanzi": "同心协力", "pinyin": "tóng xīn xié lì", "meaning_en": "work together with one heart and joint effort"}], "character_decomposition": [{"character": "姑", "pinyin": "gū", "meaning_en": "paternal aunt; maiden; tentatively", "meaning_es": "tía paterna; doncella; provisionalmente", "radical": "女", "radical_meaning_en": "woman / female", "meaning_component": "女 (female kinship)", "sound_component": "古 (gǔ, ancient / phonetic)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound combining female radical 女 with phonetic 古, designating a woman of the ancestral paternal clan.", "visual_mnemonic_story_en": "An ancient (古) lineage woman (女) who preserves the family bonds and traditions with tender care.", "visual_mnemonic_story_es": "Una mujer (女) vinculada al linaje antiguo (古) del padre que cuida con esmero a los hijos de sus hermanos.", "tone_mnemonic_anchor": "55", "cangjie": "VJR", "traditional": "姑"}], "extended_reading_passages": [{"id": "#1", "hanzi": "姑姑是个极爱干净且性情温和的人。在我的童年记忆里，每次去姑姑家，桌上总会摆着满满一盘洗得干干净净的水果。她一边听我讲学校里的趣事，一边笑着抚摸我的额头，目光里尽是慈爱。", "pinyin": "Gūgu shì gè jí ài gānjìng qiě xìngqíng wēnhé de rén. Zài wǒ de tóngnián jìyì lǐ, měicì qù gūgu jiā, zhuō shàng zǒng huì bǎizhe mǎnmǎn yì pán xǐ de gāngānjìngjìng de shuǐguǒ. Tā yìbiān tīng wǒ jiǎng xuéxiào lǐ de qùshì, yìbiān xiào zhe fǔmō wǒ de étóu, mùguāng lǐ jìn shì cí'ài.", "en": "Aunt is an impeccably tidy and gentle person. In my childhood memories, whenever visiting her home, the table held a freshly washed platter of fruits. Listening to school tales, she smiled and stroked my forehead, eyes radiant with affection.", "es": "Mi tía es una persona pulcra y dulce. En mis recuerdos de infancia, al visitarla siempre había una bandeja de fruta fresca sobre la mesa. Escuchaba mis anécdotas escolares mientras acariciaba mi frente con mirada henchida de ternura."}, {"id": "#2", "hanzi": "汉字文化圈中精细的亲属称谓体现了宗法制度的核心逻辑。姑、舅、叔、伯不仅明确了父系与母系的血缘远近，更界定了宗族礼仪中的权利与义务。这种细密的亲属网络至今仍在维系家庭情感中发挥独特作用。", "pinyin": "Hànzì wénhuàquān zhōng jīngxì de qīnshǔ chēngwèi tǐxiàn le zōngfǎ zhìdù de héxīn luójí. Gū, jiù, shū, bó bùjǐn míngquè le fùxì yǔ mǔxì de xiěyuán yuǎnjìn, gèng jièdìng le zōngzú lǐyí zhōng de quánlì yǔ yìwù. Zhè zhǒng xìmì de qīnshǔ wǎngluò zhìjīn réng zài wéixì jiātíng qínggǎn zhōng fāhuī dútè zuòyòng.", "en": "Precise kinship terms in Sinophone culture reflect the logic of patriarchal lineage. Distinctions like aunt, uncle, and elder uncle clarify blood proximity and formal obligations. This fine kinship matrix continues to play an irreplaceable role sustaining family solidarity today.", "es": "La minuciosa nomenclatura de parentesco tradicional refleja la lógica del sistema patriarcal. Términos específicos como tía paterna definen grados de consanguinidad y deberes ceremoniales, manteniendo la cohesión y el apoyo solidario intrafamiliar."}]}, {"meanings_summary": {"en": "firm; resolute; determined; unyielding", "es": "firme; resuelto; tajante; inquebrantable"}, "mnemonics_and_roots": {"composite_memory_hook_en": "With the strength of rammed earth (坚) and the cutting sharpness of a blade (决), one makes a resolute (坚决) choice.", "composite_memory_hook_es": "Con la solidez de la tierra firme (坚) y el filo tajante del hielo (决), se toma una decisión inquebrantable (坚决).", "cultural_and_cognitive_roots": "In classical Chinese statecraft, '坚决' represents moral fortitude where rock-solid internal integrity (坚) pairs with decisive external execution (决) without wavering.", "tone_sandhi_and_pitch_modulation": "Pronounced with a 55-35 pitch contour (1st tone high and level, followed by 2nd tone rising resolutely). Maintain firm articulation throughout."}, "semantic_boundary_contrasts": {"core_nuance": "坚决 describes an uncompromising, unwavering attitude or stance in taking decisive action.", "contrasts": [{"id": "1", "compared_word": "坚决 vs. 坚定", "pinyin": "jiāndìng", "analysis": "坚决 focuses on decisive and uncompromising external action or attitude (e.g. 坚决执行, 坚决反对), whereas 坚定 emphasizes enduring internal conviction, faith, or willpower (e.g. 立场坚定, 坚定信心)."}, {"id": "2", "compared_word": "坚决 vs. 果断", "pinyin": "guǒduàn", "analysis": "坚决 highlights firmness and lack of hesitation against opposition, while 果断 stresses swift decisiveness and absence of delay or hesitation in crises."}, {"id": "3", "compared_word": "坚决 vs. 顽固", "pinyin": "wángù", "analysis": "坚决 is a positive or neutral commendation of integrity and moral strength, whereas 顽固 is derogatory, implying irrational stubbornness and refusal to change."}]}, "traps_and_cognates": {"look_alikes": [{"character": "坚持", "pinyin": "jiān chí", "meaning_en": "persist; persevere", "distinction_note": "Contains 坚 but paired with 持 (hold)"}, {"character": "快", "pinyin": "kuài", "meaning_en": "fast; quick", "distinction_note": "Has 忄 (heart) on the left with 夬 on the right instead of 冫"}, {"character": "决", "pinyin": "jué", "meaning_en": "decide", "distinction_note": "Has 冫 on the left, unlike 块 which has 土 (earth)"}, {"character": "贤", "pinyin": "xián", "meaning_en": "worthy; virtuous", "distinction_note": "Has 贝 (shell/wealth) at the bottom instead of 土"}], "etymological_cognates": [{"character": "决定", "pinyin": "jué dìng", "gloss_en": "decide; decision"}, {"character": "坚定", "pinyin": "jiān dìng", "gloss_en": "firm; steadfast"}, {"character": "坚强", "pinyin": "jiān qiáng", "gloss_en": "strong; staunch; resilient"}, {"character": "决断", "pinyin": "jué duàn", "gloss_en": "make a decision; judgment"}]}, "id": "10", "hanzi": "坚决", "pinyin": "jiān jué", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "firm and unwavering in attitude, stance, or decision", "definition_es": "firme; resuelto; que no vacila", "example_phrase": "态度坚决 (resolute attitude)"}, {"sense_number": "2", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "resolutely; determinedly; firmly (modifying a verb)", "definition_es": "resueltamente; con firmeza", "example_phrase": "坚决反对 (firmly oppose)"}], "example_sentences": [{"id": "#1", "hanzi": "面对村里重男轻女的传统旧观念，母亲坚决支持姐姐继续读完大学并追求梦想。", "pinyin": "Miànduì cūnlǐ zhòngnán-qīngnǚ de chuántǒng jiù guānniàn, mǔqīn jiānjué zhīchí jiějie jìxù dú wán dàxué bìng zhuīqiú mèngxiǎng.", "en": "In the face of old village prejudices favoring boys over girls, mother resolutely supported my elder sister finishing university and pursuing her dreams.", "es": "Frente al prejuicio tradicional de la aldea que favorecía a los varones, mi madre apoyó resueltamente a mi hermana para concluir la universidad."}, {"id": "#2", "hanzi": "董事会以坚决的姿态驳回了这项存在巨大合规风险的投资提案，切实保障了股东利益。", "pinyin": "Dǒngshìhuì yǐ jiānjué de zītài bóhuí le zhè xiàng cúnzài jùdà hégūi fēngxiǎn de tóuzī tí'àn, qièshí bǎozhàng le gǔdōng lìyì.", "en": "The board of directors rejected with a resolute stance this investment proposal carrying huge compliance risks, safeguarding shareholder interests.", "es": "La junta directiva rechazó con firme determinación la propuesta inversora de alto riesgo regulatorio, protegiendo los intereses de los accionistas."}], "collocations": [{"hanzi": "坚决反对", "en": "firmly oppose"}, {"hanzi": "坚决支持", "en": "resolutely support"}, {"hanzi": "态度坚决", "en": "resolute attitude"}, {"hanzi": "坚决执行", "en": "resolutely execute / implement"}, {"hanzi": "坚决抵制", "en": "firmly resist / boycott"}, {"hanzi": "语气坚决", "en": "resolute tone of voice"}], "idioms": [{"hanzi": "坚定不移", "pinyin": "jiān dìng bù yí", "meaning_en": "unswerving; steadfast and immovable"}, {"hanzi": "斩钉截铁", "pinyin": "zhǎn dīng jié tiě", "meaning_en": "chop through nails and sever iron; resolute and decisive"}, {"hanzi": "雷打不动", "pinyin": "léi dǎ bú dòng", "meaning_en": "not shaken even by thunder; rock-firm and unyielding"}, {"hanzi": "毅然决然", "pinyin": "yì rán jué rán", "meaning_en": "resolute and determined without hesitation"}], "character_decomposition": [{"character": "坚", "pinyin": "jiān", "meaning_en": "hard; solid; firm; resolute", "meaning_es": "duro; sólido; firme; tenaz", "radical": "土", "radical_meaning_en": "earth / soil", "meaning_component": "土 (earth packed solid)", "sound_component": "臤 (qiān, firm grasp)", "stroke_count": "7", "composition_type": "上下结构", "etymology_and_mnemonic": "Ancient compound depicting rammed earth (土) held tightly together, symbolizing unyielding structural integrity.", "visual_mnemonic_story_en": "Solid earth (土) compressed so tightly beneath a watchful hand that no force can crumble its resolve.", "visual_mnemonic_story_es": "Tierra apisonada (土) tan compacta bajo una mano firme que nada logra quebrar su solidez.", "tone_mnemonic_anchor": "55", "cangjie": "EPG", "traditional": "堅"}, {"character": "决", "pinyin": "jué", "meaning_en": "decide; breach; certainly", "meaning_es": "decidir; resolver; tajante", "radical": "冫", "radical_meaning_en": "ice / two drops of water", "meaning_component": "冫 (cutting water or ice)", "sound_component": "夬 (guài, decisive parting)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where ice (冫) and breach (夬) denote breaking through obstacles to make an irrevocable judgment.", "visual_mnemonic_story_en": "Chilly drops of water (冫) cutting like a sharp blade (夬) through doubts to make a final decision.", "visual_mnemonic_story_es": "Gotas de hielo (冫) que cortan como una cuchilla (夬) las dudas para tomar una determinación tajante.", "tone_mnemonic_anchor": "35", "cangjie": "IMDK", "traditional": "決"}], "extended_reading_passages": [{"id": "#1", "hanzi": "在人生的十字路口，我们总会面临外界的非议与阻力。唯有内心笃定、态度坚决的人，才能在重重迷雾中守住自己的初心，不被旁人的只言片语所左右，一步一个脚印走出属于自己的宽广坦途。", "pinyin": "Zài rénshēng de shízìlùkǒu, wǒmen zǒng huì miànlín wàijiè de fēiyì yǔ zǔlì. Wéiyǒu nèixīn dǔdìng, tàidù jiānjué de rén, cáinǐng zài chóngchóng míwù zhōng shǒuzhù zìjǐ de chūxīn, bú bèi pángrén de zhīyán-piànyǔ suǒ zuǒyòu, yíbù yí gè jiǎoyìn zǒuchū shǔyú zìjǐ de kuānguǎng tǎntú.", "en": "At life's crossroads, we always encounter outside criticism and resistance. Only those with inner certainty and resolute resolve can safeguard their initial aspirations amid thick mists, unswayed by casual remarks, forging their own broad path.", "es": "En las encrucijadas vitales, siempre afrontamos críticas y obstáculos. Solo quien posee convicción interior y actitud resuelta preserva su vocación entre la niebla, sin dejarse desviar por juicios ajenos, labrando su propio destino."}, {"id": "#2", "hanzi": "面对突发公共卫生事件与复杂的国际经济博弈，决策层采取了极为坚决果断的宏观调控措施。通过迅速切断风险传播链条、全力稳就业保民生，各级机构展现出高效的协同动员力，确保了社会大局平稳发展。", "pinyin": "Miànduì tūfā gōnggòng wèishēng shìjiàn yǔ fùzá de guójì jīngjì bóyì, juécècéng cǎiqǔ le jíwéi jiānjué guǒduàn de hóngguān tiáokòng cuòshī. Tōngguò xùnsù qiēduàn fēngxiǎn chuánbō liàntiáo, quánlì wěn jiùyè bǎo mínshēng, gèjí jīgòu zhǎnxiàn chū gāoxiào de xiétóng dòngyuánlì, quèbǎo le shèhuì dàjú píngwěn fāzhǎn.", "en": "Confronting emergency public health crises and intricate global economic games, leadership adopted resolute macro-regulatory measures. Promptly cutting risk transmission chains and stabilizing livelihoods, institutions demonstrated efficient mobilization.", "es": "Ante emergencias sanitarias y complejas tensiones económicas globales, el liderazgo adoptó enérgicas medidas reguladoras macroeconómicas. Cortando cadenas de riesgo y protegiendo el empleo, las instituciones preservaron la estabilidad nacional."}]}, {"meanings_summary": {"en": "to work a temporary or manual job; to work away from home; to do part-time work", "es": "trabajar por cuenta ajena; hacer trabajos temporales; trabajar fuera de casa"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Using one's hands (打) with tools to produce disciplined labor (工) defines working for wages (打工).", "composite_memory_hook_es": "Mover las manos (打) con disciplina laboral (工) define trabajar como asalariado (打工).", "cultural_and_cognitive_roots": "Originating from Cantonese vernacular ('打工'), the phrase entered Mandarin during China's 1980s economic reform, becoming the defining symbol of the massive rural-to-urban migrant labor mobility ('民工潮').", "tone_sandhi_and_pitch_modulation": "Pronounced with a 214-55 pitch contour (3rd tone dipping cleanly, followed by a crisp 1st tone high pitch)."}, "semantic_boundary_contrasts": {"core_nuance": "打工 highlights working as an employee, wage earner, or migrant worker, often emphasizing manual, frontline, or temporary nature.", "contrasts": [{"id": "1", "compared_word": "打工 vs. 工作", "pinyin": "gōngzuò", "analysis": "工作 is a neutral, formal term covering any professional employment or career, whereas 打工 emphasizes working under an employer for hourly/monthly wages, often implying migrant or frontline status."}, {"id": "2", "compared_word": "打工 vs. 就业", "pinyin": "jiùyè", "analysis": "就业 is an official socio-economic term referring to systemic employment and labor market statistics, while 打工 is colloquial personal parlance."}, {"id": "3", "compared_word": "打工 vs. 创业", "pinyin": "chuàngyè", "analysis": "打工 means working for someone else's business, which is the direct conceptual antonym of 创业 (founding one's own business / entrepreneurship)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "订", "pinyin": "dìng", "meaning_en": "subscribe; order", "distinction_note": "Has 讠 (speech) on the left instead of 扌 (hand)"}, {"character": "顶", "pinyin": "dǐng", "meaning_en": "crown; apex; prop", "distinction_note": "Has 页 (head) on the right instead of hand 扌"}, {"character": "土", "pinyin": "tǔ", "meaning_en": "soil; earth", "distinction_note": "Has shorter top horizontal stroke than 工"}, {"character": "干", "pinyin": "gàn", "meaning_en": "do; dry; trunk", "distinction_note": "Has vertical stroke piercing through the top horizontal"}], "etymological_cognates": [{"character": "工人", "pinyin": "gōng rén", "gloss_en": "worker; laborer"}, {"character": "工业", "pinyin": "gōng yè", "gloss_en": "industry"}, {"character": "工作", "pinyin": "gōng zuò", "gloss_en": "work; job; task"}, {"character": "手工艺", "pinyin": "shǒu gōng yì", "gloss_en": "handicraft; artisan craftsmanship"}]}, "id": "11", "hanzi": "打工", "pinyin": "dǎ gōng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to work as an employee or wage laborer, often away from one's hometown", "definition_es": "trabajar de asalariado o peón, a menudo emigrando", "example_phrase": "外出打工 (go out to work)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to do part-time or student odd jobs to earn pocket money", "definition_es": "hacer trabajos de media jornada o changas de estudiante", "example_phrase": "假期打工 (work part-time during holidays)"}], "example_sentences": [{"id": "#1", "hanzi": "为了供弟弟妹妹上学，他高中毕业后就跟随同乡前往沿海工业城市打工。", "pinyin": "Wèile gōng dìdi mèimei shàngxué, tā gāozhōng bìyè hòu jiù gēnsuí tóngxiāng qiánwǎng yánhǎi gōngyè chéngshì dǎgōng.", "en": "In order to support his younger siblings' schooling, after high school graduation he followed fellow villagers to coastal industrial cities to work.", "es": "Para costear los estudios de sus hermanos, tras graduarse de secundaria emigró a las ciudades industriales costeras a trabajar como asalariado."}, {"id": "#2", "hanzi": "许多当代大学生利用寒暑假在企业打工实习，以此积累宝贵的职场实践经验并实现经济独立。", "pinyin": "Xǔduō dāngdài dàxuéshēng lìyòng hánshǔjià zài qǐyè dǎgōng shíxí, yǐ cǐ jīlěi bǎoguì de zhíchǎng shíjiàn jīngyàn bìng shíxiàn jīngjì dúlì.", "en": "Many contemporary college students work temporary internships during breaks to accumulate workplace experience and achieve financial independence.", "es": "Muchos universitarios aprovechan las vacaciones para trabajar como pasantes en empresas, acumulando experiencia profesional y logrando autonomía económica."}], "collocations": [{"hanzi": "外出打工", "en": "go out to work away from home"}, {"hanzi": "打工仔", "en": "migrant worker / young employee (colloquial)"}, {"hanzi": "打工妹", "en": "young female migrant worker"}, {"hanzi": "兼职打工", "en": "work a part-time job"}, {"hanzi": "打工赚钱", "en": "work to earn money"}, {"hanzi": "打工经历", "en": "work experience as an employee"}], "idioms": [{"hanzi": "白手起家", "pinyin": "bái shǒu qǐ jiā", "meaning_en": "build up an enterprise from scratch with bare hands"}, {"hanzi": "自食其力", "pinyin": "zì shí qí lì", "meaning_en": "earn one's own living; support oneself by one's own labor"}, {"hanzi": "起早贪黑", "pinyin": "qǐ zǎo tān hēi", "meaning_en": "wake early and toil into the dark; work from dawn to dusk"}, {"hanzi": "苦尽甘来", "pinyin": "kǔ jìn gān lái", "meaning_en": "bitterness ends and sweetness arrives; after pain comes joy"}], "character_decomposition": [{"character": "打", "pinyin": "dǎ", "meaning_en": "strike; hit; do; make", "meaning_es": "golpear; dar; hacer; ejercer", "radical": "扌", "radical_meaning_en": "hand", "meaning_component": "扌 (hand in vigorous manual motion)", "sound_component": "丁 (dīng, nail / phonetic)", "stroke_count": "5", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound combining hand radical 扌 with phonetic 丁, broadly signifying energetic bodily manipulation or work.", "visual_mnemonic_story_en": "A skilled hand (扌) driving a nail (丁) represents physical work and manual exertion.", "visual_mnemonic_story_es": "Una mano diestra (扌) que clava con fuerza un clavo (丁) simboliza el trabajo manual dinámico.", "tone_mnemonic_anchor": "214", "cangjie": "QMN", "traditional": "打"}, {"character": "工", "pinyin": "gōng", "meaning_en": "labor; work; craftsman", "meaning_es": "trabajo; labor; obrero", "radical": "工", "radical_meaning_en": "carpenter's square / work", "meaning_component": "工 (pictograph of a builder's carpenter's rule or square)", "sound_component": "", "stroke_count": "3", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of a carpenter's square or level, representing the craft and discipline of human manual fabrication.", "visual_mnemonic_story_en": "A carpenter's square (工) used by craftsmen to measure wood accurately on the worksite.", "visual_mnemonic_story_es": "La escuadra de carpintero (工) que emplean los artesanos para medir la obra en construcción.", "tone_mnemonic_anchor": "55", "cangjie": "M", "traditional": "工"}], "extended_reading_passages": [{"id": "#1", "hanzi": "那些年在外打工，父亲的双手磨出了厚厚的老茧。每年年底踏上回乡的绿皮火车，他总会小心翼翼地把攒下的工钱缝在外衣内侧口袋里，那是撑起全家希望的全部底气与尊严。", "pinyin": "Nàxiē nián zài wài dǎgōng, fùqīn de shǒushān mó chū le hòuhòu de lǎojiǎn. Měinián niándǐ tà shàng huíxiāng de lǜpí huǒchē, tā zǒng huì xiǎoxīnyìyì de bǎ zǎn xià de gōngqián féng zài wàiyī nèicè kǒudài lǐ, nà shì chēng qǐ quán jiā xīwàng de quánbù dǐqì yǔ zūnyán.", "en": "During those years working away from home, father's hands grew thick calluses. Boarding the green train home at year's end, he carefully stitched saved wages into his inner coat pocket, carrying our family's entire hope and dignity.", "es": "En aquellos años de trabajo fuera, las manos de mi padre se llenaron de callos. Al subir al tren verde a fin de año, cosía los ahorros en el forro del abrigo, guardando la dignidad y el sustento de la familia."}, {"id": "#2", "hanzi": "改革开放以来，数以亿计的农民工外出打工，为中国制造业崛起与城市化建设奠定了坚实的人力基石。近年来，随着产业升级与技能培训普及，“新生代农民工”正加速向具备专业技能的现代产业工人转型。", "pinyin": "Gǎigé kāifàng yǐlái, shù yǐ yì jì de nóngmíngōng wàichū dǎgōng, wèi Zhōngguó zhìzàoyè juéqǐ yǔ chéngshìhuà jiànshè diàndìng le jiānshí de rénlì jīshí. Jìnnián lái, suí zhe chǎnyè shēngjí yǔ jìnéng péixùn pǔjí, \"xīnshēngdài nóngmíngōng\" zhèng jiāsù xiàng jùbèi zhuānyè jìnéng de xiàndài chǎnyè gōngrén zhuǎnxíng.", "en": "Since the reform, hundreds of millions of rural workers migrated to work, laying the manpower foundation for China's manufacturing and urban boom. Recently, industrial upgrading has accelerated their transformation into skilled modern industrial workers.", "es": "Desde la reforma, cientos de millones de campesinos migraron a trabajar en la urbe, levantando la industria china. Con la capacitación técnica moderna, las nuevas generaciones se transforman rápidamente en operarios cualificados."}]}, {"meanings_summary": {"en": "to earn (money); to make a living; to struggle free", "es": "ganar (dinero); ganarse la vida; desasirse; forcejear"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Using both hands (扌) to strive and compete (争) in the world allows you to earn (挣) hard-won income.", "composite_memory_hook_es": "Usar las manos (扌) para luchar y pugnar (争) en la vida te permite ganar (挣) el sustento con esfuerzo.", "cultural_and_cognitive_roots": "In traditional Chinese popular ethics, '挣' carries the weight of sweat and hardship; money earned through bodily toil (血汗钱) is revered as the highest test of moral character and familial piety.", "tone_sandhi_and_pitch_modulation": "When meaning 'earn money', read in 4th tone with sharp falling pitch: 'zhèng' (51). When paired in '挣扎' (struggle), read in 1st tone: 'zhēngzhá' (55-35)."}, "semantic_boundary_contrasts": {"core_nuance": "挣 emphasizes earning income through arduous physical or persistent personal labor.", "contrasts": [{"id": "1", "compared_word": "挣 vs. 赚", "pinyin": "zhuàn", "analysis": "挣 emphasizes hard work, sweat, and labor to earn wages (e.g. 挣辛苦钱), whereas 赚 focuses on commercial profit, investment margins, or financial returns (e.g. 赚钱, 赚差价)."}, {"id": "2", "compared_word": "挣 vs. 赢", "pinyin": "yíng", "analysis": "挣 is strictly earning remuneration through work, while 赢 means winning a game, competition, legal lawsuit, or lottery (e.g. 赢得比赛, 赢牌)."}, {"id": "3", "compared_word": "挣 vs. 领", "pinyin": "lǐng", "analysis": "挣 requires exertion of effort to produce income, while 领 means receiving, collecting, or claiming funds issued by others (e.g. 领工资, 领补贴)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "净", "pinyin": "jìng", "meaning_en": "clean; pure; net", "distinction_note": "Has 冫 (ice) on the left instead of 扌 (hand)"}, {"character": "争", "pinyin": "zhēng", "meaning_en": "contend; dispute", "distinction_note": "Standalone phonetic root without the left hand radical 扌"}, {"character": "睁", "pinyin": "zhēng", "meaning_en": "open eyes", "distinction_note": "Has 目 (eye) on the left with 争 on the right"}, {"character": "铮", "pinyin": "zhēng", "meaning_en": "clank of metal; sonorous", "distinction_note": "Has 钅 (metal) on the left with 争 on the right"}], "etymological_cognates": [{"character": "挣钱", "pinyin": "zhèng qián", "gloss_en": "earn money"}, {"character": "挣脱", "pinyin": "zhèng tuō", "gloss_en": "break free from; extricate oneself"}, {"character": "挣扎", "pinyin": "zhēng zhá", "gloss_en": "struggle; flail"}, {"character": "争分夺秒", "pinyin": "zhēng fēn duó miǎo", "gloss_en": "race against the clock; contest every second"}]}, "id": "12", "hanzi": "挣", "pinyin": "zhèng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to earn money through labor or enterprise", "definition_es": "ganar dinero mediante el trabajo", "example_phrase": "挣钱养家 (earn money to support family)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "(read zhēng) to struggle, strive, or try to break free", "definition_es": "(leído zhēng) forcejear; desasirse; bregar", "example_phrase": "挣脱束缚 (struggle free from shackles)"}], "example_sentences": [{"id": "#1", "hanzi": "他年轻时在建筑工地上勤扒苦做，省吃俭用挣下了第一笔买房的首付款。", "pinyin": "Tā niánqīng shí zài jiànzhù gōngdì shàng qín bā kǔ zuò, shěngchī-jiǎnyòng zhèng xià le dì-yī bǐ mǎi fáng de shǒufùkuǎn.", "en": "When young he toiled relentlessly on construction sites, living frugally to earn the down payment for his first apartment.", "es": "De joven trabajó duramente en obras de construcción, ahorrando hasta el último céntimo para ganar la entrada de su primer piso."}, {"id": "#2", "hanzi": "该科技初创公司通过不断优化海外跨境电商服务模式，在竞争激烈的国际市场中挣得了可观的利润。", "pinyin": "Gāi kējì chūchuàng gōngsī tōngguò búduàn yōuhuà hǎiwài kuàjìng diànshāng fúwù móshì, zài jìngzhēng jīliè de guójì shìchǎng zhōng zhèng dé le kěguān de lìrùn.", "en": "By continually refining its cross-border e-commerce model, the tech startup earned respectable profits in the fierce global market.", "es": "Optimizando su modelo de comercio transfronterizo, la empresa emergente obtuvo considerables beneficios en el competitivo mercado internacional."}], "collocations": [{"hanzi": "挣钱", "en": "earn money; make money"}, {"hanzi": "挣工资", "en": "earn a salary / wage"}, {"hanzi": "挣大钱", "en": "make big money"}, {"hanzi": "挣扎", "en": "struggle; strive (pronounced zhēngzhá)"}, {"hanzi": "挣脱", "en": "struggle free; break loose"}, {"hanzi": "挣得", "en": "earn; gain; secure"}], "idioms": [{"hanzi": "垂死挣扎", "pinyin": "chuí sǐ zhēng zhá", "meaning_en": "make a deathbed struggle; put up a desperate last-ditch fight"}, {"hanzi": "挣扎求生", "pinyin": "zhēng zhá qiú shēng", "meaning_en": "struggle to survive amidst harsh adversity"}, {"hanzi": "自食其力", "pinyin": "zì shí qí lì", "meaning_en": "earn one's own living through one's own labor"}, {"hanzi": "日进斗金", "pinyin": "rì jìn dǒu jīn", "meaning_en": "bring in a peck of gold every day; rake in wealth"}], "character_decomposition": [{"character": "挣", "pinyin": "zhèng", "meaning_en": "earn money; struggle", "meaning_es": "ganar dinero; forcejear", "radical": "扌", "radical_meaning_en": "hand", "meaning_component": "扌 (hand engaged in hard labor)", "sound_component": "争 (zhēng, contend / strive)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound combining hand radical 扌 with phonetic 争 (strive), illustrating earning wealth through competitive bodily struggle.", "visual_mnemonic_story_en": "Diligent hands (扌) contending against all odds (争) to earn a living through honest hard labor.", "visual_mnemonic_story_es": "Manos tenaces (扌) que luchan y compiten (争) con esfuerzo para ganar honradamente el sustento diario.", "tone_mnemonic_anchor": "51", "cangjie": "QNSD", "traditional": "掙"}], "extended_reading_passages": [{"id": "#1", "hanzi": "祖辈们常说，踏踏实实挣来的钱，花起来心里才最敞亮。每一分辛苦钱都凝聚着日晒雨淋的艰辛，它教会了我们敬畏劳动、珍惜粮食，更懂得了生活最本真的分量与尊严。", "pinyin": "Zǔbèimen cháng shuō, tātāshíshí zhèng lái de qián, huā qǐlái xīnlǐ cái zuì chǎngliàng. Měi yì fēn xīnkǔqián dōu níngjù zhe rìshài-yǔlín de jiānxīn, tā jiàohuì le wǒmen jìngwèi láodòng, zhēnxī liángshi, gèng dǒngdé le shēnghuó zuì běnzhēn de fènliàng yǔ zūnyán.", "en": "Elders often said money earned with honest sweat feels lightest to spend. Every hard-earned penny crystallizes hardship under scorching sun and pouring rain, teaching us reverence for labor and the true weight of human dignity.", "es": "Los ancianos decían que el dinero ganado con honradez es el que da mayor paz al gastarse. Cada moneda atesora el esfuerzo bajo sol y lluvia, enseñándonos a valorar el trabajo y la dignidad de la vida."}, {"id": "#2", "hanzi": "在知识经济时代，人们“挣钱”的思维方式已从单纯出售体力向出售智力与创意转变。数字内容创作者与自由职业者利用平台经济开拓多元收入渠道，重塑了个体价值变现与财富积累的全新路径。", "pinyin": "Zài zhīshi jīngjì shídài, rénmen \"zhèngqián\" de sīwéi fāngshì yǐ cóng dānchún chūshòu tǐlì xiàng chūshòu zhìlì yǔ chuàngyì zhuǎnbiàn. Shùzì nèiróng chuàngzuòzhě yǔ zìyóuzhíyèzhě lìyòng píngtái jīngjì kāituò duōyuán shōurù qúdào, zhòngshù le gètǐ jiàzhí biànxiàn yǔ cáifù jīlěi de quánxīn lùjìng.", "en": "In the knowledge economy, the mindset of earning money has shifted from manual labor to monetizing intellect and creativity. Digital creators and freelancers leverage platform models to reshape avenues of individual wealth accumulation.", "es": "En la era del conocimiento, ganar dinero evoluciona del esfuerzo físico a la monetización del talento creativo. Los creadores digitales emplean economías de plataforma para diversificar ingresos y redefinir el éxito laboral."}]}, {"meanings_summary": {"en": "county; administrative subdivision below prefecture/city", "es": "condado; distrito; demarcación administrativa intermedia"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A local official affixing a seal (厶) over registry books (目) oversees the affairs of the entire county (县).", "composite_memory_hook_es": "El sello oficial (厶) estampado sobre el censo de población (目) rige los asuntos de todo el condado (县).", "cultural_and_cognitive_roots": "Originating during the Qin Dynasty's pioneering prefecture-county system (郡县制), the 'xiàn' has served for over 2,200 years as the fundamental administrative cell uniting imperial or national policy with grassroots rural life.", "tone_sandhi_and_pitch_modulation": "Pronounced in the 4th tone with a decisive falling pitch: 'xiàn' (51). Ensure the vowel ending nasal 'n' is sharp and not confused with 'xiàng'."}, "semantic_boundary_contrasts": {"core_nuance": "县 is an intermediate administrative division bridging provincial/municipal cities with grassroots towns and villages.", "contrasts": [{"id": "1", "compared_word": "县 vs. 市", "pinyin": "shì", "analysis": "县 is an administrative county centered around small towns and extensive rural land, whereas 市 denotes an urbanized prefecture, municipality, or metropolitan city."}, {"id": "2", "compared_word": "县 vs. 乡", "pinyin": "xiāng", "analysis": "县 is an upper administrative level governing numerous townships, while 乡 is a grassroots rural township subordinate to a county."}, {"id": "3", "compared_word": "县 vs. 省", "pinyin": "shěng", "analysis": "县 is a local district level, whereas 省 is the highest provincial administrative tier governing multiple cities and counties."}]}, "traps_and_cognates": {"look_alikes": [{"character": "且", "pinyin": "qiě", "meaning_en": "and; moreover; just", "distinction_note": "Lacks the upper 厶 component present in 县"}, {"character": "具", "pinyin": "jù", "meaning_en": "tool; possess", "distinction_note": "Has an upper horizontal shelter stroke and two dots inside"}, {"character": "直", "pinyin": "zhí", "meaning_en": "straight; direct", "distinction_note": "Has a vertical cross line at the top"}, {"character": "真", "pinyin": "zhēn", "meaning_en": "true; real", "distinction_note": "Has an upper cross and base strokes unlike 县"}], "etymological_cognates": [{"character": "县城", "pinyin": "xiàn chéng", "gloss_en": "county seat"}, {"character": "县志", "pinyin": "xiàn zhì", "gloss_en": "county annals / chronicles"}, {"character": "悬挂", "pinyin": "xuán guà", "gloss_en": "suspend; hang (etymological cognate sharing ancient 縣 root)"}, {"character": "郡县", "pinyin": "jùn xiàn", "gloss_en": "commanderies and counties (Qin administrative system)"}]}, "id": "13", "hanzi": "县", "pinyin": "xiàn", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "an administrative division in China subordinate to a prefecture or city, governing townships and villages", "definition_es": "condado; demarcación administrativa bajo la prefectura que administra pueblos", "example_phrase": "县城 (county seat / county town)"}], "example_sentences": [{"id": "#1", "hanzi": "他在沿海打工多年，终于攒够了钱在老家的县城买下了一套宽敞明亮的楼房。", "pinyin": "Tā zài yánhǎi dǎgōng duōnián, zhōngyú zǎn gòu le qián zài lǎojiā de xiànchéng mǎi xià le yí tào kuānchǎng míngliàng de lóufáng.", "en": "After working along the coast for years, he finally saved enough money to buy a spacious and bright apartment in his home county seat.", "es": "Tras trabajar años en la costa, reunió suficiente dinero para comprar un piso amplio y luminoso en la cabecera de su condado natal."}, {"id": "#2", "hanzi": "为了缩小区域发展差距，国家大力扶持中西部各县发展特色农业与文化旅游优势产业。", "pinyin": "Wèile suōxiǎo qūyù fāzhǎn chājù, guójiā dàlì fúchí zhōng-xībù gè xiàn fāzhǎn tèsè nóngyè yǔ wénhuà lǚyóu yōushì chǎnyè.", "en": "To narrow regional development disparities, the state vigorously supports central and western counties in developing specialty agriculture and cultural tourism.", "es": "Para mitigar las brechas de desarrollo regional, el Estado impulsa en los condados del centro y oeste la agricultura autóctona y el turismo cultural."}], "collocations": [{"hanzi": "县城", "en": "county seat; county town"}, {"hanzi": "县长", "en": "county magistrate; county mayor"}, {"hanzi": "县政府", "en": "county government"}, {"hanzi": "全县", "en": "the entire county"}, {"hanzi": "偏远县", "en": "remote county"}, {"hanzi": "贫困县", "en": "impoverished county"}], "idioms": [{"hanzi": "他山之石", "pinyin": "tā shān zhī shí", "meaning_en": "stones from other hills can polish jade; learn from others' experience"}, {"hanzi": "一方水土", "pinyin": "yì fāng shuǐ tǔ", "meaning_en": "a particular natural environment nurtures its local inhabitants"}, {"hanzi": "安贫乐道", "pinyin": "ān pín lè dào", "meaning_en": "contented with poverty and devoted to spiritual pursuit"}, {"hanzi": "保境息民", "pinyin": "bǎo jìng xī mín", "meaning_en": "safeguard one's territory and bring peace to the populace"}], "character_decomposition": [{"character": "县", "pinyin": "xiàn", "meaning_en": "county; district", "meaning_es": "condado; distrito administrativo", "radical": "厶", "radical_meaning_en": "private / cocoon", "meaning_component": "系 (traditional silk thread tether)", "sound_component": "目 (inverted head in archaic form)", "stroke_count": "7", "composition_type": "上下结构", "etymology_and_mnemonic": "Simplified from traditional 縣, originally depicting an inverted head suspended by silk (tethered jurisdiction dependent on the central court).", "visual_mnemonic_story_en": "An administrative official's seal (厶) placed atop recorded registers (目/且) to govern a regional county.", "visual_mnemonic_story_es": "El sello de un magistrado (厶) estampado sobre los libros de registro (目/且) para gobernar un condado.", "tone_mnemonic_anchor": "51", "cangjie": "BVI", "traditional": "縣"}], "extended_reading_passages": [{"id": "#1", "hanzi": "穿过那座青石拱桥，就进入了县城的老街。两旁的店铺挂着手写的老招牌，茶馆里传来热热闹闹的说书声。这座古老的小县城，承载着数代人的悲欢离合，在时代变迁中守着自己的安宁。", "pinyin": "Chuānguò nà zuò qīngshí gǒngqiáo, jiù jìnrù le xiànchéng de lǎojiē. Liǎngpáng de diànpù guà zhe shǒuxiě de lǎo zhāopai, cháguǎn lǐ chuánlái rèrènàonào de shuōshū shēng. Zhè zuò gǔlǎo de xiǎoxiànchéng, chéngzài zhe shù dài rén de bēihuān-líhé, zài shídài biànqiān zhōng shǒu zhe zìjǐ de ānníng.", "en": "Crossing the blue-stone arched bridge leads into the old street of the county seat. Shops on both sides hang hand-painted signs while storytelling echoes from teahouses. This ancient small county town holds generations of joys and sorrows.", "es": "Al cruzar el puente de piedra se entra en la calle vieja de la cabecera comarcal. Las tiendas exhiben rótulos tradicionales y el salón de té bulle de narradores populares. Esta comarca histórica custodia con sosiego la memoria de generaciones."}, {"id": "#2", "hanzi": "“县域经济”是中国国民经济发展的重要基石。当前，县域正成为承接大中城市产业转移与吸纳农村富余劳动力的核心载体。健全县城基础设施与公共服务配套，对于推进新型城镇化建设具有深远的战略意义。", "pinyin": "\"Xiànyù jīngjì\" shì Zhōngguó guómín jīngjì fāzhǎn de zhòngyào jīshí. Dāngqián, xiànyù zhèng chéngwéi chéngjiē dàzhōng chéngshì chǎnyè zhuǎnyí yǔ xīnà nóngcūn fùyú láodònglì de héxīn zàitǐ. Jiànquán xiànchéng jīchǔ shèshī yǔ gōnggòng fúwù pèitào, duìyú tuījìn xīnxíng chéngzhènhuà jiànshè jùyǒu shēnyuǎn de zhànlüè yìyì.", "en": "The county economy is an essential cornerstone of China's national economy. Today, county regions act as key vehicles absorbing industrial relocation and rural surplus labor. Improving county public services carries strategic significance for urbanization.", "es": "La economía comarcal es un pilar vertebral del desarrollo nacional. Los condados absorben la transferencia industrial de las metrópolis y canalizan el empleo rural. Mejorar los servicios públicos comarcales impulsa decisivamente la urbanización equilibrada."}]}, {"meanings_summary": {"en": "set; suite; series; cover; sheath; to encase; conventional formula", "es": "juego; conjunto; serie; funda; cubierta; enfundar; juego (clasificador para pisos)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A large (大) and long (镸) cover slips perfectly over items to form a complete matched set (套).", "composite_memory_hook_es": "Una funda grande (大) y larga (镸) que se ajusta a las prendas para formar un conjunto completo (套).", "cultural_and_cognitive_roots": "In Chinese material culture, '套' conceptualizes wholeness through fitting integration—whether a set of ritual furniture, an interconnected courtyard suite, or a protective embroidered cover.", "tone_sandhi_and_pitch_modulation": "Pronounced in the 4th tone with a firm falling pitch: 'tào' (51). When following '一' (yī), '一' shifts to 2nd tone: 'yí tào' (35-51)."}, "semantic_boundary_contrasts": {"core_nuance": "套 designates an interrelated system or collection forming an organic, matched, or complete functional unit.", "contrasts": [{"id": "1", "compared_word": "套 vs. 件", "pinyin": "jiàn", "analysis": "套 classifies multi-piece composite sets or entire dwellings (e.g. 一套衣服, 一套房), whereas 件 classifies single standalone articles (e.g. 一件衣服, 一件事)."}, {"id": "2", "compared_word": "套 vs. 组", "pinyin": "zǔ", "analysis": "套 stresses complete, self-contained functional unity (e.g. 一套家具), while 组 emphasizes combinatorial groupings or research teams (e.g. 一组数据, 一个研究组)."}, {"id": "3", "compared_word": "套 vs. 间", "pinyin": "jiān", "analysis": "套 refers to a whole private apartment containing multiple chambers, while 间 designates a single discrete partitioned room (e.g. 一间卧室)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "肆", "pinyin": "sì", "meaning_en": "four (formal); reckless", "distinction_note": "Has 镸 on the left with 聿 on the right"}, {"character": "契", "pinyin": "qì", "meaning_en": "contract; deed", "distinction_note": "Has 丰 and 刀 beneath 大 instead of 镸"}, {"character": "奢", "pinyin": "shē", "meaning_en": "luxurious; extravagant", "distinction_note": "Has 者 below 大 instead of 镸"}, {"character": "奖", "pinyin": "jiǎng", "meaning_en": "award; prize", "distinction_note": "Has 将 on top and 大 below; inverse positioning"}], "etymological_cognates": [{"character": "配套", "pinyin": "pèi tào", "gloss_en": "complete set; provide supporting facilities"}, {"character": "圈套", "pinyin": "quān tào", "gloss_en": "trap; snare"}, {"character": "手套", "pinyin": "shǒu tào", "gloss_en": "gloves"}, {"character": "套房", "pinyin": "tào fáng", "gloss_en": "suite of rooms"}]}, "id": "14", "hanzi": "套", "pinyin": "tào", "level": "HSK 5", "part_of_speech": "Measure Word", "senses": [{"sense_number": "1", "part_of_speech": "Measure Word", "register": "Standard", "definition_en": "classifier for sets of things, suites of rooms/apartments, books, or suits of clothing", "definition_es": "clasificador para conjuntos, trajes, pisos o juegos", "example_phrase": "一套房子 (an apartment / a suite of rooms)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "sheath, cover, case, or glove slipped over an object", "definition_es": "funda; cubierta; guante protector", "example_phrase": "被套 (quilt cover)"}, {"sense_number": "3", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to slip over; to encase; to tie up; to coax information", "definition_es": "enfundar; encajar; envolver; sonsacar", "example_phrase": "套上外套 (slip on an overcoat)"}], "example_sentences": [{"id": "#1", "hanzi": "经过多年的勤俭节约，夫妻俩终于在市中心按揭购买了一套属于自己的两居室公寓。", "pinyin": "Jīngguò duōnián de qínjiǎn jiéyuē, fūqī liǎ zhōngyú zài shìzhōngxīn ànjiē gòumǎi le yí tào shǔyú zìjǐ de liǎngjūshì gōngyù.", "en": "Through years of thrift and frugality, the couple finally purchased a two-bedroom apartment of their own through a mortgage downtown.", "es": "Tras años de ahorro y austeridad, el matrimonio compró con hipoteca un piso de dos dormitorios en el centro urbano."}, {"id": "#2", "hanzi": "这套关于中国传统节令民俗的丛书考据详实、图文并茂，深受广大文史学者与读者的喜爱。", "pinyin": "Zhè tào guānyú Zhōngguó chuántǒng jiélìng mínsú de cóngshū kǎojù xiángshí, túwén-bìngmào, shēn shòu guǎngdà wénshǐ xuézhě yǔ dúzhě de xǐ'ài.", "en": "This multi-volume series on traditional Chinese seasonal folklore features rigorous scholarship and exquisite illustrations, highly loved by scholars.", "es": "Esta serie de libros sobre costumbres y fiestas estacionales tradicionales cuenta con rigurosa erudición e ilustraciones, muy aplaudida por eruditos."}], "collocations": [{"hanzi": "一套房子", "en": "an apartment / house"}, {"hanzi": "一套西装", "en": "a suit of Western clothing"}, {"hanzi": "一套方案", "en": "a complete plan or scheme"}, {"hanzi": "沙发套", "en": "sofa slipcover"}, {"hanzi": "手套", "en": "gloves; mittens"}, {"hanzi": "套近乎", "en": "cozy up to; try to win someone's favor"}], "idioms": [{"hanzi": "陈词滥调", "pinyin": "chén cí làn diào", "meaning_en": "worn-out clichés; hackneyed platitudes (talking in stereotypes/套话)"}, {"hanzi": "设局圈套", "pinyin": "shè jú quān tào", "meaning_en": "set up an elaborate snare or trap"}, {"hanzi": "相辅相成", "pinyin": "xiāng fǔ xiāng chéng", "meaning_en": "complement each other in an integrated system"}, {"hanzi": "层出不穷", "pinyin": "céng chū bù qióng", "meaning_en": "emerge one after another in an endless series"}], "character_decomposition": [{"character": "套", "pinyin": "tào", "meaning_en": "cover; sheath; set; loop", "meaning_es": "funda; juego; conjunto; encajar", "radical": "大", "radical_meaning_en": "big / great", "meaning_component": "大 (large outer covering)", "sound_component": "镸 (cháng, long / extensive)", "stroke_count": "10", "composition_type": "上下结构", "etymology_and_mnemonic": "Ideogrammic compound of big (大) over long (镸), signifying a large garment or cover enclosing an entire set.", "visual_mnemonic_story_en": "A big (大) outer garment designed long (镸) to slip comfortably over an entire matching outfit.", "visual_mnemonic_story_es": "Una prenda amplia (大) y larga (镸) concebida para enfundar y cubrir un conjunto completo de ropa.", "tone_mnemonic_anchor": "51", "cangjie": "KMMI", "traditional": "套"}], "extended_reading_passages": [{"id": "#1", "hanzi": "拥有这一套真正属于自己的居所，是普通人最踏实的幸福。夕阳洒在客厅淡米色的地板上，看着亲手挑选的这套原木餐桌与布艺沙发，奔波半生的疲惫在这一瞬间化作了安心的微笑。", "pinyin": "Yōngyǒu zhè yí tào zhēnzhèng shǔyú zìjǐ de jūsuǒ, shì pǔtōngrén zuì tàshi de xìngfú. Xīyáng sǎ zài kètīng dànmǐsè de dìbǎn shàng, kàn zhe qīnshǒu tiāoxuǎn de zhè tào yuánmù cānzhuō yǔ bùyì shāfā, bēnbō bànshēng de píbèi zài zhè yí shùnjiān huàzuò le ānxīn de wēixiào.", "en": "Owning a residential apartment truly belonging to oneself is the most grounded happiness for ordinary people. Sunset washes over beige flooring, illuminating the chosen wooden table and cloth sofa; the weariness of half a lifetime turns into a tranquil smile.", "es": "Poseer un piso verdaderamente propio constituye la dicha más sólida para la gente corriente. El sol poniente baña el suelo y acaricia la mesa de madera y el sofá elegidos a mano; las fatigas de media vida se truecan en paz."}, {"id": "#2", "hanzi": "现代化城市住宅配套建设已步入系统化阶段。从单一的居住单元开发，延伸至涵盖医疗、教育与商业网点的一整套生活服务链。高品质的居住环境不再仅指房屋本身，更依托于社区整体生态的完善度。", "pinyin": "Xiàndàihuà chéngshì zhùzhái pèitào jiànshè yǐ bùrù xìtǒnghuà jiēduàn. Cóng dānyī de jūzhù dānyuán kāifā, yánshēn zhì hángài yīliáo, jiàoyù yǔ shāngyè wǎngdiǎn de yì zhěng tào shēnghuó fúwù liàn. Gāopǐnzhì de jūzhù huánjìng bú zài jǐn zhǐ fángwū běnshēn, gèng yītuō yú shèqū zhěngtǐ shēngtài de wánshàndù.", "en": "Supporting construction for modern urban housing has entered a systemic stage. From single residential units, it extends to an entire suite of service chains spanning healthcare, schooling, and commerce. Quality of life depends on the holistic neighborhood ecosystem.", "es": "La edificación de vivienda urbana moderna es ya una obra integral. Evoluciona del bloque residencial aislado a un conjunto completo de servicios sanitarios, educativos y comerciales que garantizan el bienestar vecinal."}]}, {"meanings_summary": {"en": "to decorate; to renovate; to fit out (an interior); interior decoration", "es": "renovar; remodelar; decorar (una vivienda); decoración de interiores"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Outfitting a living space with fine fixtures (装) and polishing each surface with care (修) produces a beautiful renovation (装修).", "composite_memory_hook_es": "Dotar la vivienda de buen equipamiento (装) y pulir sus paredes con esmero (修) culmina en una gran reforma (装修).", "cultural_and_cognitive_roots": "In modern Chinese society, '装修' represents the ritual transition from an empty concrete shell ('毛坯房') into a sanctified, personalized family hearth, reflecting aesthetic tastes and hard-earned prosperity.", "tone_sandhi_and_pitch_modulation": "Pronounced with paired high-level tones: 'zhuāng xiū' (55-55). Maintain a sustained high, steady pitch across both syllables without dipping."}, "semantic_boundary_contrasts": {"core_nuance": "装修 specifically refers to architectural interior fit-out, carpentry, tiling, and aesthetic decoration of spaces.", "contrasts": [{"id": "1", "compared_word": "装修 vs. 修理", "pinyin": "xiūlǐ", "analysis": "装修 focuses on beautifying and installing interior fittings for homes or offices, whereas 修理 refers to fixing broken machinery, electronics, or equipment (e.g. 修理汽车, 修理手机)."}, {"id": "2", "compared_word": "装修 vs. 装饰", "pinyin": "zhuāngshì", "analysis": "装修 involves structural carpentry, plastering, plumbing, and wall tiling, while 装饰 refers to surface adornment, decorative trinkets, or aesthetic motifs (e.g. 装饰画, 装饰品)."}, {"id": "3", "compared_word": "装修 vs. 改建", "pinyin": "gǎijiàn", "analysis": "装修 deals with indoor surface finishes and furnishing, whereas 改建 involves reconstructing or modifying external architectural frameworks and structural walls."}]}, "traps_and_cognates": {"look_alikes": [{"character": "袋", "pinyin": "dài", "meaning_en": "bag; pocket", "distinction_note": "Has 代 on top of 衣 instead of 壮"}, {"character": "裳", "pinyin": "shang", "meaning_en": "skirt; lower garment", "distinction_note": "Has 尚 on top of 衣 instead of 壮"}, {"character": "条", "pinyin": "tiáo", "meaning_en": "strip; clause", "distinction_note": "Upper structure differs from 修; has 木 at bottom"}, {"character": "徐", "pinyin": "xú", "meaning_en": "slowly; gentle", "distinction_note": "Has 彳 (step) on the left instead of 亻 with 攸"}], "etymological_cognates": [{"character": "修理", "pinyin": "xiū lǐ", "gloss_en": "repair; fix"}, {"character": "修养", "pinyin": "xiū yǎng", "gloss_en": "personal cultivation; refinement"}, {"character": "装置", "pinyin": "zhuāng zhì", "gloss_en": "device; apparatus; installation"}, {"character": "装备", "pinyin": "zhuāng bèi", "gloss_en": "equipment; outfit"}]}, "id": "15", "hanzi": "装修", "pinyin": "zhuāng xiū", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to renovate, decorate, and install fixtures in a building or apartment", "definition_es": "reformar; remodelar o decorar los interiores de un inmueble", "example_phrase": "装修新房 (renovate a new apartment)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "interior decoration, renovation works, or fit-out", "definition_es": "reforma; obras de decoración interior", "example_phrase": "豪华装修 (luxurious interior decor)"}], "example_sentences": [{"id": "#1", "hanzi": "新买的房子刚装修完，为了家人的身体健康，母亲特意让窗户大开通风散味了整整三个月。", "pinyin": "Xīn mǎi de fángzi gāng zhuāngxiū wán, wèile jiārén de shēntǐ jiànkāng, mǔqīn tèyì ràng chuānghu dà kāi tōngfēng sǎnwèi le zhěngzhěng sān gè yuè.", "en": "The newly purchased apartment had just finished being renovated; for the family's health, mother deliberately kept the windows wide open to ventilate for three full months.", "es": "El piso recién comprado acababa de reformarse; por la salud de la familia, mi madre dejó las ventanas abiertas de par en par durante tres meses para ventilarlo."}, {"id": "#2", "hanzi": "该连锁酒店聘请了国际知名设计团队进行室内装修升级，全面融入环保建材与智能化客房控制系统。", "pinyin": "Gāi liánsuǒ jiǔdiàn pìnqǐng le guójì zhīmíng shèjì tuánduì jìnxíng shìnèi zhuāngxiū shēngjí, quánmiàn róngrù huánbǎo jiàncái yǔ zhìnénghuà kèfáng kòngzhì xìtǒng.", "en": "The hotel chain hired an internationally renowned design team to upgrade its interior renovation, integrating eco-friendly materials and smart room controls.", "es": "La cadena hotelera contrató a un célebre equipo de diseño para renovar la decoración interior, incorporando materiales ecológicos y domótica avanzada."}], "collocations": [{"hanzi": "装修风格", "en": "decoration style; interior aesthetic"}, {"hanzi": "室内装修", "en": "interior renovation / fit-out"}, {"hanzi": "豪华装修", "en": "luxurious renovation"}, {"hanzi": "简单装修", "en": "simple / basic renovation"}, {"hanzi": "装修工人", "en": "interior decoration / renovation worker"}, {"hanzi": "装修污染", "en": "renovation pollution (fumes/formaldehyde)"}], "idioms": [{"hanzi": "富丽堂皇", "pinyin": "fù lì táng huáng", "meaning_en": "sumptuous and magnificent; majestic and splendid"}, {"hanzi": "美轮美奂", "pinyin": "měi lún měi huàn", "meaning_en": "magnificent and gorgeous; describing exquisite architecture"}, {"hanzi": "焕然一新", "pinyin": "huàn rán yì xīn", "meaning_en": "take on an entirely new look; refreshed and renewed"}, {"hanzi": "巧夺天工", "pinyin": "qiǎo duó tiān gōng", "meaning_en": "exquisite craftsmanship surpassing nature itself"}], "character_decomposition": [{"character": "装", "pinyin": "zhuāng", "meaning_en": "attire; pack; dress; fit out", "meaning_es": "vestir; adornar; instalar; empaquetar", "radical": "衣", "radical_meaning_en": "clothing / garments", "meaning_component": "衣 (fine garments adorning the exterior)", "sound_component": "壮 (zhuàng, robust / strong)", "stroke_count": "12", "composition_type": "上下结构", "etymology_and_mnemonic": "Phono-semantic compound where clothing (衣) signifies dressing up or outfitting a person or architectural space.", "visual_mnemonic_story_en": "Dressing a sturdy room frame (壮) in exquisite clothing and decorative fabrics (衣).", "visual_mnemonic_story_es": "Revestir la sólida estructura de un hogar (壮) con hermosas vestiduras y acabados decorativos (衣).", "tone_mnemonic_anchor": "55", "cangjie": "LVH", "traditional": "裝"}, {"character": "修", "pinyin": "xiū", "meaning_en": "decorate; repair; cultivate", "meaning_es": "reparar; adornar; cultivar; pulir", "radical": "彡", "radical_meaning_en": "hair / feathers / fine brushstrokes", "meaning_component": "彡 (delicate brush embellishment)", "sound_component": "攸 (yōu, flowing water / person)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Ancient compound depicting polishing ornaments with fine brushstrokes (彡) to attain elegance and repair defects.", "visual_mnemonic_story_en": "A craftsman using delicate brush strokes (彡) to polish, paint, and perfect interior surfaces.", "visual_mnemonic_story_es": "Un artesano aplicando delicadas pinceladas (彡) para pintar, pulir y embellecer los muros interiores.", "tone_mnemonic_anchor": "55", "cangjie": "OLOH", "traditional": "修"}], "extended_reading_passages": [{"id": "#1", "hanzi": "新房装修的每个周末，夫妻俩都满怀期待地穿梭于建材市场。从一块地砖的花纹到一盏吊灯的色调，他们亲手将对未来生活的所有憧憬，一点一滴地融入到了这个崭新的温馨居所之中。", "pinyin": "Xīnfáng zhuāngxiū de měi gè zhōumò, fūqī liǎ dōu mǎnhuái qīdài de chuānsuō yú jiàncái shìchǎng. Cóng yí kuài dìzhuān de huāwén dào yì zhǎn diàodēng de sèdiào, tāmen qīnshǒu jiāng duì wèilái shēnghuó de suǒyǒu chōngjǐng, yìdiǎn-yìdī de róngrù dào le zhè gè zhǎnxīn de wēnxīn jūsuǒ zhīzhōng.", "en": "Every weekend during the apartment renovation, the couple eagerly navigated building material markets. From tile patterns to lamp shades, they incorporated their hopes for future life into this fresh, cozy residence.", "es": "Cada fin de semana de la reforma, la pareja recorría con ilusión los almacenes de construcción. Del dibujo de las baldosas a la tonalidad de las lámparas, plasmaron con esmero sus anhelos en su nuevo y acogedor hogar."}, {"id": "#2", "hanzi": "近年来，随着居民环保意识提升，绿色家装已成为住宅装修市场的核心风向标。低碳环保建材、装配式装修工艺以及零甲醛涂料的应用，不仅缩短了工期，更从源头上筑牢了健康人居环境的生态防线。", "pinyin": "Jìnnián lái, suí zhe jūmín huánbǎo yìshí tíshēng, lǜsè jiāzhuāng yǐ chéngwéi zhùzhái zhuāngxiū shìchǎng de héxīn fēngxiàngbiāo. Dītàn huánbǎo jiàncái, zhuāngpèishì zhuāngxiū gōngyì yǐjí líng jiǎquán túliào de yìngyòng, bùjǐn suōduǎn le gōngqī, gèng cóng yuántóu shàng zhùláo le jiànkāng rénjū huánjìng de shēngtài fángxiàn.", "en": "With rising eco-awareness, green home decoration has become the benchmark of the interior renovation industry. Low-carbon materials, prefabricated fittings, and zero-formaldehyde coatings safeguard a healthy residential ecology.", "es": "Con la creciente conciencia ecológica, la reforma sostenible lidera el mercado del interiorismo. El empleo de materiales no contaminantes y prefabricados modulares acorta plazos y garantiza un hábitat residencial saludable."}]}, {"meanings_summary": {"en": "extremely; terribly; disastrous; serious; out of hand", "es": "tremendo; gravísimo; extraordinario; sumamente; una barbaridad"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Something so extreme that it cannot (不) be attained (得) or concluded (了) within normal limits is truly extraordinary (不得了).", "composite_memory_hook_es": "Algo tan desmedido que no (不) se puede abarcar (得) ni dar por terminado (了) es una auténtica barbaridad (不得了).", "cultural_and_cognitive_roots": "Originating from classical Chinese philosophical vernacular expressing boundary breach ('不得了' = incapable of closure/resolution), it evolved into a vivid emotional exclamation for extreme subjective intensity.", "tone_sandhi_and_pitch_modulation": "The headword is pronounced with flowing cadence: 'bù dé liǎo' (51-35-214). When modifying a predicate with '得', the tone carries lively oral exaggeration."}, "semantic_boundary_contrasts": {"core_nuance": "不得了 functions primarily as an exaggerated vernacular degree complement meaning 'to an astonishing degree' or as a catastrophic exclamation.", "contrasts": [{"id": "1", "compared_word": "不得了 vs. 非常", "pinyin": "fēicháng", "analysis": "不得了 is placed after an adjective with 得 (e.g. 累得不得了) with strong emotional exaggeration, whereas 非常 is a formal adverb placed before adjectives (e.g. 非常累)."}, {"id": "2", "compared_word": "不得了 vs. 了不起", "pinyin": "liǎobùqǐ", "analysis": "不得了 indicates extreme degree or impending disaster, while 了不起 expresses praise, meaning remarkable, marvelous, or admirable (e.g. 了不起的成就)."}, {"id": "3", "compared_word": "不得了 vs. 极其", "pinyin": "jíqí", "analysis": "不得了 is informal and oral, whereas 极其 is a formal written adverb of superlative degree (e.g. 极其重要)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "待", "pinyin": "dài", "meaning_en": "wait; treat", "distinction_note": "Has 寺 on the right instead of 旦+寸 (得)"}, {"character": "木", "pinyin": "mù", "meaning_en": "wood; tree", "distinction_note": "Lacks the lower left oblique stroke of 不"}, {"character": "子", "pinyin": "zǐ", "meaning_en": "child; infant", "distinction_note": "Has an extra horizontal middle stroke compared to 了"}, {"character": "行", "pinyin": "xíng", "meaning_en": "walk; alright", "distinction_note": "Has 亍 on the right instead of 旦+寸"}], "etymological_cognates": [{"character": "了解", "pinyin": "liǎo jiě", "gloss_en": "understand; comprehend"}, {"character": "了结", "pinyin": "liǎo jié", "gloss_en": "settle; wind up"}, {"character": "获得", "pinyin": "huò dé", "gloss_en": "obtain; acquire"}, {"character": "不得已", "pinyin": "bù dé yǐ", "gloss_en": "have no alternative; forced to"}]}, "id": "16", "hanzi": "不得了", "pinyin": "bù dé liǎo", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Colloquial", "definition_en": "extremely; exceedingly (used after 得 as an intensifier: Adj + 得不得了)", "definition_es": "sumamente; extraordinariamente (pospuesto a adjetivos con 得)", "example_phrase": "高兴得不得了 (terribly happy / overjoyed)"}, {"sense_number": "2", "part_of_speech": "Adjective", "register": "Colloquial", "definition_en": "disastrous; terrible; serious (indicating a catastrophic or unmanageable turn of events)", "definition_es": "terrible; catastrófico; gravísimo", "example_phrase": "那还了得，可不得了了 (that's terrible / serious trouble)"}], "example_sentences": [{"id": "#1", "hanzi": "第一次走进儿子在城里买的新房子，看到宽敞明亮的落地窗，母亲高兴得不得了。", "pinyin": "Dì-yī cì zǒujìn érzi zài chénglǐ mǎi de xīn fángzi, kàndào kuānchǎng míngliàng de luòdìchuāng, mǔqīn gāoxìng de bùdéliǎo.", "en": "Stepping into the new city apartment her son purchased for the first time and seeing the floor-to-ceiling windows, mother was overjoyed.", "es": "Al entrar por primera vez al piso nuevo que su hijo compró en la ciudad y ver las amplias cristaleras, mi madre se puso contentísima."}, {"id": "#2", "hanzi": "汛期山洪一旦冲毁村头堤坝那可就不得了了，全村的防汛抢险队伍昼夜坚守在第一线。", "pinyin": "Xùnqī shānhóng yídàn chōnghuǐ cūntóu dībà nà kě jiù bùdéliǎo le, quán cūn de fángxùn qiǎngxiǎn duìwǔ zhòuyè jiānshǒu zài dì-yī xiàn.", "en": "If mountain torrents in flood season breached the village dam it would be catastrophic; the village flood-relief crew guarded the front lines day and night.", "es": "Si las riadas quebraran la presa de la aldea sería una catástrofe; por ello las cuadrillas de emergencia montaron guardia día y noche en primera línea."}], "collocations": [{"hanzi": "高兴得不得了", "en": "overjoyed; thrilled to bits"}, {"hanzi": "热得不得了", "en": "terribly hot; scorching"}, {"hanzi": "忙得不得了", "en": "insanely busy; swamped"}, {"hanzi": "疼得不得了", "en": "hurting terribly; agonizing"}, {"hanzi": "那还不得了", "en": "that would be completely disastrous / out of hand"}, {"hanzi": "乐得不得了", "en": "delighted beyond measure"}], "idioms": [{"hanzi": "非同小可", "pinyin": "fēi tóng xiǎo kě", "meaning_en": "no small matter; extraordinary and serious"}, {"hanzi": "喜出望外", "pinyin": "xǐ chū wàng wài", "meaning_en": "overjoyed at unexpected good news; delighted beyond expectations"}, {"hanzi": "不可收拾", "pinyin": "bù kě shōu shí", "meaning_en": "out of hand; irremediable; hopelessly disorganized"}, {"hanzi": "欣喜若狂", "pinyin": "xīn xǐ ruò kuáng", "meaning_en": "wild with joy; ecstatic beyond words"}], "character_decomposition": [{"character": "不", "pinyin": "bù", "meaning_en": "not; negative", "meaning_es": "no; prefijo negativo", "radical": "一", "radical_meaning_en": "one / horizontal line", "meaning_component": "一 (firm boundary line)", "sound_component": "", "stroke_count": "4", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of a seed or bird flying upward toward the firmament line, asserting negative denial.", "visual_mnemonic_story_en": "A boundary line above a downward-branching stroke firmly denying any further extension.", "visual_mnemonic_story_es": "Un trazo delimitador superior que niega tajantemente cualquier paso hacia abajo.", "tone_mnemonic_anchor": "51", "cangjie": "MF", "traditional": ""}, {"character": "得", "pinyin": "dé", "meaning_en": "obtain; acquire; succeed", "meaning_es": "obtener; lograr; partícula modal", "radical": "彳", "radical_meaning_en": "step / walk", "meaning_component": "彳 (footsteps of progress)", "sound_component": "贝 (wealth/shell) + 寸 (hand)", "stroke_count": "11", "composition_type": "左右结构", "etymology_and_mnemonic": "Depicts taking purposeful steps (彳) while using a hand (寸) to acquire valuable treasure (贝).", "visual_mnemonic_story_en": "Taking strides (彳) to firmly grasp (寸) precious seashells (贝) into one's possession.", "visual_mnemonic_story_es": "Dar zancadas (彳) para asir firmemente (寸) valiosas conchas (贝) entre las manos.", "tone_mnemonic_anchor": "35", "cangjie": "HOAMI", "traditional": "得"}, {"character": "了", "pinyin": "liǎo", "meaning_en": "finish; settle; understand", "meaning_es": "terminar; concluir; comprender", "radical": "亅", "radical_meaning_en": "hook / standing line", "meaning_component": "亅 (hook denoting finality)", "sound_component": "子 (without arms)", "stroke_count": "2", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of an infant swaddled tight, denoting the conclusive end of birth or completion of an action.", "visual_mnemonic_story_en": "A swift hook stroke (了) drawing a line under everything to mark total completion.", "visual_mnemonic_story_es": "Un trazo limpio y curvado (了) que pone punto final a una acción concluida.", "tone_mnemonic_anchor": "214", "cangjie": "NN", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "幼年每逢过年，孩子们穿上崭新的棉袄，兜里塞满了花生和糖果，心里快活得不得了。在窄窄的村巷里追逐嬉闹，那清脆的笑声穿透冬日的寒风，成了记忆里最温暖明亮的底色。", "pinyin": "Yòunián měiféng guònián, háizimen chuān shàng zhǎnxīn de mián'ǎo, dōulǐ sāi mǎn le huāshēng hé tángguǒ, xīnlǐ kuàihuó de bùdéliǎo. Zài zhǎizhǎi de cūnxiàng lǐ zhuīzhú xīnào, nà qīngcuì de xiàoshēng chuāntòu dōngrì de hánfēng, chéngle jìyì lǐ zuì wēnnuǎn míngliàng de dǐsè.", "en": "In childhood at New Year, kids wore new cotton coats with pockets stuffed with peanuts and candies, overjoyed beyond words. Frolicking along narrow village lanes, our laughter pierced the chilly wind, painting the warmest memories.", "es": "En la niñez, al llegar el Año Nuevo, los niños estrenaban abrigos y llenaban sus bolsillos de cacahuetes y dulces, contentísimos. Corrían por los callejones nevados y sus risas claras templaban el invierno."}, {"id": "#2", "hanzi": "在复杂的工业控制系统中，哪怕是微小的信号抖动，如果引发级联放大效应，后果也会严重得不得了。因此，系统架构师必须在各关键子模块之间设置严格的安全冗余隔离，确保整体稳定受控。", "pinyin": "Zài fùzá de gōngyè kòngzhì xìtǒng zhōng, nǎpà shì wēixiǎo de xìnhào dǒudòng, rúguǒ yǐnfā jílián fàngdà xiàoyìng, hòuguǒ yě huì yánzhòng de bùdéliǎo. Yīncǐ, xìtǒng jiàgòushī bìxū zài gè guānjiàn zǐmókuài zhījiān shèzhì yángé de ānquán rǒngyú gélí, quèbǎo zhěngtǐ wěndìng shòukòng.", "en": "In intricate industrial control systems, even minute signal jitter, if triggering cascade amplification, could lead to catastrophic consequences. Hence architects must install safety redundancy barriers between critical submodules.", "es": "En sistemas industriales complejos, una leve oscilación de señal puede desatar efectos en cascada gravísimos. Por ello, los ingenieros instalan aislamientos redundantes para garantizar el control riguroso de cada módulo."}]}, {"meanings_summary": {"en": "to be drunk; intoxicated; enchanted; infatuated with", "es": "emborracharse; embriagarse; estar ebrio; extasiarse; cautivado"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Drinking liquor from a wine vessel (酉) to the utmost limit (卒) leaves one completely drunk (醉).", "composite_memory_hook_es": "Beber de la vasija de vino (酉) hasta agotar la última gota (卒) deja a cualquiera ebrio (醉).", "cultural_and_cognitive_roots": "In classical Chinese literature, '醉' transcends mere alcohol intake; from Li Bai to Su Shi, drunkenness served as an aesthetic and spiritual liberation from mundane constraints into transcendent artistic ecstasy.", "tone_sandhi_and_pitch_modulation": "Pronounced in the 4th tone with a decisive dropping pitch: 'zuì' (51). Distinct from 1st tone 'zuī' (as in 咀)."}, "semantic_boundary_contrasts": {"core_nuance": "醉 describes the physiological state of alcohol intoxication or psychological enchantment and aesthetic ecstasy.", "contrasts": [{"id": "1", "compared_word": "醉 vs. 醒", "pinyin": "xǐng", "analysis": "醉 is the state of intoxication or loss of sobriety, whereas 醒 is its direct antonym, meaning regaining consciousness, waking up, or becoming sober."}, {"id": "2", "compared_word": "醉 vs. 迷", "pinyin": "mí", "analysis": "醉 implies blissful intoxication or sensory absorption, while 迷 suggests losing direction, being infatuated, confused, or obsessed with something (e.g. 迷失方向, 追星着迷)."}, {"id": "3", "compared_word": "醉 vs. 晕", "pinyin": "yūn", "analysis": "醉 is caused by alcohol or overwhelming joy, whereas 晕 denotes physiological dizziness, vertigo, motion sickness, or faintness (e.g. 晕车, 头晕)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "碎", "pinyin": "suì", "meaning_en": "broken; smashed", "distinction_note": "Has 石 (stone) on the left instead of 酉 (wine jar)"}, {"character": "粹", "pinyin": "cuì", "meaning_en": "pure; unadulterated", "distinction_note": "Has 米 (rice) on the left instead of 酉"}, {"character": "醒", "pinyin": "xǐng", "meaning_en": "wake up; sober up", "distinction_note": "Has 星 on the right instead of 卒; direct semantic antonym"}, {"character": "配", "pinyin": "pèi", "meaning_en": "match; allocate", "distinction_note": "Has 己 on the right instead of 卒"}], "etymological_cognates": [{"character": "酒", "pinyin": "jiǔ", "gloss_en": "wine; liquor; alcoholic drink"}, {"character": "配", "pinyin": "pèi", "gloss_en": "match; blend wine ingredients"}, {"character": "酪", "pinyin": "lào", "gloss_en": "fermented dairy / cheese"}, {"character": "酷", "pinyin": "kù", "gloss_en": "cruel; intense; cool (originally strong fermented liquor taste)"}]}, "id": "17", "hanzi": "醉", "pinyin": "zuì", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to become intoxicated by alcohol", "definition_es": "emborracharse; intoxicarse por el alcohol", "example_phrase": "喝醉了 (got drunk)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Literary", "definition_en": "to be deeply enchanted, captivated, or fascinated by scenery, art, or affection", "definition_es": "embriagarse de emoción; extasiarse con la belleza", "example_phrase": "令人陶醉 (intoxicating / enchanting)"}, {"sense_number": "3", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to cook or steep food in liquor or rice wine", "definition_es": "adobar o marinar con licor", "example_phrase": "醉虾 (drunken shrimp)"}], "example_sentences": [{"id": "#1", "hanzi": "儿子考上重点大学那晚，平日滴酒不沾的父亲破例多喝了几杯，脸色微红，彻底醉倒在沙发上。", "pinyin": "Érzi kǎoshàng zhòngdiǎn dàxué nà wǎn, píngrì dījiǔ-bùzhān de fùqīn pòlì duō hē le jǐ bēi, liǎnsè wēihóng, chèdǐ zuì dǎo zài shāfā shàng.", "en": "The night his son got admitted into a key university, father who usually never touched a drop broke his rule, drank several cups, blushed red, and fell asleep drunk on the sofa.", "es": "La noche en que su hijo ingresó en la universidad, el padre, que jamás probaba alcohol, bebió varias copas de emoción y cayó dormido ebrio en el sofá."}, {"id": "#2", "hanzi": "漫步在初春盛放的油菜花海中，微风轻拂送来阵阵清香，游人们无不沉醉在这如诗如画的田园风光里。", "pinyin": "Mànbù zài chūchūn shèngfàng de yóucàihuā hǎi zhōng, wēifēng qīngfú sòng lái zhènzhèn qīngxiāng, yóurénmen wúbù chénzuì zài zhè rúshī-rúhuà de tiányuán fēngguāng lǐ.", "en": "Strolling through rapeseed blossoms blooming in early spring, a gentle breeze wafted fragrance; tourists were all enchanted by this picturesque countryside scenery.", "es": "Paseando entre campos dorados de colza en flor, la brisa traía aromas frescos; todos los viajeros se extasiaban con aquel paisaje campestre poético."}], "collocations": [{"hanzi": "喝醉", "en": "get drunk; intoxicated"}, {"hanzi": "沉醉", "en": "deeply intoxicated / immersed in"}, {"hanzi": "陶醉", "en": "revel in; be enchanted by"}, {"hanzi": "醉鬼", "en": "drunkard; drunk"}, {"hanzi": "微醉", "en": "tipsy; slightly drunk"}, {"hanzi": "醉意", "en": "signs or feeling of drunkenness"}], "idioms": [{"hanzi": "醉生梦死", "pinyin": "zuì shēng mèng sǐ", "meaning_en": "lead a drunken dream-like stupor; live aimlessly and indulgently"}, {"hanzi": "如痴如醉", "pinyin": "rú chī rú zuì", "meaning_en": "completely entranced and infatuated as if spellbound"}, {"hanzi": "纸醉金迷", "pinyin": "zhǐ zuì jīn mí", "meaning_en": "dazzling luxury and decadent dissipation"}, {"hanzi": "自我陶醉", "pinyin": "zì wǒ táo zuì", "meaning_en": "self-intoxicated; smugly infatuated with oneself"}], "character_decomposition": [{"character": "醉", "pinyin": "zuì", "meaning_en": "drunk; intoxicated; enchanted", "meaning_es": "ebrio; embriagado; cautivado", "radical": "酉", "radical_meaning_en": "wine vessel / fermented wine", "meaning_component": "酉 (wine jar fermenting spirits)", "sound_component": "卒 (zú, extreme limit / soldier)", "stroke_count": "15", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where a wine jar (酉) filled to the extreme limit (卒) causes a drinker to become intoxicated.", "visual_mnemonic_story_en": "Drinking wine from an earthenware jar (酉) down to the very last drop (卒) makes one delightfully drunk.", "visual_mnemonic_story_es": "Beber el licor de la tinaja (酉) hasta el último sorbo (卒) deja al comensal felizmente embriagado.", "tone_mnemonic_anchor": "51", "cangjie": "MWYJ", "traditional": "醉"}], "extended_reading_passages": [{"id": "#1", "hanzi": "故乡的金秋总是令人心醉神迷。院子里的桂花落了满满一地，浓郁的甜香随着夜风弥漫在空气里。一家人围坐在一起品尝新酿的米酒，微醉之中，欢声笑语将整个秋夜染得格外明亮。", "pinyin": "Gùxiāng de jīnqiū zǒngshì lìngrén xīnzùishénmí. Yuànzi lǐ de guìhuā luò le mǎnmǎn yí dì, nóngyù de tiánxiāng suí zhe yèfēng mímàn zài kōngqì lǐ. Yì jiā rén wéizuò zài yìqǐ pǐncháng xīn niàng de mǐjiǔ, wēizuì zhīzhōng, huānshēng-xiàoyǔ jiāng zhěnggè qiūyè rǎn de géwài míngliàng.", "en": "Golden autumn in my hometown is always captivating. Osmanthus blossoms scatter across the yard, sweet aroma wafting on night breezes. Sipping sweet rice wine together, our tipsy laughter lit up the autumn night.", "es": "El otoño dorado de mi pueblo natal siempre embriaga los sentidos. Las flores de osmanto alfombran el patio perfumando la brisa. Al probar el licor de arroz en familia, la alegre ebriedad ilumina la noche otoñal."}, {"id": "#2", "hanzi": "在中国古典诗学中，“醉”往往是文人摆脱世俗规训、进入审美自由境界的催化剂。陶渊明借酒远避尘俗，李白则以醉态挥洒诗情。酒意并非逃避，而是诗人与天地造化精神往来的独特精神仪式。", "pinyin": "Zài Zhōngguó gǔdiǎn shīxué zhōng, \"zuì\" wǎngwǎng shì wénrén bǎituō shìsú guīxùn, jìnrù shěnměi zìyóu jìngjiè de cuīhuàjì. Táo Yuānmíng jiè jiǔ yuǎnbì chénsú, Lǐ Bái zé yǐ zuìtài huīsǎ shīqíng. Jiǔyì bìng fēi táobì, ér shì shīrén yǔ tiāndì zàohuà jīngshén wǎnglái de dútè jīngshén yíshì.", "en": "In classical Chinese poetics, drunkenness often catalyzed literary liberation into aesthetic freedom. Tao Yuanming shunned worldly cares through wine, while Li Bai poured poetry in drunken ecstasy, conversing with the universe.", "es": "En la poética clásica china, la embriaguez liberaba al literato de las ataduras mundanas hacia el éxtasis creador. Lejos de ser evasión vulgar, constituía un ritual espiritual de comunión con la naturaleza."}]}, {"meanings_summary": {"en": "strong; intense; vehement; sharp; violent", "es": "fuerte; intenso; vehemente; agudo; violento"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Combining the elastic force of a tense bow (强) with blazing fire (烈) creates an intensely powerful impact (强烈).", "composite_memory_hook_es": "Unir la fuerza de un arco tenso (强) con el fuego ardiente (烈) produce un impacto intensísimo (强烈).", "cultural_and_cognitive_roots": "In ancient natural philosophy, '烈' signifies fire at peak combustion while '强' denotes muscular or structural tenacity; together they embody forces that overcome resistance by sheer energy density.", "tone_sandhi_and_pitch_modulation": "Pronounced with a 35-51 pitch contour (2nd tone rising steadily, followed by 4th tone dropping with explosive force). Emphasize the crisp, punchy articulation on 'liè'."}, "semantic_boundary_contrasts": {"core_nuance": "强烈 conveys extreme concentration of energy, high sensory impact, or fervent emotional force.", "contrasts": [{"id": "1", "compared_word": "强烈 vs. 激烈", "pinyin": "jīliè", "analysis": "强烈 describes sensations, emotions, desire, or physical elements (e.g. 强烈光线, 强烈愿望), whereas 激烈 applies to dynamic competitive clashes, battles, or debates (e.g. 激烈竞争, 激烈争吵)."}, {"id": "2", "compared_word": "强烈 vs. 剧烈", "pinyin": "jùliè", "analysis": "强烈 highlights intensity of feeling, brightness, or demands, while 剧烈 emphasizes violent physical bodily convulsions or shaking motion (e.g. 剧烈运动, 剧烈疼痛)."}, {"id": "3", "compared_word": "强烈 vs. 浓烈", "pinyin": "nóngliè", "analysis": "强烈 applies to light, feelings, or arguments, while 浓烈 is restricted to dense fragrances, thick smoke, or heavy colors (e.g. 浓烈的香水味, 浓烈的色彩)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "列", "pinyin": "liè", "meaning_en": "row; array; line", "distinction_note": "Standalone phonetic root without the lower fire radical 灬"}, {"character": "照", "pinyin": "zhào", "meaning_en": "photograph; illuminate", "distinction_note": "Has 昭 on top of 灬 instead of 列"}, {"character": "弱", "pinyin": "ruò", "meaning_en": "weak; frail", "distinction_note": "Two bows back to back; direct semantic antonym of 强"}, {"character": "弦", "pinyin": "xián", "meaning_en": "string; chord", "distinction_note": "Has 玄 on the right of 弓 instead of 虽"}], "etymological_cognates": [{"character": "热烈", "pinyin": "rè liè", "gloss_en": "warm; enthusiastic; fervent"}, {"character": "激烈", "pinyin": "jī liè", "gloss_en": "intense; fierce; heated"}, {"character": "富强", "pinyin": "fù qiáng", "gloss_en": "rich and powerful; prosperous"}, {"character": "倔强", "pinyin": "jué jiàng", "gloss_en": "stubborn; unyielding; obstinate"}]}, "id": "18", "hanzi": "强烈", "pinyin": "qiáng liè", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "having immense physical force, brightness, scent, or impact", "definition_es": "fuerte; intenso en luz, olor o fuerza física", "example_phrase": "强烈的光线 (intense light beam)"}, {"sense_number": "2", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "vehement and passionate in feeling, desire, demand, or opposition", "definition_es": "vehemente; ardiente; apasionado en sentimientos o demandas", "example_phrase": "强烈的愿望 (strong desire)"}], "example_sentences": [{"id": "#1", "hanzi": "初夏午后的阳光十分强烈，母亲特意把厚厚的冬被抱到院子里暴晒，以便彻底杀灭潮气与细菌。", "pinyin": "Chūxià wǔhòu de yángguāng shífēn qiángliè, mǔqīn tèyì bǎ hòuhòu de dōngbèi bào dào yuànzi lǐ bàoshài, yǐbiàn chèdǐ shāmiè cháoqì yǔ xìjūn.", "en": "Early summer afternoon sunshine was exceptionally intense; mother took the thick winter quilts into the yard to bake under the sun to destroy moisture and germs.", "es": "El sol de la siesta estival pegaba muy fuerte; mi madre sacó los gruesos edredones de invierno al patio para secarlos al sol y eliminar la humedad."}, {"id": "#2", "hanzi": "该国企图单方面修改贸易规则的做法，遭到了国际社会与周边多个邻国的强烈谴责与坚决抵制。", "pinyin": "Gāi guó qǐtú dānfāngmiàn xiūgǎi màoyì guīzé de zuòfǎ, zāodào le guójì shèhuì yǔ zhōubiān duō gè línguó de qiángliè qiǎnzé yǔ jiānjué dǐzhì.", "en": "The country's attempt to unilaterally alter trade rules met with intense condemnation and firm boycott from the international community and neighboring nations.", "es": "El intento de aquel país de modificar unilateralmente las reglas comerciales desató la enérgica condena y el firme boicot de la comunidad internacional."}], "collocations": [{"hanzi": "强烈要求", "en": "strongly demand"}, {"hanzi": "强烈反对", "en": "vehemently oppose"}, {"hanzi": "强烈对比", "en": "sharp contrast"}, {"hanzi": "强烈的阳光", "en": "intense sunlight"}, {"hanzi": "强烈的愿望", "en": "strong desire / burning wish"}, {"hanzi": "强烈震撼", "en": "deep / intense shock"}], "idioms": [{"hanzi": "烈火干柴", "pinyin": "liè huǒ gān chái", "meaning_en": "dry firewood near blazing fire; intense passion ready to erupt"}, {"hanzi": "轰轰烈烈", "pinyin": "hōng hōng liè liè", "meaning_en": "grand and vigorous; stirring and fiery"}, {"hanzi": "自强不息", "pinyin": "zì qiáng bù xī", "meaning_en": "constantly strive to improve oneself without cessation"}, {"hanzi": "旗帜鲜明", "pinyin": "qí zhì xiān míng", "meaning_en": "show a clear-cut and distinctive stance"}], "character_decomposition": [{"character": "强", "pinyin": "qiáng", "meaning_en": "strong; powerful; robust", "meaning_es": "fuerte; poderoso; robusto", "radical": "弓", "radical_meaning_en": "bow", "meaning_component": "弓 (bow drawn under immense tension)", "sound_component": "虽 (insect / vigor)", "stroke_count": "12", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where a tense hunting bow (弓) conveys resilience, power, and forceful elasticity.", "visual_mnemonic_story_en": "An arched hunting bow (弓) stretched to maximum tension ready to release immense striking force.", "visual_mnemonic_story_es": "Un arco tensado al máximo (弓) cargado de energía elástica para disparar con potencia descomunal.", "tone_mnemonic_anchor": "35", "cangjie": "NII", "traditional": "強"}, {"character": "烈", "pinyin": "liè", "meaning_en": "fiery; fierce; intense; ardent", "meaning_es": "ardiente; fiero; intenso; vehemente", "radical": "灬", "radical_meaning_en": "fire (four dots)", "meaning_component": "灬 (blazing fire heat)", "sound_component": "列 (liè, line / array / phonetic)", "stroke_count": "10", "composition_type": "上下结构", "etymology_and_mnemonic": "Phono-semantic compound where blazing fire dots 灬 combine with phonetic 列 to convey overwhelming searing energy.", "visual_mnemonic_story_en": "A blazing roaring fire (灬) burning with such fury that its heat waves knock spectators back.", "visual_mnemonic_story_es": "Un fuego abrasador (灬) que arde con tal furia que expande olas de calor sofocante.", "tone_mnemonic_anchor": "51", "cangjie": "MNF", "traditional": "烈"}], "extended_reading_passages": [{"id": "#1", "hanzi": "走进故乡的老屋，一股强烈的熟悉感瞬间涌上心头。斑驳的木桌、墙角的老钟，都在午后强烈的阳光中投下修长的影子，无声唤醒了沉睡在心底童年的纯真欢愉与深切眷恋。", "pinyin": "Zǒujìn gùxiāng de lǎowū, yì gǔ qiángliè de shúxīgǎn shùnjiān yǒng shàng xīntóu. Bānbó de mùzhuō, qiángjiǎo de lǎozhōng, dōu zài wǔhòu qiángliè de yángguāng zhōng tóuxià xiūcháng de yǐngzi, wúshēng huànxǐng le chénsùi zài xīndǐ tóngnián de chúnzhēn huānyú yǔ shēnqiè juànliàn.", "en": "Stepping into the old house, an intensely familiar feeling surged into my heart. The weathered table and grandfather clock cast long shadows in the intense afternoon sunlight, silently awakening childhood joys and deep affection.", "es": "Al entrar a la casa vieja, una intensa familiaridad inundó mi alma. La mesa descolorida y el reloj proyectaban largas sombras bajo el sol ardiente de la siesta, despertando los tiernos cariños de la niñez."}, {"id": "#2", "hanzi": "全球气候变暖引发的极端天气事件呈现出频次增高与强度剧增的强烈态势。从超级干旱到破坏性飓风，气候危机的加剧促使国际社会形成强烈共识，必须加速落实碳减排目标，共同维护地球生态安全。", "pinyin": "Quánqiú qìhòu biànnuǎn yǐnfā de jíduān tiānqì shìjiàn chéngxiàn chū píncì zēnggāo yǔ qiángdù jùzēng de qiángliè tàishì. Cóng chāojí gānhàn dào pòhuàixìng jùfēng, qìhòu wēijī de jiājù cùshǐ guójì shèhuì xíngchéng qiángliè gòngshí, bìxū jiāsù luòshí tànjiǎnpái mùbiāo, gòngtóng wéihù dìqiú shēngtài ānquán.", "en": "Extreme weather events triggered by global warming show a strong trend of increased frequency and severity. From mega-droughts to hurricanes, the deepening crisis impels a strong international consensus to cut emissions.", "es": "El calentamiento global intensifica de forma extrema los temporales. De severas sequías a huracanes devastadores, la crisis climática exige un consenso firme internacional para acelerar la reducción de carbono."}]}, {"meanings_summary": {"en": "night; evening; darkness; nocturnal", "es": "noche; anochecer; oscuridad; nocturno"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A crescent moon (夕) rising above human roofs marks the onset of the quiet night (夜).", "composite_memory_hook_es": "Una luna creciente (夕) que asoma sobre los tejados inaugura la quietud de la noche (夜).", "cultural_and_cognitive_roots": "In classical Chinese poetic tradition, '夜' is the sacred realm of introspective nostalgia, longing for absent loved ones, and philosophical communion with cosmic infinity.", "tone_sandhi_and_pitch_modulation": "Pronounced in the 4th tone with a decisive dropping pitch: 'yè' (51). Ensure firm glottal stop and do not draw out unnecessarily."}, "semantic_boundary_contrasts": {"core_nuance": "夜 refers to the temporal span from dusk to dawn, characterized by darkness and restful domestic quiet.", "contrasts": [{"id": "1", "compared_word": "夜 vs. 晚", "pinyin": "wǎn", "analysis": "夜 strictly denotes the period of darkness and night (e.g. 半夜, 黑夜), whereas 晚 can mean evening (晚上) or tardiness/delay (来晚了, 迟到晚了)."}, {"id": "2", "compared_word": "夜 vs. 暮", "pinyin": "mù", "analysis": "夜 is the entire nocturnal span, while 暮 refers specifically to the transitional dusk hour of twilight when the sun sinks (e.g. 暮色, 暮年)."}, {"id": "3", "compared_word": "夜 vs. 昏", "pinyin": "hūn", "analysis": "夜 refers to nighttime, whereas 昏 emphasizes dusk, dimness, or loss of clarity and consciousness (e.g. 黄昏, 昏迷)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "夕", "pinyin": "xī", "meaning_en": "evening; sunset", "distinction_note": "The standalone radical of 夜 without upper and lower limbs"}, {"character": "死", "pinyin": "sǐ", "meaning_en": "die; death", "distinction_note": "Has 歹 (bad/bone) on left with 匕 on right"}, {"character": "度", "pinyin": "dù", "meaning_en": "degree; spend time", "distinction_note": "Has 广 and 廿 on top with 又 below"}, {"character": "亦", "pinyin": "yì", "meaning_en": "also; too", "distinction_note": "Has upper lid and lower strokes without the middle 夕"}], "etymological_cognates": [{"character": "夜晚", "pinyin": "yè wǎn", "gloss_en": "night; evening"}, {"character": "夜光", "pinyin": "yè guāng", "gloss_en": "nocturnal glow; luminous"}, {"character": "日日夜夜", "pinyin": "rìrì-yèyè", "gloss_en": "day and night; continuously"}, {"character": "宵夜", "pinyin": "xiāo yè", "gloss_en": "late night snack"}]}, "id": "19", "hanzi": "夜", "pinyin": "yè", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the period of darkness between sunset and sunrise; night", "definition_es": "noche; periodo de oscuridad entre el ocaso y el alba", "example_phrase": "漆黑的夜 (pitch-black night)"}, {"sense_number": "2", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "at night; during the evening hours", "definition_es": "de noche; por la noche", "example_phrase": "夜行 (travel by night)"}], "example_sentences": [{"id": "#1", "hanzi": "乡村的冬夜格外寂静，只有窗外寒风吹打树枝的沙沙声，和屋里炉火偶尔噼啪作响的温热。", "pinyin": "Xiāngcūn de dōngyè géwài jìjìng, zhǐyǒu chuāngwài hánfēng chuīdǎ shùzhī de shāshā shēng, hé wūlǐ lúhuǒ ǒu'ěr pīpā zuòxiǎng de wēnrè.", "en": "Winter nights in the countryside are exceptionally tranquil, broken only by chilly winds rustling branches outside and the cozy crackle of the hearth fire indoors.", "es": "Las noches de invierno en el campo son de un sosiego admirable, rotas solo por el viento en las ramas y el chisporroteo cálido del hogar."}, {"id": "#2", "hanzi": "为了确保新一代运载火箭按期发射，科研攻关团队连夜奋战在戈壁深处的发射控制大厅里。", "pinyin": "Wèile quèbǎo xīn yídài yùnzài huǒjiàn ànqī fāshè, kēyán gōngguān tuánduì liányè fènzhàn zài gēbì shēnchù de fāshè kòngzhì dàtīng lǐ.", "en": "To ensure the scheduled launch of the new generation carrier rocket, the research team fought throughout the night in the launch hall deep in the Gobi desert.", "es": "Para asegurar el lanzamiento puntual del cohete espacial, el equipo científico trabajó toda la noche sin descanso en el centro de control del desierto."}], "collocations": [{"hanzi": "深夜", "en": "late at night; deep in the night"}, {"hanzi": "半夜", "en": "midnight; middle of the night"}, {"hanzi": "夜市", "en": "night market"}, {"hanzi": "连夜", "en": "that very night; throughout the night"}, {"hanzi": "整夜", "en": "all night long; whole night"}, {"hanzi": "熬夜", "en": "stay up late; pull an all-nighter"}], "idioms": [{"hanzi": "夜以继日", "pinyin": "yè yǐ jì rì", "meaning_en": "day and night without stopping; work around the clock"}, {"hanzi": "日落西山", "pinyin": "rì luò xī shān", "meaning_en": "the sun sets behind western hills; declining rapidly"}, {"hanzi": "秉烛夜游", "pinyin": "bǐng zhú yè yóu", "meaning_en": "hold candles to stroll at night; make merry while life lasts"}, {"hanzi": "万家灯火", "pinyin": "wàn jiā dēng huǒ", "meaning_en": "a myriad twinkling lights of homes at night"}], "character_decomposition": [{"character": "夜", "pinyin": "yè", "meaning_en": "night; evening; dark", "meaning_es": "noche; anochecer; nocturno", "radical": "夕", "radical_meaning_en": "evening / dusk", "meaning_component": "夕 (crescent moon in twilight)", "sound_component": "亦 (yì, person standing under twilight)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "Ancient compound depicting a person walking under the newly risen crescent moon (夕), entering the dark hours of night.", "visual_mnemonic_story_en": "A person walking homeward beneath a cool crescent evening moon (夕) as darkness descends across the earth.", "visual_mnemonic_story_es": "Una persona que regresa a casa bajo la luna creciente del crepúsculo (夕) cuando la noche envuelve la tierra.", "tone_mnemonic_anchor": "51", "cangjie": "YONK", "traditional": "夜"}], "extended_reading_passages": [{"id": "#1", "hanzi": "故乡山村的夜，澄澈得如同洗过的明镜。没有都市霓虹的喧扰，漫天繁星在墨蓝的天幕上悄然闪烁。微风吹过竹林，沙沙作响，将游子漂泊的心温柔地安放在这静谧的夜色之中。", "pinyin": "Gùxiāng shāncūn de yè, chéngchè de rútóng xǐ guò de míngjìng. Méiyǒu dūshì níhóng de xuānrǎo, màntiān fánxīng zài mòlán de tiānmù shàng qiǎorán shǎnshuò. Wēifēng chuīguò zhúlín, shāshā zuòxiǎng, jiāng yóuzǐ piāobó de xīn wēnróu de ānfàng zài zhè jìngmì de yèsè zhīzhōng.", "en": "The night in my mountain hometown is as clear as a polished mirror. Free from city neons, countless stars glitter quietly on ink-blue heavens. Breeze murmuring through bamboos gently lulls a wanderer's restless heart into stillness.", "es": "La noche en el pueblo serrano es tan pura como un espejo bruñido. Lejos del neón urbano, infinitas estrellas titilan sobre el cielo azul marino. La brisa en el bambú serena con ternura el corazón inquieto del viajero."}, {"id": "#2", "hanzi": "随着夜间文旅与消费场景的不断拓展，“夜经济”已成为激发中国城市活力的重要引擎。从深夜书店到全景夜游，多元业态不仅丰富了市民的精神文化生活，更显著带动了第三产业的复苏与升级。", "pinyin": "Suí zhe yèjiān wénlǚ yǔ xiāofèi chǎngjǐng de búduàn tuòzhǎn, \"yè jīngjì\" yǐ chéngwéi jīfā Zhōngguó chéngshì huólì de zhòngyào yǐnqíng. Cóng shēnyè shūdiàn dào quánjǐng yèyóu, duōyuán yètài bùjǐn fēngfù le shìmín de jīngshén wénhuà shēnghuó, gèng xiǎnzhù dàidòng le dìsān chǎnyè de fùsū yǔ shēngjí.", "en": "With nighttime tourism and commerce expanding, the night economy has become a prime engine energizing Chinese cities. From late-night bookstores to night tours, diverse formats enrich cultural life and boost tertiary sector revitalization.", "es": "La expansión del ocio nocturno convierte la economía de la noche en motor urbano. De librerías nocturnas a rutas iluminadas, estas propuestas enriquecen la vida ciudadana y dinamizan con fuerza el sector servicios."}]}, {"meanings_summary": {"en": "to lock; lock; padlock; chain; to lock up; to knit (brows)", "es": "cerrar con llave; candado; cerradura; encadenar; fruncir (el ceño)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A metal bolt (钅) fitted with intricate internal tumblers (琐) forms a secure lock (锁).", "composite_memory_hook_es": "Una pieza metálica (钅) con diminutos engranajes interiores (琐) constituye una cerradura segura (锁).", "cultural_and_cognitive_roots": "In ancient China, bronze fish locks ('鱼锁') symbolized vigilance because fish sleep with their eyes open; locking up signified not mere suspicion, but the moral boundary guarding home harmony.", "tone_sandhi_and_pitch_modulation": "Pronounced in the 3rd tone with a dipping and rising contour: 'suǒ' (214). When followed by another 3rd tone (e.g. 锁好), 'suǒ' undergoes tone sandhi to 2nd tone: 'suó hǎo' (35-214)."}, "semantic_boundary_contrasts": {"core_nuance": "锁 refers to fastening or securing with a mechanical key/bolt, or shutting tight metaphorically.", "contrasts": [{"id": "1", "compared_word": "锁 vs. 关", "pinyin": "guān", "analysis": "关 means closing or shutting a door/window without a key mechanism (e.g. 关门), whereas 锁 explicitly requires engaging a bolt or padlock (e.g. 把门锁上)."}, {"id": "2", "compared_word": "锁 vs. 封", "pinyin": "fēng", "analysis": "锁 restricts access via a key mechanism while preserving the barrier, whereas 封 means sealing, gluing, or stamping shut completely (e.g. 封信, 封锁)."}, {"id": "3", "compared_word": "锁 vs. 扣", "pinyin": "kòu", "analysis": "锁 secures with tumblers or padlocks, while 扣 means fastening buttons, buckles, or clasping with rings (e.g. 扣纽扣, 扣紧安全带)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "琐", "pinyin": "suǒ", "meaning_en": "trifling; trivial", "distinction_note": "Has 王 (jade) on the left instead of 钅 (metal)"}, {"character": "销", "pinyin": "xiāo", "meaning_en": "melt; cancel; sell", "distinction_note": "Has 肖 on the right of 钅 instead of 琐"}, {"character": "铝", "pinyin": "lǚ", "meaning_en": "aluminum", "distinction_note": "Has 吕 on the right of 钅 instead of 琐"}, {"character": "错", "pinyin": "cuò", "meaning_en": "mistake; wrong; cross", "distinction_note": "Has 昔 on the right of 钅 instead of 琐"}], "etymological_cognates": [{"character": "钥匙", "pinyin": "yào shi", "gloss_en": "key"}, {"character": "锁链", "pinyin": "suǒ liàn", "gloss_en": "chain; iron links"}, {"character": "枷锁", "pinyin": "jiā suǒ", "gloss_en": "shackles; fetters; yoke"}, {"character": "锁骨", "pinyin": "suǒ gǔ", "gloss_en": "clavicle; collarbone"}]}, "id": "20", "hanzi": "锁", "pinyin": "suǒ", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to fasten or secure with a lock or latch", "definition_es": "cerrar con llave; echar el cerrojo", "example_phrase": "把门锁好 (lock the door properly)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a mechanical or electronic fastening device opened by a key or code", "definition_es": "cerradura; cerrojo; candado", "example_phrase": "一把铜锁 (a bronze lock)"}, {"sense_number": "3", "part_of_speech": "Verb", "register": "Literary", "definition_en": "to knit or contract tightly (as in brows/eyebrows in deep worry)", "definition_es": "fruncir (el ceño por preocupación)", "example_phrase": "眉头紧锁 (brows deeply furrowed)"}], "example_sentences": [{"id": "#1", "hanzi": "临出门前，母亲总要反复拉动门把手确认大门已经锁好，才放心地迈步下楼。", "pinyin": "Lín chūmén qián, mǔqīn zǒng yào fǎnfù lādòng ménbǎshou quèrèn dàmén yǐjīng suǒ hǎo, cái fàngxīn de màibù xiàlóu.", "en": "Just before stepping out, mother always rattles the door handle repeatedly to ensure the front door is securely locked before walking downstairs.", "es": "Antes de salir, mi madre siempre tira varias veces del picaporte para cerciorarse de que la puerta quedó bien cerrada antes de bajar."}, {"id": "#2", "hanzi": "该数据中心部署了金融级智能数字密码锁与多模态生物识别门禁系统，全面防范未经授权的物理入侵。", "pinyin": "Gāi shùjù zhōngxīn bùshǔ le jīnróng jí zhìnéng shùzì mìmǎsuǒ yǔ duōmótài shēngwù shíbié ménjìn xìtǒng, quánmiàn fángfàn wèijīng shòuquán de wùlǐ rùqīn.", "en": "The data center deployed finance-grade smart digital combination locks and multimodal biometric access controls to guard against unauthorized entry.", "es": "El centro de datos implementó cerraduras digitales de seguridad bancaria y control biométrico de accesos para blindarse frente a intrusiones."}], "collocations": [{"hanzi": "一把锁", "en": "a lock; a padlock"}, {"hanzi": "开锁", "en": "unlock; pick a lock"}, {"hanzi": "锁门", "en": "lock the door"}, {"hanzi": "上锁", "en": "put a lock on; lock up"}, {"hanzi": "锁链", "en": "chain; iron fetters"}, {"hanzi": "紧锁眉头", "en": "furrow one's brows deeply"}], "idioms": [{"hanzi": "封关锁国", "pinyin": "fēng guān suǒ guó", "meaning_en": "close borders and lock up the country; strict isolationism"}, {"hanzi": "神魂颠倒", "pinyin": "shén hún diān dǎo", "meaning_en": "infatuated to distraction; soul turned topsy-turvy"}, {"hanzi": "闭关自守", "pinyin": "bì guān zì shǒu", "meaning_en": "close passes and defend oneself; adopt a closed-door stance"}, {"hanzi": "严阵以待", "pinyin": "yán zhèn yǐ dài", "meaning_en": "stand in tight array waiting for the enemy; fully prepared"}], "character_decomposition": [{"character": "锁", "pinyin": "suǒ", "meaning_en": "lock; latch; chain; fasten", "meaning_es": "cerradura; candado; cerrar con llave", "radical": "钅", "radical_meaning_en": "metal / gold", "meaning_component": "钅 (metal hardware)", "sound_component": "琐 (suǒ, intricate link / small pieces)", "stroke_count": "12", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where metal radical 钅 combines with phonetic 琐 (intricate links) to designate a secure locking mechanism.", "visual_mnemonic_story_en": "An intricate metal device (钅) forged with precise interlocking tumblers (琐) to safeguard the house.", "visual_mnemonic_story_es": "Un mecanismo metálico (钅) forjado con precisos engranajes (琐) para custodiar los bienes del hogar.", "tone_mnemonic_anchor": "214", "cangjie": "CFBO", "traditional": "鎖"}], "extended_reading_passages": [{"id": "#1", "hanzi": "祖宅大门上的那把老铜锁早已生出了斑驳的绿锈，但在钥匙插入旋转的清脆声响中，尘封的童年记忆仿佛瞬间被打开。推开沉重的木门，天井里的青苔与老树依然守候在静谧的光阴里。", "pinyin": "Zǔzhái dàmén shàng de nà bǎ lǎo tóngsuǒ zǎoyǐ shēngchū le bānbó de lǜxiù, dàn zài yàoshi chārù xuánzhuǎn de qīngcuì shēngxiǎng zhōng, chénfēng de tóngnián jìyì fǎngrú shùnjiān bèi dǎkāi. Tuīkāi chénzhòng de mùmén, tiānjǐng lǐ de qīngtái yǔ lǎoshù yīrán shǒuhòu zài jìngmì de guāngyīn lǐ.", "en": "The old bronze padlock on the ancestral gate had grown mottled green patina, yet at the crisp click of the turning key, sealed childhood memories seemed to unlock instantly. Pushing open heavy doors, moss and old trees waited in tranquility.", "es": "El viejo cerrojo de bronce de la casa solariega mostraba pátina verdosa, pero al girar la llave con un chasquido limpio, los recuerdos sellados se abrieron de par en par. El musgo y los árboles aguardaban aún en silencio."}, {"id": "#2", "hanzi": "随着移动物联网与生物识别技术的普及，传统机械锁正迅速向智能门锁系统迭代。通过集成活体指纹、3D人脸识别以及远程权限加密授权，现代安防系统在极大提升出入便捷性的同时，筑牢了数字家庭的安全防线。", "pinyin": "Suí zhe yídòng wùliánwǎng yǔ shēngwù shíbié jìshù de pǔjí, chuántǒng jīxièsuǒ zhèng xùnsù xiàng zhìnéng ménsuǒ xìtǒng diédài. Tōngguò jíchéng huótǐ zhǐwén, sān-D rénliǎn shíbié yǐjí yuǎnchéng quánxiàn jiāmì shòuquán, xiàndài ānfáng xìtǒng zài jídà tíshēng chūrù biànjièxìng de tóngshí, zhùláo le shùzì jiātíng de ānquán fángxiàn.", "en": "Driven by IoT and biometrics, mechanical locks are iterating into smart lock systems. Integrating live fingerprint, 3D facial recognition, and encrypted authorization, modern security elevates convenience while fortifying digital home safety.", "es": "Con el internet de las cosas y la biometría, las cerraduras mecánicas dan paso a cerraduras inteligentes. El reconocimiento facial y la huella digital dactilar multiplican la comodidad blindando la seguridad del hogar digital."}]}, {"meanings_summary": {"en": "just before; about to; on the verge of; to overlook; to face; to arrive", "es": "justo antes de; a punto de; frente a; asomarse a; llegar; descender"}, "mnemonics_and_roots": {"composite_memory_hook_en": "An observer leaning over (临) to inspect everything carefully right on the verge of departure.", "composite_memory_hook_es": "Inclinarse a mirar (临) con atención todo lo que sucede justo antes del momento de actuar.", "cultural_and_cognitive_roots": "In ancient governance, '临' signified an imperial or compassionate gaze descending onto subjects; in family life, it captured tender parental anxiety guarding a child's parting moment ('临行密密缝').", "tone_sandhi_and_pitch_modulation": "Pronounced in the 2nd tone with a smooth rising pitch: 'lín' (35). Articulate the nasal 'n' ending cleanly without dropping into 3rd tone."}, "semantic_boundary_contrasts": {"core_nuance": "临 indicates immediate temporal proximity right before an event occurs or physical spatial exposure facing an open vista.", "contrasts": [{"id": "1", "compared_word": "临 vs. 快", "pinyin": "kuài", "analysis": "临 is a preposition meaning 'just before' attached to a verb/noun (e.g. 临睡前, 临别), whereas 快 is an adverb/predicate meaning 'soon' or 'rapidly' (e.g. 快走, 火车快开了)."}, {"id": "2", "compared_word": "临 vs. 将", "pinyin": "jiāng", "analysis": "临 marks the immediate threshold moments before an action, while 将 indicates a broader upcoming future tense (e.g. 将要发生)."}, {"id": "3", "compared_word": "临 vs. 朝", "pinyin": "cháo", "analysis": "临 means facing with a direct view or overlooking (e.g. 临街, 临水), while 朝 indicates directional orientation toward any compass point (e.g. 朝南, 朝东)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "师", "pinyin": "shī", "meaning_en": "teacher; master", "distinction_note": "Has 巾 on the right side instead of the vertical strokes of 临"}, {"character": "帅", "pinyin": "shuài", "meaning_en": "handsome; commander", "distinction_note": "Has 巾 on the right with a top dot stroke"}, {"character": "川", "pinyin": "chuān", "meaning_en": "river; stream", "distinction_note": "Consists solely of three vertical strokes"}, {"character": "卧", "pinyin": "wò", "meaning_en": "lie down; recline", "distinction_note": "Has 臣 on the left with 卜 on the right"}], "etymological_cognates": [{"character": "临时", "pinyin": "lín shí", "gloss_en": "temporary; provisional"}, {"character": "临近", "pinyin": "lín jìn", "gloss_en": "approach; draw near"}, {"character": "光临", "pinyin": "guāng lín", "gloss_en": "honor with presence (polite arrival)"}, {"character": "面临", "pinyin": "miàn lín", "gloss_en": "face; be confronted with"}]}, "id": "21", "hanzi": "临", "pinyin": "lín", "level": "HSK 5", "part_of_speech": "Preposition", "senses": [{"sense_number": "1", "part_of_speech": "Preposition", "register": "Standard", "definition_en": "just before; on the point of (an action or departure)", "definition_es": "justo antes de; al borde de (una partida o acción)", "example_phrase": "临走前 (just before leaving)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to overlook; to face; to border on (a river, street, sea)", "definition_es": "dar a; asomarse a; estar frente a", "example_phrase": "临街的窗户 (window overlooking the street)"}, {"sense_number": "3", "part_of_speech": "Verb", "register": "Literary", "definition_en": "to arrive; to descend upon (used in polite or formal contexts)", "definition_es": "descender; llegar; presentarse", "example_phrase": "光临 (honor with one's presence)"}], "example_sentences": [{"id": "#1", "hanzi": "临上长途汽车前，母亲悄悄往儿子的背包里塞了两罐亲手炒制的牛肉辣酱和一沓厚厚的零钱。", "pinyin": "Lín shàng chángtú qìchē qián, mǔqīn qiāoqiāo wǎng érzi de bèibāo lǐ sāi le liǎng guàn qīnshǒu chǎozhì de niúròu làjiàng hé yì dá hòuhòu de língqián.", "en": "Just before boarding the long-distance coach, mother quietly slipped two jars of handmade spicy beef sauce and a thick wad of pocket money into her son's backpack.", "es": "Justo antes de subir al autobús de larga distancia, mi madre metió a escondidas dos frascos de pasta picante de carne casera y un fajo de dinero en mi mochila."}, {"id": "#2", "hanzi": "该高级商务酒店坐落于黄浦江畔，每间行政套房均拥有极佳的临江全景视野，为高端旅客提供卓越入住体验。", "pinyin": "Gāi gāojí shāngwù jiǔdiàn zuòluò yú Huángpǔ Jiāng pàn, měi jiān xíngzhèng tàofáng jūn yōngyǒu jí jiā de línjiāng quánjǐng shìyě, wèi gāoduān lǚkè tígōng zhuóyuè rùzhù tǐyàn.", "en": "The luxury business hotel sits by the Huangpu River; every executive suite commands an exceptional panoramic river view, offering premium guests an outstanding stay.", "es": "Este hotel ejecutivo se erige junto al río Huangpu; sus suites poseen magníficas vistas panorámicas frente al agua, brindando una estancia insuperable a viajeros distinguidos."}], "collocations": [{"hanzi": "临走", "en": "just before leaving"}, {"hanzi": "临时", "en": "temporary; provisional"}, {"hanzi": "面临", "en": "be faced with; confront"}, {"hanzi": "降临", "en": "descend; arrive; befall"}, {"hanzi": "临近", "en": "approaching; close at hand"}, {"hanzi": "临危不乱", "en": "calm and undaunted in the face of peril"}], "idioms": [{"hanzi": "身临其境", "pinyin": "shēn lín qí jìng", "meaning_en": "be personally on the scene; experience firsthand"}, {"hanzi": "临渴掘井", "pinyin": "lín kě jué jǐng", "meaning_en": "dig a well only when thirsty; make preparations at the last minute"}, {"hanzi": "临危不乱", "pinyin": "lín wēi bú luàn", "meaning_en": "remain undaunted and calm in the face of crisis"}, {"hanzi": "双喜临门", "pinyin": "shuāng xǐ lín mén", "meaning_en": "two blessings arrive at the door simultaneously"}], "character_decomposition": [{"character": "临", "pinyin": "lín", "meaning_en": "just before; overlook; descend", "meaning_es": "justo antes de; dar a; llegar", "radical": "丨", "radical_meaning_en": "vertical stroke / line", "meaning_component": "臣 (archaic downward-gazing eye)", "sound_component": "品/人 (people below)", "stroke_count": "9", "composition_type": "左右结构", "etymology_and_mnemonic": "Depicts an eye peering down from above to inspect people below, evolving into facing or imminent arrival.", "visual_mnemonic_story_en": "A compassionate overseer bending down to inspect people below just as critical action begins.", "visual_mnemonic_story_es": "Una mirada atenta que se inclina hacia abajo para supervisar el lugar justo antes de partir.", "tone_mnemonic_anchor": "35", "cangjie": "LIOR", "traditional": "臨"}], "extended_reading_passages": [{"id": "#1", "hanzi": "孟郊诗云：“慈母手中线，游子身上衣。临行密密缝，意恐迟迟归。”每当读到这句千古名句，眼前便会浮现出母亲在昏黄油灯下飞针走线的背影，那份母爱穿越千年依然滚烫如初。", "pinyin": "Mèng Jiāo shī yún: \"Címǔ shǒuzhōng xiàn, yóuzǐ shēnshàng yī. Línxíng mìmì féng, yì kǒng chíchí guī.\" Měidāng dú dào zhè jù qiāngǔ míngjù, yǎnqián biàn huì fúxiàn chū mǔqīn zài hūnhuáng yóudēng xià fēizhēn-zǒuxiàn de bèiyǐng, nà fèn mǔ'ài chuānyuè qiānnián yīrán gǔntàng rúchū.", "en": "Meng Jiao wrote: \"Threads in loving mother's hands become the coat on the departing child. Stitching closely just before he goes, fearing his return will be delayed.\" This filial imagery remains intensely poignant through millennia.", "es": "Meng Jiao escribió: \"Hilos en manos de la madre tejen la túnica del hijo viajero. Puntadas apretadas antes de partir, temiendo su tardío retorno\". La estampa maternal conmueve hoy con idéntica hondura milenaria."}, {"id": "#2", "hanzi": "面对全球产业链重塑与市场不确定性剧增的严峻挑战，企业决策者必须具备临危不乱的战略定力。唯有在风浪来临之前未雨绸缪，建立多元化的供应链缓冲体系，方能在激烈的国际竞争中立于不败之地。", "pinyin": "Miànduì quánqiú chǎnyèliàn chóngshù yǔ shìchǎng bùquèdìngxìng jùzēng de yánjùn tiǎozhàn, qǐyè juécèzhě bìxū jùbèi línwēi-búlùan de zhànlüè dìnglì. Wéiyǒu zài fēnglàng láilín zhīqián wèiyǔchóumóu, jiànlì duōyuánhuà de gōngyìngliàn huǎnchōng tǐxì, fāng néng zài jīliè de guójì jìngzhēng zhōng lìyú-búbàizhīdì.", "en": "Facing supply chain restructuring and market uncertainty, business leaders must demonstrate strategic calmness when facing crises. Preparing buffers before storms arrive ensures lasting resilience in global competition.", "es": "Ante la recomposición de cadenas industriales y la incertidumbre, los directivos empresariales deben mantener serenidad estratégica frente a las crisis, reforzando la logística para afianzar su liderazgo mundial."}]}, {"meanings_summary": {"en": "quietly; secretly; stealthily; softly without making noise", "es": "silenciosamente; a escondidas; furtivamente; en voz baja; sigilosamente"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Keeping one's heart (忄) gentle and discreet like a tiny shadow (肖) allows one to move quietly (悄悄).", "composite_memory_hook_es": "Mantener el corazón (忄) en calma y discreción como una sombra sutil (肖) permite actuar sigilosamente (悄悄).", "cultural_and_cognitive_roots": "In Chinese domestic culture, '悄悄' is synonymous with maternal tender care: sneaking in to pull up fallen quilts, slipping money into coat pockets, or keeping rooms quiet for studying children.", "tone_sandhi_and_pitch_modulation": "Reduplicated colloquial adverb pronounced with twin high level tones: 'qiāo qiāo' (55-55). When used in literary idiom '悄然', pronounced in 3rd tone: 'qiǎorán' (214-35)."}, "semantic_boundary_contrasts": {"core_nuance": "悄悄 focuses on deliberate suppression of sound or movement to avoid drawing attention.", "contrasts": [{"id": "1", "compared_word": "悄悄 vs. 偷偷", "pinyin": "tōutōu", "analysis": "悄悄 emphasizes softness and absence of sound with loving or discreet intention, whereas 偷偷 implies illicit concealment, fear of discovery, or sneaky wrongdoing."}, {"id": "2", "compared_word": "悄悄 vs. 暗暗", "pinyin": "àn'àn", "analysis": "悄悄 describes physical behavior carried out without making sound, while 暗暗 describes private psychological thoughts or hidden inner emotions (e.g. 暗暗下定决心)."}, {"id": "3", "compared_word": "悄悄 vs. 轻轻", "pinyin": "qīngqīng", "analysis": "悄悄 means without noise or awareness of others, whereas 轻轻 emphasizes low physical pressure or gentle muscular touch (e.g. 轻轻拍了拍他的肩膀)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "消", "pinyin": "xiāo", "meaning_en": "vanish; eliminate", "distinction_note": "Has 氵 (water) on the left instead of 忄 (heart)"}, {"character": "梢", "pinyin": "shāo", "meaning_en": "tip of branch", "distinction_note": "Has 木 (wood) on the left instead of 忄"}, {"character": "稍", "pinyin": "shāo", "meaning_en": "slightly; a little", "distinction_note": "Has 禾 (grain) on the left instead of 忄"}, {"character": "硝", "pinyin": "xiāo", "meaning_en": "niter; saltpeter", "distinction_note": "Has 石 (stone) on the left instead of 忄"}], "etymological_cognates": [{"character": "悄然", "pinyin": "qiǎo rán", "gloss_en": "quietly; sorrowfully (literary)"}, {"character": "悄声", "pinyin": "qiāo shēng", "gloss_en": "in a hushed voice; whisper"}, {"character": "静悄悄", "pinyin": "jìng qiāoqiāo", "gloss_en": "quiet and peaceful"}, {"character": "肖像", "pinyin": "xiào xiàng", "gloss_en": "portrait (sharing phonetic root 肖)"}]}, "id": "22", "hanzi": "悄悄", "pinyin": "qiāo qiāo", "level": "HSK 5", "part_of_speech": "Adverb", "senses": [{"sense_number": "1", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "softly without producing noise or attracting attention", "definition_es": "silenciosamente; sin hacer ruido", "example_phrase": "悄悄走出去 (walk out quietly)"}, {"sense_number": "2", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "secretly; surreptitiously behind someone's back", "definition_es": "a escondidas; en secreto", "example_phrase": "悄悄塞给他 (secretly slipped it to him)"}], "example_sentences": [{"id": "#1", "hanzi": "清晨全家人还在熟睡，母亲便悄悄起床来到厨房，轻手轻脚地为我们煮好了一锅香甜的红枣粥。", "pinyin": "Qīngchén quán jiā rén hái zài shúshuì, mǔqīn biàn qiāoqiāo qǐchuáng lái dào chúfáng, qīngshǒu-qīngjiǎo de wèi wǒmen zhǔ hǎo le yì guō xiāngtián de hóngzǎozhōu.", "en": "At dawn while the family was sound asleep, mother quietly got out of bed and came to the kitchen, softly cooking a pot of sweet red date porridge.", "es": "De madrugada, con la familia dormida aún, mi madre se levantó en silencio y marchó de puntillas a la cocina a preparar gachas de dátiles."}, {"id": "#2", "hanzi": "为了给身处重症病房的同事减轻经济负担，全体部门同事悄悄组织了一次爱心匿名善款捐赠活动。", "pinyin": "Wèile gěi shēnchǔ zhòngzhèng bìngfáng de tóngshì jiǎnqīng jīngjì fùdān, quántǐ bùmén tóngshì qiāoqiāo zǔzhī le yí cì àixīn nìmíng shànkuǎn juānzèng huódòng.", "en": "To relieve financial burdens on a colleague in the ICU, department colleagues secretly organized an anonymous charitable donation campaign.", "es": "Para aliviar a un compañero ingresado en cuidados intensivos, los colegas de su sección organizaron en secreto una colecta solidaria anónima."}], "collocations": [{"hanzi": "悄悄话", "en": "whispered secret; intimate whisper"}, {"hanzi": "悄悄离开", "en": "leave quietly; slip away unnoticed"}, {"hanzi": "悄悄走近", "en": "approach stealthily / softly"}, {"hanzi": "悄悄塞给", "en": "secretly slip to someone"}, {"hanzi": "静悄悄", "en": "quiet and silent (reduplicated adj)"}, {"hanzi": "悄悄发生", "en": "happen silently / subtly"}], "idioms": [{"hanzi": "悄然无声", "pinyin": "qiǎo rán wú shēng", "meaning_en": "completely quiet without a single sound"}, {"hanzi": "不动声色", "pinyin": "bú dòng shēng sè", "meaning_en": "not a word or motion; maintain calm composure"}, {"hanzi": "潜移默化", "pinyin": "qián yí mò huà", "meaning_en": "exert subtle, imperceptible influence over time"}, {"hanzi": "鸦雀无声", "pinyin": "yā què wú shēng", "meaning_en": "not even a crow or sparrow cawing; dead silence"}], "character_decomposition": [{"character": "悄", "pinyin": "qiāo", "meaning_en": "quiet; silent; sorrowful", "meaning_es": "silencioso; sigiloso; apenado", "radical": "忄", "radical_meaning_en": "heart (standing heart)", "meaning_component": "忄 (discreet interior emotion)", "sound_component": "肖 (xiāo, small / resemble)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where standing heart 忄 expresses gentle discretion and silence, guided by phonetic 肖.", "visual_mnemonic_story_en": "A heart (忄) made so tiny and careful (肖) that its footsteps make no audible sound.", "visual_mnemonic_story_es": "Un corazón (忄) que late con suma delicadeza (肖) para no turbar el silencio de la noche.", "tone_mnemonic_anchor": "55", "cangjie": "PFB", "traditional": "悄"}], "extended_reading_passages": [{"id": "#1", "hanzi": "夜深了，月光像轻纱一样铺在床前。母亲悄悄走进卧室，轻轻替熟睡的孩子掖好被角，又悄无声息地掩门离去。母爱就是这样，从不喧哗招摇，却在每一个无声的细节里倾注着生命全部的温柔。", "pinyin": "Yè shēn le, yuèguāng xiàng qīngshā yíyàng pū zài chuángqián. Mǔqīn qiāoqiāo zǒujìn wòshì, qīngqīng tì shúshuì de háizi yē hǎo bèijiǎo, yòu qiāowúshēngxī de yǎnmén líqù. Mǔ'ài jiùshì zhèyàng, cóngbù xuānhuá zhāoyáo, què zài měi yí gè wúshēng de xìjié lǐ qīngzhù zhe shēngmìng quánbù de wēnróu.", "en": "Night deepened; moonlight draped like gauze before the bed. Mother stepped quietly into the bedroom, gently tucked in the quilt for her sleeping child, and slipped out. Maternal love never boasts, yet pours all tenderness into silent details.", "es": "Avanza la noche; la luna viste el suelo de seda tenue. Madre entra en silencio a la habitación, arropa al niño dormido y marcha de puntillas. El amor materno nunca alardea: late con dulzura en cada gesto callado."}, {"id": "#2", "hanzi": "在数字化浪潮推动下，现代社会的阅读习惯正悄悄发生深刻演变。传统纸质图书的专注沉浸，逐渐与移动终端的碎片化阅读深度共存。这种阅读介质的变迁，正悄然重塑着当代公众的认知与思维模式。", "pinyin": "Zài shùzìhuà làngcháo tuīdòng xià, xiàndài shèhuì de yuèdú xíguàn zhèng qiāoqiāo fāshēng shēnkè yǎnbiàn. Chuántǒng zhǐzhì túshū de zhuānzhù chénjìn, zhújiàn yǔ yídòng zhōngduān de suìpiànhuà yuèdú shēndù gòngcún. Zhè zhǒng yuèdú jièzhì de biànqiān, zhèng qiǎorán zhòngshù zhe dāngdài gōngzhòng de rènzhī yǔ sīwéi móshì.", "en": "Propelled by digital tides, modern reading habits are quietly undergoing profound evolution. Traditional deep reading coexists with fragmented mobile screen engagement, subtly reshaping cognitive habits of the public.", "es": "Con el auge digital, los hábitos lectores evolucionan en silencio. La lectura reposada en papel convive con la consulta fragmentada en dispositivos móviles, modelando los esquemas cognitivos de las nuevas generaciones."}]}, {"meanings_summary": {"en": "to dry in the sun; to bask; to expose to sunshine; to share/showcase online", "es": "secar al sol; solear; tomar el sol; exhibir o compartir en redes sociales"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Letting the bright sun (日) shine down onto your belongings dries and warms (晒) them through and through.", "composite_memory_hook_es": "Dejar que el sol (日) ilumine los tejidos logra secar y calentar (晒) cada fibra con su brillo.", "cultural_and_cognitive_roots": "In rural China, '晒' is the centerpiece of seasonal labor—drying harvested grain, drying autumn chilies, and airing heavy cotton quilts so they smell of 'the aroma of sunshine' (阳光的味道).", "tone_sandhi_and_pitch_modulation": "Pronounced in the 4th tone with a sharp falling pitch: 'shài' (51). Distinguish from 4th tone homophones like 'shài' (筛 is 1st tone shāi)."}, "semantic_boundary_contrasts": {"core_nuance": "晒 requires the direct thermal energy of sunlight to heat, dry, or disinfect physical objects or human skin.", "contrasts": [{"id": "1", "compared_word": "晒 vs. 晾", "pinyin": "liàng", "analysis": "晒 relies on direct radiant sunlight to dry and heat, whereas 晾 emphasizes hanging items in a ventilated, shaded, or breezy space to dry without requiring sun (e.g. 晾在屋檐下)."}, {"id": "2", "compared_word": "晒 vs. 烤", "pinyin": "kǎo", "analysis": "晒 utilizes natural solar warmth, while 烤 involves artificial fire, an oven, or an electric heater (e.g. 烤面包, 烤火)."}, {"id": "3", "compared_word": "晒 vs. 烘", "pinyin": "hōng", "analysis": "晒 relies on outdoor sunshine, whereas 烘 implies using hot air or a specialized mechanical tumble dryer (e.g. 烘干机)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "洒", "pinyin": "sǎ", "meaning_en": "sprinkle; spill", "distinction_note": "Has 氵 (water) on the left instead of 日 (sun)"}, {"character": "栖", "pinyin": "qī", "meaning_en": "perch; roost", "distinction_note": "Has 木 (wood) on the left instead of 日"}, {"character": "西", "pinyin": "xī", "meaning_en": "west", "distinction_note": "Standalone phonetic component without left sun radical 日"}, {"character": "昭", "pinyin": "zhāo", "meaning_en": "bright; evident", "distinction_note": "Has 召 on the right of 日 instead of 西"}], "etymological_cognates": [{"character": "日晒", "pinyin": "rì shài", "gloss_en": "sun exposure; insolation"}, {"character": "晾晒", "pinyin": "liàng shài", "gloss_en": "dry in the sun and air"}, {"character": "晴朗", "pinyin": "qíng lǎng", "gloss_en": "sunny and bright"}, {"character": "映照", "pinyin": "yìng zhào", "gloss_en": "shine upon; reflect"}]}, "id": "23", "hanzi": "晒", "pinyin": "shài", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to expose objects (clothes, quilts, crops) to sunshine for drying or sanitizing", "definition_es": "secar o airear ropa, cereales o edredones al sol", "example_phrase": "晒被子 (dry quilts in the sun)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to bask under the sun (for warmth or tanning)", "definition_es": "tomar el sol; broncearse; asolearse", "example_phrase": "晒太阳 (bask in the sun)"}, {"sense_number": "3", "part_of_speech": "Verb", "register": "Colloquial", "definition_en": "to post, showcase, or flaunt photos and lifestyle on social media", "definition_es": "compartir fotos o presumir en redes sociales", "example_phrase": "晒朋友圈 (post on Moments)"}], "example_sentences": [{"id": "#1", "hanzi": "趁着周末晴空万里，母亲一大早就把家里的几床厚棉被抱到楼顶晒衣绳上充分晾晒。", "pinyin": "Chènzhe zhōumò qíngkōng-wànlǐ, mǔqīn yí dà zǎo jiù bǎ jiālǐ de jǐ chuáng hòu miánbèi bào dào lóudǐng shàiyīshéng shàng chōngfèn liàngshài.", "en": "Taking advantage of the cloudless weekend sky, mother took several thick cotton quilts to the rooftop clothesline early to dry under the sun.", "es": "Aprovechando el cielo despejado del fin de semana, mi madre subió de buena mañana los edredones de algodón a la azotea para airearlos al sol."}, {"id": "#2", "hanzi": "在高原地区进行户外实地科学考察时，研究队员必须涂抹防晒霜并佩戴墨镜，以防止强烈的紫外线晒伤皮肤。", "pinyin": "Zài gāoyuán dìqū jìnxíng hùwài shídì kēxué kǎochá shí, yánjiū duìyuán bìxū túmǒ fángshàishuāng bìng pèidài mòjìng, yǐ fángzhǐ qiángliè de zǐwàixiàn shàishāng pífū.", "en": "When conducting field scientific research in plateau regions, researchers must apply sunscreen and wear sunglasses to prevent intense UV rays from sunburn.", "es": "Durante las expediciones científicas en zonas de meseta, los investigadores deben aplicarse protector solar y gafas oscuras para no quemarse con la radiación ultravioleta."}], "collocations": [{"hanzi": "晒太阳", "en": "bask in the sun; sunbathe"}, {"hanzi": "晒被子", "en": "air quilts under the sun"}, {"hanzi": "晾晒", "en": "dry in the sun and air"}, {"hanzi": "防晒霜", "en": "sunscreen; sun cream"}, {"hanzi": "晒伤", "en": "sunburn"}, {"hanzi": "暴晒", "en": "expose to scorching baking sun"}], "idioms": [{"hanzi": "三天打鱼，两天晒网", "pinyin": "sān tiān dǎ yú, liǎng tiān shài wǎng", "meaning_en": "go fishing three days and dry nets two days; lack perseverance"}, {"hanzi": "风吹日晒", "pinyin": "fēng chuī rì shài", "meaning_en": "weathered by wind and scorched by sun; endure outdoor hardship"}, {"hanzi": "饱经风霜", "pinyin": "bǎo jīng fēng shuāng", "meaning_en": "weather-beaten; having experienced many hardships of life"}, {"hanzi": "烈日炎炎", "pinyin": "liè rì yán yán", "meaning_en": "the blazing sun scorching hot"}], "character_decomposition": [{"character": "晒", "pinyin": "shài", "meaning_en": "dry in sun; bask; expose", "meaning_es": "secar al sol; solear; asolearse", "radical": "日", "radical_meaning_en": "sun / day", "meaning_component": "日 (sun radiating light and warmth)", "sound_component": "西 (xī, west / phonetic)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where sun radical 日 combines with phonetic 西; simplified from traditional 曬.", "visual_mnemonic_story_en": "Hanging fresh fabrics outside as the bright sun (日) sets toward the west (西) to bake in warmth.", "visual_mnemonic_story_es": "Extender telas al aire libre mientras el sol (日) brilla cálido hacia el poniente (西) absorbiendo la luz.", "tone_mnemonic_anchor": "51", "cangjie": "AMCW", "traditional": "曬"}], "extended_reading_passages": [{"id": "#1", "hanzi": "阳光明媚的周末，小区的阳台上铺满了各色被褥。经过整整一个下午的暴晒，棉絮里吸饱了太阳的温暖与干爽。扑倒在刚晒好的被子里深吸一口气，那熟悉的青草香气让人彻底卸下周身疲惫。", "pinyin": "Yángguāng míngmèi de zhōumò, xiǎoqū de yángtái shàng pūmǎn le gèsè bèirù. Jīngguò zhěngzhěng yí gè xiàwǔ de bàoshài, miánxù lǐ xī bǎo le tàiyáng de wēnnuǎn yǔ gānshuǎng. Pūdǎo zài gāng shài hǎo de bèizi lǐ shēn xī yì kǒu qì, nà shúxī de qīngcǎoxiāng qì ràng rén chèdǐ xièxià zhōushēn píbèi.", "en": "On a bright weekend, residential balconies fill with colorful bedding. Baked throughout the afternoon, cotton absorbs the sun's warmth. Collapsing onto the sun-dried quilt with a deep breath, familiar fresh scents dissolve all exhaustion.", "es": "En fines de semana soleados, los balcones se llenan de colchas. Tras una siesta bajo el sol, el algodón absorbe calidez y pureza. Al tenderse en la colcha recién soleada aspirando su fragancia, el cuerpo se libera de toda fatiga."}, {"id": "#2", "hanzi": "传统中药材炮制工艺中的“日晒”绝非单纯脱水，而是借助特定波长的紫外线促进活性成分转化的关键生化环节。科研机构通过光谱模拟与控温干燥技术，成功实现了传统晒制工艺的数字化与标准化升级。", "pinyin": "Chuántǒng zhōngyàocái páozhì gōngyì zhōng de \"rìshài\" juéfēi dānchún tuōshuǐ, ér shì jièzhù tèdìng bōcháng de zǐwàixiàn cùjìn huóxìng chéngfèn zhuǎnhuà de guānjiàn shēnghuà huánjié. Kēyán jīgòu tōngguò guāngpǔ mónǐ yǔ kòngwēn gānzào jìshù, chénggōng shíxiàn le chuántǒng shàizhì gōngyì de shùzìhuà yǔ biāozhǔnhuà shēngjí.", "en": "Sun-drying in traditional medicine preparation is not mere dehydration, but a photochemical phase transforming active compounds via UV wavelengths. Research centers simulate solar spectra to standardize traditional drying methods digitally.", "es": "El soleado en la medicina tradicional supera la deshidratación; los rayos ultravioleta activan fitoquímicos esenciales. Laboratorios modernos reproducen espectros solares para industrializar este método milenario con rigor científico."}]}, {"meanings_summary": {"en": "quilt; blanket; duvet; comforter", "es": "edredón; colcha; manta; manta acolchada"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Soft fabric stitched like a warm outer skin (被) wraps around you like a child (子) in a cozy quilt (被子).", "composite_memory_hook_es": "Una suave tela acolchada como una segunda piel (被) abriga al durmiente como a un niño (子) en una colcha (被子).", "cultural_and_cognitive_roots": "In Chinese tradition, cotton quilts are central to matrimonial dowries and maternal devotion; receiving a handmade quilt signifies enduring maternal protection and familial warmth across distance.", "tone_sandhi_and_pitch_modulation": "Pronounced with 4th tone followed by the neutral tone: 'bèi zi' (51-0). Avoid giving 'zi' full 3rd tone weight."}, "semantic_boundary_contrasts": {"core_nuance": "被子 specifically designates a thick quilted bedding cover stuffed with cotton or feathers used over the body.", "contrasts": [{"id": "1", "compared_word": "被子 vs. 褥子", "pinyin": "rùzi", "analysis": "被子 is the top cover draped over the sleeping body, whereas 褥子 is the padded mattress pad laid beneath the sleeper."}, {"id": "2", "compared_word": "被子 vs. 毯子", "pinyin": "tǎnzi", "analysis": "被子 is thick and stuffed with batting (cotton, down, silk), while 毯子 refers to a woven, single-layer woolen or fleece blanket."}, {"id": "3", "compared_word": "被子 vs. 席子", "pinyin": "xízi", "analysis": "被子 provides thermal insulation against cold, while 席子 is a cooling woven bamboo or straw mat used on summer beds."}]}, "traps_and_cognates": {"look_alikes": [{"character": "破", "pinyin": "pò", "meaning_en": "broken; damaged", "distinction_note": "Has 石 (stone) on the left instead of 衤 (clothing)"}, {"character": "坡", "pinyin": "pō", "meaning_en": "slope; hillside", "distinction_note": "Has 土 (earth) on the left instead of 衤"}, {"character": "波", "pinyin": "bō", "meaning_en": "wave; ripple", "distinction_note": "Has 氵 (water) on the left instead of 衤"}, {"character": "初", "pinyin": "chū", "meaning_en": "beginning; first", "distinction_note": "Has 衤 on left but 刀 on right instead of 皮"}], "etymological_cognates": [{"character": "被褥", "pinyin": "bèi rù", "gloss_en": "bedding; quilts and mattresses"}, {"character": "被套", "pinyin": "bèi tào", "gloss_en": "quilt cover; duvet slipcover"}, {"character": "棉被", "pinyin": "mián bèi", "gloss_en": "cotton-padded quilt"}, {"character": "植被", "pinyin": "zhí bèi", "gloss_en": "vegetation cover (botanical)"}]}, "id": "24", "hanzi": "被子", "pinyin": "bèi zi", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a quilted blanket filled with cotton, down, or wool used for sleeping warmly", "definition_es": "edredón; colcha rellena de algodón o plumón para dormir abrigado", "example_phrase": "盖被子 (cover with a quilt)"}], "example_sentences": [{"id": "#1", "hanzi": "母亲知道城里冬天阴冷，特意用老家新采摘的头茬白棉花，亲手缝制了一床十斤重的大棉被。", "pinyin": "Mǔqīn zhīdào chénglǐ dōngtiān yīnlěng, tèyì yòng lǎojiā xīn cǎizhāi de tóuchá bái miánhua, qīnshǒu féngzhì le yì chuáng shí jīn zhòng de dà miánbèi.", "en": "Knowing city winters are damp and chilly, mother specially used newly picked prime white cotton from home to hand-stitch a ten-pound quilt.", "es": "Consciente del frío húmedo urbano en invierno, mi madre seleccionó el mejor algodón blanco de la aldea para coser a mano una manta acolchada."}, {"id": "#2", "hanzi": "为了保障受灾群众温暖过冬，民政部门紧急调拨了数万床保暖被子与防寒服迅速运往震区。", "pinyin": "Wèile bǎozhàng shòuzāi qúnzhòng wēnnuǎn guòdōng, mínzhèng bùmén jǐnjí diàobō le shù wàn chuáng bǎonuǎn bèizi yǔ fánghánfú xùnsù yùn wǎng zhènqū.", "en": "To ensure disaster victims stay warm through winter, civil affairs departments urgently dispatched tens of thousands of thermal quilts to the quake zone.", "es": "Para que los damnificados pasen un invierno cálido, las autoridades enviaron de urgencia decenas de miles de mantas térmicas a la zona sísmica."}], "collocations": [{"hanzi": "盖被子", "en": "cover with a quilt / blanket"}, {"hanzi": "晒被子", "en": "sun / air a quilt"}, {"hanzi": "缝被子", "en": "sew a quilt by hand"}, {"hanzi": "叠被子", "en": "fold the quilt / make the bed"}, {"hanzi": "一床被子", "en": "one quilt / blanket (classifier 床)"}, {"hanzi": "棉被", "en": "cotton quilt; padded blanket"}], "idioms": [{"hanzi": "高枕无忧", "pinyin": "gāo zhěn wú yōu", "meaning_en": "sleep on a high pillow without care; rest easy and worry-free"}, {"hanzi": "安居乐业", "pinyin": "ān jū lè yè", "meaning_en": "live in peace and work happily with contentment"}, {"hanzi": "同床异梦", "pinyin": "tóng chuáng yì mèng", "meaning_en": "share the same bed but dream different dreams; outward unity with inner division"}, {"hanzi": "寒冬腊月", "pinyin": "hán dōng là yuè", "meaning_en": "the coldest months of deep winter"}], "character_decomposition": [{"character": "被", "pinyin": "bèi", "meaning_en": "quilt; cover; passive marker", "meaning_es": "edredón; cubrir; por (voz pasiva)", "radical": "衤", "radical_meaning_en": "clothing (cloth radical)", "meaning_component": "衤 (fabric or clothing enclosing the body)", "sound_component": "皮 (pí, animal hide / phonetic)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where clothing radical 衤 and phonetic 皮 (skin) evoke a protective skin-like fabric layer.", "visual_mnemonic_story_en": "A layer of warm fabric clothing (衤) functioning like a second animal skin (皮) to keep the sleeper warm.", "visual_mnemonic_story_es": "Una prenda acolchada de tela (衤) que abriga como una segunda piel (皮) protegiendo el sueño nocturno.", "tone_mnemonic_anchor": "51", "cangjie": "LDE", "traditional": "被"}, {"character": "子", "pinyin": "zi", "meaning_en": "noun suffix", "meaning_es": "sufijo nominal", "radical": "子", "radical_meaning_en": "child / infant", "meaning_component": "子 (infant pictograph)", "sound_component": "", "stroke_count": "3", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of a child, used across spoken Mandarin as a lightweight noun-forming suffix.", "visual_mnemonic_story_en": "A child (子) serving as an everyday conversational affix appended to home objects.", "visual_mnemonic_story_es": "Una pequeña figura (子) que actúa como sufijo cotidiano en el vocabulario doméstico.", "tone_mnemonic_anchor": "214", "cangjie": "ND", "traditional": ""}], "extended_reading_passages": [{"id": "#1", "hanzi": "钻进刚被母亲晒过、铺得平平整整的被子里，满鼻腔都是混合着阳光与棉絮的清甜香气。那份沉甸甸的暖意迅速包裹全身，让人仿佛重回幼年时无忧无虑的怀抱，一夜好梦到天亮。", "pinyin": "Zuānjìn gāng bèi mǔqīn shài guò, pū de píngpíng-zhěngzhěng de bèizi lǐ, mǎn bíqiāng dōu shì hùnhé zhe yángguāng yǔ miánxù de qīngtián xiāngqì. Nà fèn chéndiāndiān de nuǎnyì xùnsù bǎoguǒ quánshēn, ràng rén fǎngrú chónghuí yòunián shí wúyōu-wúlǜ de huáibào, yí yè hǎomèng dào tiānliàng.", "en": "Slipping under the quilt freshly sunned and made by mother, one's senses fill with the sweet aroma of sunshine and cotton. That heavy warmth wraps the entire body, recalling innocent childhood embrace and peaceful sleep till dawn.", "es": "Al deslizarse bajo la colcha recién asoleada y estirada por la madre, se respira un suave aroma a sol y algodón. El cálido abrazo de la tela disipa el frío devolviendo la dulce paz de la infancia hasta el amanecer."}, {"id": "#2", "hanzi": "家用纺织品产业的科技升级正深刻改变着传统寝具市场。抗菌防螨纤维、石墨烯远红外控温发热材料被广泛应用于新型被子的研发，实现了在轻量化质感下的优异保暖与微环境湿度智能调节。", "pinyin": "Jiāyòng fǎngzhīpǐn chǎnyè de kējì shēngjí zhèng shēnkè gǎibiàn zhe chuántǒng qǐnjù shìchǎng. Kàngjūn fángmǎn xiānwéi, shímòxī yuǎnhóngwài kòngwēn fārè cáiliào bèi guǎngfàn yìngyòng yú xīnxíng bèizi de yánfā, shíxiàn le zài qīngliànghuà zhìgǎn xià de yōuyì bǎonuǎn yǔ wēihuánjìng shīdù zhìnéng tiáojié.", "en": "Technological modernization in home textiles is transforming the bedding market. Antibacterial fibers and graphene far-infrared thermal materials applied in modern duvets achieve ultralight warmth and smart humidity regulation.", "es": "La innovación textil moderniza el mercado de la ropa de cama. Fibras hipoalergénicas y grafeno autorregulador crean edredones ligeros de alto rendimiento térmico que optimizan el descanso nocturno."}]}, {"meanings_summary": {"en": "long-distance; long haul; long journey", "es": "larga distancia; largo trayecto; largo recorrido"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Walking an extensively long (长) highway route (途) completes an arduous long-distance journey (长途).", "composite_memory_hook_es": "Recorrer una ruta (途) sumamente larga (长) define un viaje de larga distancia (长途).", "cultural_and_cognitive_roots": "In Chinese poetry, '长途' carries profound historical resonance of post stations, official couriers, and migrant workers journeying across mountains to reunite with distant families during Lunar New Year ('春运').", "tone_sandhi_and_pitch_modulation": "Pronounced with twin 2nd tones: 'cháng tú' (35-35). Both syllables rise smoothly in pitch; articulate the 't' clearly."}, "semantic_boundary_contrasts": {"core_nuance": "长途 emphasizes significant geographic spatial distance or extended travel duration.", "contrasts": [{"id": "1", "compared_word": "长途 vs. 短途", "pinyin": "duǎntú", "analysis": "长途 denotes cross-city or interprovincial travel covering vast distances, whereas 短途 refers to local suburban or intra-city commutes."}, {"id": "2", "compared_word": "长途 vs. 远道", "pinyin": "yuǎndào", "analysis": "长途 describes the physical nature of transport or travel (e.g. 长途客运), while 远道 is often used in polite hospitality phrases welcoming guests from afar (e.g. 远道而来)."}, {"id": "3", "compared_word": "长途 vs. 漫长", "pinyin": "màncháng", "analysis": "长途 anchors specifically to physical travel distance or routes, whereas 漫长 describes abstract or psychological duration of time (e.g. 漫长的等待, 漫长的岁月)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "短", "pinyin": "duǎn", "meaning_en": "short; brief", "distinction_note": "Direct semantic antonym of 长; has 矢 and 豆"}, {"character": "徐", "pinyin": "xú", "meaning_en": "slowly; gentle", "distinction_note": "Has 彳 (step) instead of 辶 (walking radical)"}, {"character": "除", "pinyin": "chú", "meaning_en": "eliminate; divide", "distinction_note": "Has 阝 (mound) on the left of 余 instead of 辶"}, {"character": "叙", "pinyin": "xù", "meaning_en": "narrate; chat", "distinction_note": "Has 又 on the right of 余 instead of 辶"}], "etymological_cognates": [{"character": "途径", "pinyin": "tú jìng", "gloss_en": "pathway; channel; avenue"}, {"character": "前途", "pinyin": "qián tú", "gloss_en": "future prospects; outlook"}, {"character": "沿途", "pinyin": "yán tú", "gloss_en": "along the way; en route"}, {"character": "旅途", "pinyin": "lǚ tú", "gloss_en": "journey; trip"}]}, "id": "25", "hanzi": "长途", "pinyin": "cháng tú", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a journey covering a long physical distance; long haul", "definition_es": "viaje de larga distancia; trayecto prolongado", "example_phrase": "长途旅行 (long-distance trip)"}, {"sense_number": "2", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "operating or communicating over long distances", "definition_es": "de larga distancia (transporte, telecomunicación)", "example_phrase": "长途汽车 (long-distance bus)"}], "example_sentences": [{"id": "#1", "hanzi": "经过十几个小时的长途颠簸，客车终于在夜幕降临时缓缓驶进了县城客运站。", "pinyin": "Jīngguò shí jǐ gè xiǎoshí de chángtú diānbǒ, kèchē zhōngyú zài yèmù jiànglín shí huǎnhuǎn shǐjìn le xiànchéng kèyùnzhàn.", "en": "After more than ten hours of bumpy long-distance travel, the coach finally pulled slowly into the county passenger station at nightfall.", "es": "Tras más de diez horas de traqueteo en un viaje de larga distancia, el autobús entró despacio en la estación del pueblo al caer la noche."}, {"id": "#2", "hanzi": "高铁网络的四通八达彻底重塑了人们的出行方式，使原本耗时漫长的跨省长途通勤变得前所未有的快捷与舒适。", "pinyin": "Gāotiě wǎngluò de sìtōng-bādá chèdǐ zhòngshù le rénmen de chūxíng fāngshì, shǐ yuánběn hàoshí màncháng de kuàshěng chángtú tōngqín biàn de qiánsuǒwèiyǒu de kuàijié yǔ shūshì.", "en": "The extensive high-speed rail network has revolutionized travel, making interprovincial long-distance journeys faster and more comfortable than ever.", "es": "La densa red de trenes de alta velocidad ha revolucionado la movilidad, haciendo los trayectos de larga distancia más veloces y confortables que nunca."}], "collocations": [{"hanzi": "长途汽车", "en": "long-distance bus / coach"}, {"hanzi": "长途电话", "en": "long-distance phone call"}, {"hanzi": "长途旅行", "en": "long-distance travel"}, {"hanzi": "长途跋涉", "en": "trek a long distance; arduous journey"}, {"hanzi": "长途客运", "en": "long-distance passenger transport"}, {"hanzi": "长途奔波", "en": "rush around on long journeys"}], "idioms": [{"hanzi": "长途跋涉", "pinyin": "cháng tú bá shè", "meaning_en": "trek a long and arduous journey across mountains and rivers"}, {"hanzi": "道阻且长", "pinyin": "dào zǔ qiě cháng", "meaning_en": "the road is perilous and long; steep challenges ahead"}, {"hanzi": "前途无量", "pinyin": "qián tú wú liàng", "meaning_en": "have boundless prospects and limitless future"}, {"hanzi": "风雨兼程", "pinyin": "fēng yǔ jiān chéng", "meaning_en": "travel day and night braving wind and rain"}], "character_decomposition": [{"character": "长", "pinyin": "cháng", "meaning_en": "long; space; time", "meaning_es": "largo; extenso; prolongado", "radical": "长", "radical_meaning_en": "long hair / elder", "meaning_component": "长 (flowing hair of an elder)", "sound_component": "", "stroke_count": "4", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient oracle script depicting an elder leaning on a cane with long flowing hair, symbolizing enduring distance.", "visual_mnemonic_story_en": "An elder's long hair (长) cascading down, evoking an unbroken line stretching far into the distance.", "visual_mnemonic_story_es": "Los largos cabellos de un anciano (长) ondeando al viento, evocando una línea que se prolonga a lo lejos.", "tone_mnemonic_anchor": "35", "cangjie": "LO", "traditional": "長"}, {"character": "途", "pinyin": "tú", "meaning_en": "way; road; journey", "meaning_es": "camino; vía; trayecto; ruta", "radical": "辶", "radical_meaning_en": "walking / motion", "meaning_component": "辶 (advancing along a route)", "sound_component": "余 (yú, ample / phonetic)", "stroke_count": "10", "composition_type": "半包围结构", "etymology_and_mnemonic": "Phono-semantic compound where walking radical 辶 indicates traveling along an established highway or path (途).", "visual_mnemonic_story_en": "Stepping forward along a road (辶) with surplus energy (余) to conquer a protracted journey.", "visual_mnemonic_story_es": "Avanzar a paso firme por una senda (辶) con vigor suficiente (余) para culminar una ruta prolongada.", "tone_mnemonic_anchor": "35", "cangjie": "YOMD", "traditional": "途"}], "extended_reading_passages": [{"id": "#1", "hanzi": "伴随长途列车车轮有节奏的撞击声，车窗外的群山与原野飞速向后退去。车厢里满载着思乡的游子，尽管身体疲惫，但只要想到列车终点那盏为自己亮着的家灯，漫长的旅途便充满了温情。", "pinyin": "Bànsuí chángtú lièchē chēlún yǒujiézòu de zhuàngjī shēng, chēchuāng wài de qúnshān yǔ yuányě fēisù xiànghòu tuìqù. Chēxiāng lǐ mǎnzài zhe sīxiāng de yóuzǐ, jǐnguǎn shēntǐ píbèi, dàn zhǐyào xiǎngdào lièchē zhōngdiǎn nà zhǎn wèi zìjǐ liàng zhe de jiādēng, màncháng de lǚtú biàn chōngmǎn le wēnqíng.", "en": "To the rhythmic clatter of long-distance train wheels, hills and fields retreat swiftly outside the window. Tired travelers fill the cars, yet knowing a home lamp shines at the journey's end warms every mile.", "es": "Al compás rítmico de los raíles del tren de larga distancia, montes y llanuras desfilan tras el cristal. Pese al cansancio, la certeza de la luz del hogar al término del trayecto llena de afecto el camino."}, {"id": "#2", "hanzi": "现代化多式联运物流体系正重塑长途干线货运格局。通过铁路班列与大型公路货车的高效衔接，跨区域生鲜食品与高端工业品的长途周转损耗显著降低，大幅提升了国家大市场内部的资源流通效率。", "pinyin": "Xiàndàihuà duōshì liányùn wùliú tǐxì zhèng chóngshù chángtú gànxiàn huòyùn géjú. Tōngguò tiělù bānliè yǔ dàxíng gōnglù huòchē de gāoxiào xiánjiē, kuàqūyù shēngxiān shípǐn yǔ gāoduān gōngyèpǐn de chángtú zhōuzhuǎn sǔnhào xiǎnzhù jiàngdī, dàfú tíshēng le guójiā dàshìchǎng nèibù de zīyuán liútōng xiàolǜ.", "en": "Multimodal logistics systems are reshaping long-distance freight patterns. Seamless rail-to-truck transfers minimize transit spoilage of perishables and high-tech freight, maximizing unified market distribution.", "es": "La logística intermodal moderna transforma el transporte de mercancías de larga distancia. La coordinación de ferrocarril y carretera reduce mermas y dinamiza la distribución eficiente en el mercado nacional."}]}, {"meanings_summary": {"en": "to freeze; to feel very cold; to suffer from frostbite; jelly/aspic", "es": "congelarse; helar; pasar mucho frío; aterirse; gelatina"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Ice crystals (冫) blowing from the eastern dawn (东) freeze everything solid (冻).", "composite_memory_hook_es": "Gotas heladas (冫) que llegan desde el este (东) congelan la tierra con su frío (冻).", "cultural_and_cognitive_roots": "In northern Chinese folklore and poetry, winter frostbite ('冻') contrastively highlights the moral warmth of the heated kang bed, hand-stitched quilted padding, and family solidarity against nature's cruelty.", "tone_sandhi_and_pitch_modulation": "Pronounced in the 4th tone with an abrupt falling pitch: 'dòng' (51). Distinguish from 4th tone 'dòng' (动, 洞)."}, "semantic_boundary_contrasts": {"core_nuance": "冻 refers specifically to liquid solidifying into ice or the physiological suffering caused by freezing subzero temperatures.", "contrasts": [{"id": "1", "compared_word": "冻 vs. 冷", "pinyin": "lěng", "analysis": "冷 is a general sensory state of low ambient temperature (e.g. 今天很冷), whereas 冻 denotes the extreme physical consequence where temperature reaches the freezing threshold causing numbness or ice (e.g. 手冻僵了)."}, {"id": "2", "compared_word": "冻 vs. 凉", "pinyin": "liáng", "analysis": "凉 implies comfortably cool or pleasant lack of heat (e.g. 凉快, 凉水), in sharp contrast to the painful freezing of 冻."}, {"id": "3", "compared_word": "冻 vs. 凝", "pinyin": "níng", "analysis": "冻 specifies solidification driven by cold/ice, while 凝 refers broadly to chemical curdling, condensation, or coagulation (e.g. 凝固, 凝结)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "栋", "pinyin": "dòng", "meaning_en": "ridgepole; pillar", "distinction_note": "Has 木 (wood) on the left instead of 冫 (ice)"}, {"character": "陈", "pinyin": "chén", "meaning_en": "display; old; surname", "distinction_note": "Has 阝 (mound) on the left of 东"}, {"character": "炼", "pinyin": "liàn", "meaning_en": "smelt; refine", "distinction_note": "Has 火 (fire) on the left instead of 冫"}, {"character": "冷", "pinyin": "lěng", "meaning_en": "cold; chilly", "distinction_note": "Shares radical 冫 but has 令 on the right instead of 东"}], "etymological_cognates": [{"character": "冷冻", "pinyin": "lěng dòng", "gloss_en": "freeze; refrigeration"}, {"character": "冰冻", "pinyin": "bīng dòng", "gloss_en": "frozen"}, {"character": "冻结", "pinyin": "dòng jié", "gloss_en": "freeze assets or progress"}, {"character": "解冻", "pinyin": "jiě dòng", "gloss_en": "thaw; unfreeze"}]}, "id": "26", "hanzi": "冻", "pinyin": "dòng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to freeze; to turn into ice due to low temperature", "definition_es": "congelarse; helarse", "example_phrase": "河水冻成了坚冰 (the river froze into solid ice)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to feel very cold; to suffer chills or frostbite", "definition_es": "tener mucho frío; aterirse", "example_phrase": "手脚冻得通红 (hands and feet frozen red)"}, {"sense_number": "3", "part_of_speech": "Noun", "register": "Standard", "definition_en": "jelly; aspic; gelatinous cold dish", "definition_es": "gelatina; aspic", "example_phrase": "果冻 (fruit jelly)"}], "example_sentences": [{"id": "#1", "hanzi": "冬天清晨顶着北风出门，走在去学校的泥土路上，我的双手经常被冻得通红发僵。", "pinyin": "Dōngtiān qīngchén dǐng zhe běifēng chūmén, zǒu zài qù xuéxiào de nítǔ lù shàng, wǒ de shǒushān jīngcháng bèi dòng de tōnghóng fājiāng.", "en": "Heading out against the north wind on winter mornings, walking dirt paths to school, my hands often froze bright red and stiff.", "es": "Al salir al alba invernal encarando el viento del norte por caminos de tierra hacia la escuela, mis manos se helaban rojas y rígidas."}, {"id": "#2", "hanzi": "为了保持远洋捕捞水产品的鲜美品质，大型现代化冷链运输船配备了先进的超低温速冻装置。", "pinyin": "Wèile bǎochí yuǎnyáng bǔlāo shuǐchǎnpǐn de xiānměi pǐnzhì, dàxíng xiàndàihuà lěngliàn yùnshū chuán pèibèi le xiānjìn de chāodīwēn sùdòng zhuāngzhì.", "en": "To preserve the freshness of deep-sea catch, large modern cold-chain cargo ships are equipped with advanced ultra-low temperature flash-freezing devices.", "es": "Para preservar la frescura de la pesca en alta mar, los modernos buques frigoríficos incorporan sistemas avanzados de congelación rápida a ultrabaja temperatura."}], "collocations": [{"hanzi": "冷冻", "en": "freeze; refrigerate"}, {"hanzi": "冰冻", "en": "frozen; freeze over"}, {"hanzi": "冻僵", "en": "frozen stiff; numb with cold"}, {"hanzi": "冻结", "en": "freeze (assets, accounts, or water)"}, {"hanzi": "果冻", "en": "fruit jelly / gelatin"}, {"hanzi": "冻疮", "en": "chilblain; frostbite"}], "idioms": [{"hanzi": "冰冻三尺，非一日之寒", "pinyin": "bīng dòng sān chǐ, fēi yí rì zhī hán", "meaning_en": "it takes more than one cold day for a river to freeze three feet deep; troubles build over time"}, {"hanzi": "滴水成冰", "pinyin": "dī shuǐ chéng bīng", "meaning_en": "dripping water freezes into ice; bitterly frigid cold"}, {"hanzi": "饥寒交迫", "pinyin": "jī hán jiāo pò", "meaning_en": "beset by hunger and cold; living in extreme deprivation"}, {"hanzi": "冻骨露野", "pinyin": "dòng gǔ lù yě", "meaning_en": "frozen corpses exposed across wild fields; horrific casualties of famine or war"}], "character_decomposition": [{"character": "冻", "pinyin": "dòng", "meaning_en": "freeze; cold; jelly", "meaning_es": "congelar; helar; pasar frío", "radical": "冫", "radical_meaning_en": "ice / two drops of water", "meaning_component": "冫 (freezing ice crystals)", "sound_component": "东 (dōng, east / phonetic)", "stroke_count": "7", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where ice radical 冫 indicates subzero solidification, paired with phonetic 东.", "visual_mnemonic_story_en": "Two chilling icicles (冫) freezing a tree facing the morning east (东) into solid crystal.", "visual_mnemonic_story_es": "Dos carámbanos gélidos (冫) que congelan por completo el árbol que mira al oriente (东).", "tone_mnemonic_anchor": "51", "cangjie": "IMOD", "traditional": "凍"}], "extended_reading_passages": [{"id": "#1", "hanzi": "北方的冬日清晨呵气成霜，屋檐下挂满了长长的冰锥。早起推开柴门，寒风扑面而来，双手瞬间冻得发麻。然而只要走回生着炭火的老屋，扑面而来的热气总能迅速融化周身的冰冷。", "pinyin": "Běifāng de dōngrì qīngchén hēqì-chéngshuāng, wūyán xià guàmǎn le chángcháng de bīngzhuī. Zǎoqǐ tuīkāi cháimén, hánfēng pūmiàn ér lái, shǒushān shùnjiān dòng de fāmá. Rán'ér zhǐyào zǒuhuí shēng zhe tànhuǒ de lǎowū, pūmiàn ér lái de rèqì zǒng néng xùnsù rónghuà zhōushēn de bīnglěng.", "en": "Winter dawn in the north turns breath into frost, icicles dripping from eaves. Pushing open the gate, chilly wind numbs fingers instantly. Yet returning into the hearth-warmed cottage, rising warmth melts the cold away.", "es": "La mañana invernal en el norte hiela el aliento en vaho y cuelga carámbanos del tejado. El viento adormece las manos; mas al volver al calor del fuego en la casa vieja, el aire tibio disuelve el frío al instante."}, {"id": "#2", "hanzi": "全球气候变化背景下，高纬度永冻土层的融化正对区域基础设施安全构成严峻威胁。科研团队通过铺设热棒降温与地基隔热技术，有效减缓了冻土退化速度，为青藏高原重大铁路工程的长期稳定运营提供了科技支撑。", "pinyin": "Quánqiú qìhòu biànhuà bèijǐng xià, gāowěidù yǒngdòngtǔ céng de rónghuà zhèng duì qūyù jīchǔ shèshī ānquán gòuchéng yánjùn wēixié. Kēyán tuánduì tōngguò pūshè rèbàng jiàngwēn yǔ dìjī gérè jìshù, yǒuxiào jiǎnhuǎn le dòngtǔ tuìhuà sùdù, wèi Qīng-Zàng Gāoyuán zhòngdà tiělù gōngchéng de chángqī wěndìng yùnyíng tígōng le kējì zhīchēng.", "en": "Under global climate change, thawing permafrost in high latitudes poses severe threats to infrastructure. Deploying thermosyphon cooling and thermal insulation, research teams curb permafrost degradation, safeguarding Tibetan railways.", "es": "El deshielo del permafrost por el cambio climático amenaza las infraestructuras árticas. Ingenieros aplican termosifones y aislamiento térmico en el Tíbet para mitigar la degradación del suelo helado y estabilizar el ferrocarril."}]}, {"meanings_summary": {"en": "to imagine; to visualize; to conceive; imagination", "es": "imaginar; figurarse; concebir; imaginación; fantasía"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Using the reflective heart (想) to form the mental shape of an elephant (象) is the power to imagine (想象).", "composite_memory_hook_es": "Usar el corazón meditativo (想) para dibujar la silueta majestuosa (象) permite imaginar (想象) lo que no está.", "cultural_and_cognitive_roots": "Han Feizi noted that ancient people rarely saw live elephants, so they reconstructed elephant forms by gazing upon unearthed bones; thus mental reconstruction was called 'xiàng' (象/想象).", "tone_sandhi_and_pitch_modulation": "Pronounced with a 214-51 pitch contour (3rd tone dipping cleanly, followed by 4th tone falling resolutely)."}, "semantic_boundary_contrasts": {"core_nuance": "想象 emphasizes generating subjective mental concepts, creative pictures, or scenarios not physically present.", "contrasts": [{"id": "1", "compared_word": "想象 vs. 猜测", "pinyin": "cāicè", "analysis": "想象 means picturing or visualizing hypothetical scenarios in the mind's eye, whereas 猜测 means estimating or guessing facts based on limited clues (e.g. 猜测谜底)."}, {"id": "2", "compared_word": "想象 vs. 设想", "pinyin": "shèxiǎng", "analysis": "想象 is unconstrained creative fantasy or visualization, while 设想 implies constructive, systematic planning or tentative hypothesis formulation for practical execution."}, {"id": "3", "compared_word": "想象 vs. 回忆", "pinyin": "huíyì", "analysis": "想象 produces novel mental pictures of things unexperienced or future, whereas 回忆 reconstructs past events genuinely experienced in memory."}]}, "traps_and_cognates": {"look_alikes": [{"character": "像", "pinyin": "xiàng", "meaning_en": "resemble; statue; like", "distinction_note": "Has 亻 (person) radical on the left of 象"}, {"character": "相", "pinyin": "xiāng", "meaning_en": "mutual; appearance", "distinction_note": "Top component of 想 without lower 心"}, {"character": "家", "pinyin": "jiā", "meaning_en": "home; family", "distinction_note": "Has 宀 (roof) on top of 豕 instead of elephant head strokes"}, {"character": "逐", "pinyin": "zhú", "meaning_en": "pursue; chase", "distinction_note": "Has 辶 (walk) on left of 豕"}], "etymological_cognates": [{"character": "景象", "pinyin": "jǐng xiàng", "gloss_en": "scene; sight; phenomenon"}, {"character": "表象", "pinyin": "biǎo xiàng", "gloss_en": "representation; semblance"}, {"character": "思想", "pinyin": "sī xiǎng", "gloss_en": "thought; ideology; thinking"}, {"character": "设想", "pinyin": "shè xiǎng", "gloss_en": "conceive; envision; tentative plan"}]}, "id": "27", "hanzi": "想象", "pinyin": "xiǎng xiàng", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to form a mental image or concept of something not present or not yet experienced", "definition_es": "imaginar; representarse mentalmente algo no vivido", "example_phrase": "难以想象 (hard to imagine)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "the faculty of imagining; imaginative vision or fancy", "definition_es": "imaginación; fantasía creadora", "example_phrase": "丰富的想象力 (rich imagination)"}], "example_sentences": [{"id": "#1", "hanzi": "没进过城的老母亲很难想象，在几十层的高楼大厦里，人们只要按一下电梯按钮就能瞬间上下穿梭。", "pinyin": "Méi jìn guò chéng de lǎo mǔqīn hěn nán xiǎngxiàng, zài jǐshí céng de gāolóu-dàshà lǐ, rénmen zhǐyào àn yíxià diàntī ànniǔ jiù néng shùnjiān shàngxià chuānsuō.", "en": "The elderly mother who had never been to a city found it hard to imagine that in skyscrapers tens of stories high, people ride up and down in seconds just by pushing a button.", "es": "La anciana madre, que nunca había pisado la gran ciudad, apenas podía figurarse que en rascacielos de decenas de plantas la gente subiera al instante pulsando un ascensor."}, {"id": "#2", "hanzi": "这部优秀的科幻小说打破了传统时空维度的桎梏，以超凡的想象力为读者描摹出宏伟壮阔的宇宙图景。", "pinyin": "Zhè bù yōuxiù de kēhuàn xiǎoshuō dǎpò le chuántǒng shíkōng wéidù de zhìgù, yǐ chāofán de xiǎngxiànglì wèi dúzhě miáomó chū hóngwěi zhuàngkuò de yǔzhòu tújǐng.", "en": "This outstanding sci-fi novel breaks the shackles of conventional spacetime dimensions, painting a majestic cosmic landscape for readers through extraordinary imagination.", "es": "Esta novela de ciencia ficción rompe las ataduras del espacio-tiempo convencional, dibujando con desbordante imaginación un tapiz cósmico sublime para el lector."}], "collocations": [{"hanzi": "超乎想象", "en": "beyond imagination"}, {"hanzi": "难以想象", "en": "hard to imagine / inconceivable"}, {"hanzi": "想象力", "en": "imagination; imaginative faculty"}, {"hanzi": "展开想象", "en": "unleash one's imagination"}, {"hanzi": "凭空想象", "en": "imagine out of thin air / groundless fancy"}, {"hanzi": "想象空间", "en": "room for imagination / creative scope"}], "idioms": [{"hanzi": "异想天开", "pinyin": "yì xiǎng tiān kāi", "meaning_en": "indulge in the wildest fantasies; whimsical imagination"}, {"hanzi": "奇思妙想", "pinyin": "qí sī miào xiǎng", "meaning_en": "wonderful ideas and bizarre thoughts; whimsical genius"}, {"hanzi": "浮想联翩", "pinyin": "fú xiǎng lián piān", "meaning_en": "thoughts and fantasies welling up in rapid succession"}, {"hanzi": "前所未有", "pinyin": "qián suǒ wèi yǒu", "meaning_en": "unprecedented; never seen or imagined before"}], "character_decomposition": [{"character": "想", "pinyin": "xiǎng", "meaning_en": "think; ponder; wish; miss", "meaning_es": "pensar; desear; añorar; meditar", "radical": "心", "radical_meaning_en": "heart / mind", "meaning_component": "心 (seat of thought and feeling)", "sound_component": "相 (xiāng, mutual / looking)", "stroke_count": "13", "composition_type": "上下结构", "etymology_and_mnemonic": "Phono-semantic compound where the heart-mind 心 observes a mental mutual image (相) in reflection.", "visual_mnemonic_story_en": "A person looking intently (相) with the inner heart (心) to conceive thoughts of distant things.", "visual_mnemonic_story_es": "Una persona que contempla (相) con los ojos de su corazón (心) evocando imágenes en la mente.", "tone_mnemonic_anchor": "214", "cangjie": "DUP", "traditional": "想"}, {"character": "象", "pinyin": "xiàng", "meaning_en": "elephant; image; shape", "meaning_es": "elefante; imagen; forma visible", "radical": "豕", "radical_meaning_en": "pig / beast / elephant", "meaning_component": "象 (pictograph of an elephant with trunk and tusk)", "sound_component": "", "stroke_count": "11", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient pictograph of an elephant with a long trunk, later abstracting into 'image' or mental representation.", "visual_mnemonic_story_en": "An elephant (象) with its majestic long trunk and ivory tusks, projecting an unforgettable shape and image.", "visual_mnemonic_story_es": "La silueta de un elefante (象) con su trompa y colmillos, convertida en símbolo de una imagen visible.", "tone_mnemonic_anchor": "51", "cangjie": "NAO", "traditional": "象"}], "extended_reading_passages": [{"id": "#1", "hanzi": "小时候躺在夏夜的谷堆上，望着浩瀚无垠的星空，我的脑海里总会插上想象的翅膀。那些关于牛郎织女的神话传说，在银河璀璨的波光中化作了最瑰丽的梦境，悄然启蒙了对未知世界的探索渴望。", "pinyin": "Xiǎoshíhou tǎng zài xiàyè de gǔduī shàng, wàng zhe hàohàn-wúyín de xīngkōng, wǒ de nǎohǎi lǐ zǒng huì chā shàng xiǎngxiàng de chìbǎng. Nàxiē guānyú Niúláng Zhīnǚ de shénhuà chuánshuō, zài Yínhé cuǐcàn de bōguāng zhōng huàzuò le zuì guīlì de mèngjìng, qiǎorán qǐméng le duì wèizhī shìjiè de tànsuǒ kěwàng.", "en": "Lying on summer grain piles as a child, gazing at the boundless starry sky, imagination sprouted wings in my mind. Folktales of the Cowherd and Weaver transformed in the Milky Way into splendid dreams, awakening hunger to explore the unknown.", "es": "De niño, recostado sobre parvas de trigo bajo el cielo estival, la imaginación desplegaba alas. Las leyendas del Boyero y la Tejedora en la Vía Láctea creaban sueños radiantes que encendieron la curiosidad por el cosmos."}, {"id": "#2", "hanzi": "生成式人工智能技术的爆发式演进，正在彻底重塑人类的艺术创作与想象力边界。算法不仅能够根据文本指令瞬间合成多维视觉艺术，更在辅助工程设计与生物大分子折叠预测中展现出超乎人类传统经验的创新潜力。", "pinyin": "Shēngchéngshì réngōngzhìnéng jìshù de bàofāshì yǎnjìn, zhèngzài chèdǐ zhòngshù rénlèi de yìshù chuàngzuò yǔ xiǎngxiànglì biānjiè. Suànfǎ bùjǐn nénggòu gēnjù wénběn zhǐlìng shùnjiān héchéng duōwéi shìjué yìshù, gèng zài fǔzhù gōngchéng shèjì yǔ shēngwù dàmōzǐ zhédié yùcè zhōng zhǎnxiàn chū chāohū rénlèi chuántǒng jīngyàn de chuàngxīn qiánlì.", "en": "The explosive rise of generative AI is restructuring the frontiers of human artistic creation and imagination. Algorithms synthesize multidimensional visual arts and assist structural engineering and protein folding beyond traditional experience.", "es": "La inteligencia artificial generativa redefine los horizontes de la imaginación y el arte. Los algoritmos no solo recrean escenas visuales a partir de texto, sino que revolucionan el diseño industrial y el plegamiento proteico superando moldes previos."}]}, {"meanings_summary": {"en": "dust; dirt; airborne particulate matter", "es": "polvo; ceniza; partículas de suciedad en suspensión"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Burnt powdery ashes (灰) ground down like tiny specks of soil (尘) settle everywhere as dust (灰尘).", "composite_memory_hook_es": "Cenizas apagadas (灰) reducidas a diminutas partículas de tierra (尘) flotan como polvo (灰尘).", "cultural_and_cognitive_roots": "In Buddhist and Daoist literature, '尘' represents the mundane sensory realm ('红尘' = red dust / secular world); sweeping away physical dust metaphorically mirrors purifying the human heart of greed.", "tone_sandhi_and_pitch_modulation": "Pronounced with a 55-35 pitch contour (1st tone high and level, followed by 2nd tone rising cleanly). Ensure smooth vocal glide."}, "semantic_boundary_contrasts": {"core_nuance": "灰尘 denotes tiny physical dirt particles floating in the air or settling as a dry layer on surfaces.", "contrasts": [{"id": "1", "compared_word": "灰尘 vs. 泥土", "pinyin": "nítǔ", "analysis": "灰尘 consists of dry, airborne, or settled powdery particles indoors or out, whereas 泥土 refers to wet or moist natural soil, mud, and earth on the ground."}, {"id": "2", "compared_word": "灰尘 vs. 垃圾", "pinyin": "lājī", "analysis": "灰尘 is natural fine airborne particulate matter, while 垃圾 refers to solid human household or industrial garbage, rubbish, and debris."}, {"id": "3", "compared_word": "灰尘 vs. 尘埃", "pinyin": "chén'āi", "analysis": "灰尘 is the common everyday spoken term for household dust, while 尘埃 is formal and literary, frequently used in figurative idioms (e.g. 尘埃落定)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "炭", "pinyin": "tàn", "meaning_en": "charcoal; coal", "distinction_note": "Has 山 (mountain) on top of 火 instead of 𠂇"}, {"character": "尖", "pinyin": "jiān", "meaning_en": "sharp; pointed", "distinction_note": "Has 小 over 大 instead of 小 over 土"}, {"character": "堂", "pinyin": "táng", "meaning_en": "hall; room", "distinction_note": "Has 尚 remnant over 土 instead of 小"}, {"character": "炎", "pinyin": "yán", "meaning_en": "flame; inflammation", "distinction_note": "Two fires stacked vertically 火+火"}], "etymological_cognates": [{"character": "粉尘", "pinyin": "fěn chén", "gloss_en": "fine dust / industrial airborne particles"}, {"character": "风尘", "pinyin": "fēng chén", "gloss_en": "travel fatigue / worldly tribulations"}, {"character": "石灰", "pinyin": "shí huī", "gloss_en": "limestone; lime"}, {"character": "灰心", "pinyin": "huī xīn", "gloss_en": "discouraged; disheartened"}]}, "id": "28", "hanzi": "灰尘", "pinyin": "huī chén", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "fine dry powder consisting of tiny particles of earth, ash, or waste floating in the air or settling on surfaces", "definition_es": "polvo; partículas finas de tierra o suciedad suspendidas en el aire o posadas en superficies", "example_phrase": "擦去灰尘 (wipe off the dust)"}], "example_sentences": [{"id": "#1", "hanzi": "老屋久无人住，桌椅上落了厚厚的一层灰尘，母亲一进门便挽起袖子忙碌地打扫起来。", "pinyin": "Lǎowū jiǔ wú rén zhù, zhuōyǐ shàng luò le hòuhòu de yì céng huīchén, mǔqīn yí jìn mén biàn wǎn qǐ xiùzi mánglù de dǎsǎo qǐlái.", "en": "The old house had been vacant for long, leaving a thick layer of dust on tables and chairs; stepping inside, mother rolled up her sleeves and busily began cleaning.", "es": "La casa vieja llevaba tiempo deshabitada y el polvo cubría mesas y sillas; al cruzar el umbral, mi madre se arremangó y comenzó a faenar de inmediato."}, {"id": "#2", "hanzi": "为了确保超大规模集成电路晶圆的制造良率，无尘洁净车间利用高效空气过滤器将微米级灰尘严格隔离在核心产线之外。", "pinyin": "Wèile quèbǎo chāodà guīmó jíchéng diànlù jīngyuán de zhìzào liánglǜ, wúchén jiéjìng chējiān lìyòng gāoxiào kōngqì guòlǜqì jiāng wēimǐ jí huīchén yángé gélí zài héxīn chǎnxiàn zhīwài.", "en": "To ensure fabrication yield for very-large-scale integrated circuit wafers, cleanrooms deploy HEPA filters to strictly isolate micron dust from lines.", "es": "Para garantizar el rendimiento en la fabricación de microchips integrados, las salas blancas emplean filtros de aire HEPA que aíslan el polvo microscópico de la línea productiva."}], "collocations": [{"hanzi": "一层灰尘", "en": "a layer of dust"}, {"hanzi": "擦掉灰尘", "en": "wipe away the dust"}, {"hanzi": "积满灰尘", "en": "covered with accumulated dust"}, {"hanzi": "灰尘弥漫", "en": "dust floating everywhere in the air"}, {"hanzi": "吸入灰尘", "en": "inhale airborne dust"}, {"hanzi": "空气中的灰尘", "en": "dust in the ambient air"}], "idioms": [{"hanzi": "尘埃落定", "pinyin": "chén āi luò dìng", "meaning_en": "the dust settles; things reach a definitive conclusion"}, {"hanzi": "出类拔萃", "pinyin": "chū lèi bá cuì", "meaning_en": "stand out far above one's fellows; peerless excellence"}, {"hanzi": "看破红尘", "pinyin": "kàn pò hóng chén", "meaning_en": "see through the dusty world; renounce worldly vanities"}, {"hanzi": "一尘不染", "pinyin": "yì chén bù rǎn", "meaning_en": "not stained by a single speck of dust; spotless and morally pure"}], "character_decomposition": [{"character": "灰", "pinyin": "huī", "meaning_en": "ash; dust; gray; lime", "meaning_es": "ceniza; polvo; gris; cal", "radical": "火", "radical_meaning_en": "fire", "meaning_component": "火 (fire combusting organic matter)", "sound_component": "𠂇 (hand handling ashes)", "stroke_count": "6", "composition_type": "半包围结构", "etymology_and_mnemonic": "Ancient ideogram depicting a hand (𠂇) gathering cold embers and powdery remnants left by a fire (火).", "visual_mnemonic_story_en": "A careful hand reaches into the firepit (火) to scoop up cold powdery gray ash (灰).", "visual_mnemonic_story_es": "Una mano retira las ascuas apagadas del fuego (火) recogiendo el fino polvo ceniciento (灰).", "tone_mnemonic_anchor": "55", "cangjie": "KF", "traditional": "灰"}, {"character": "尘", "pinyin": "chén", "meaning_en": "dust; earth; secular world", "meaning_es": "polvo; tierra; mundo terrenal", "radical": "小", "radical_meaning_en": "small / tiny", "meaning_component": "小 (minute particles)", "sound_component": "土 (soil / earth)", "stroke_count": "6", "composition_type": "上下结构", "etymology_and_mnemonic": "Simplified from traditional 塵; ideogrammic compound of small (小) atop soil (土), representing minuscule earth particles.", "visual_mnemonic_story_en": "Soil (土) ground down into tiny microscopic specks (小) that float gently through the sunlight.", "visual_mnemonic_story_es": "Tierra (土) desmenuzada en diminutas motas (小) que flotan en el aire formando polvo.", "tone_mnemonic_anchor": "35", "cangjie": "FG", "traditional": "塵"}], "extended_reading_passages": [{"id": "#1", "hanzi": "午后一缕金黄的阳光斜斜穿透木窗，能清晰看见无数细小的灰尘在光柱中上下起伏、静静起舞。时光仿佛在此刻放慢了脚步，让人在万籁俱寂中感受到一种难以言喻的安详与生命细微的美好。", "pinyin": "Wǔhòu yì lǚ jīnhuáng de yángguāng xiéxié chuāntòu mùchuāng, néng qīngxī kànjiàn wúshù xìxiǎo de huīchén zài guāngzhù zhōng shàngxià qǐfú, jìngjìng qǐwǔ. Shíguāng fǎngrú zài cǐkè fàngmàn le jiǎobù, ràng rén zài wànlài-jùjì zhōng gǎnshòu dào yì zhǒng nányǐ yányù de ānxiáng yǔ shēngmìng xìwēi de měihǎo.", "en": "Afternoon golden sunlight slanted through the wooden window, illuminating countless specks of dust dancing gently in the beam. Time seemed to slow, allowing one to feel unspoken serenity and the delicate beauty of existence in tranquil silence.", "es": "El sol poniente cruzaba el ventanuco de madera revelando motas de polvo que danzaban en el haz de luz. El tiempo parecía detenerse, regalando en el sosiego una paz honda y la belleza sutil de la vida."}, {"id": "#2", "hanzi": "大气细颗粒物与工业灰尘污染是现代城市环境治理的核心难点。环保监测网络利用激光散射遥感与微粒吸附技术，对建筑扬尘与工厂排放实施全天候实时监控，为守护蓝天白云提供了坚实的数字屏障。", "pinyin": "Dàqì xìkēlìwù yǔ gōngyè huīchén wūrǎn shì xiàndài chéngshì huánjìng zhìlǐ de héxīn nándiǎn. Huánbǎo jiāncè wǎngluò lìyòng jīguāng sǎnsè yáogǎn yǔ wēilì xīfù jìshù, duì jiànzhù yángchén yǔ gōngchǎng páifàng shíshī quántiānhòu shíshí jiānkòng, wèi shǒuhù lántiān-báiyún tígōng le jiānshí de shùzì píngzhàng.", "en": "Fine atmospheric particulates and industrial dust pollution pose core hurdles in urban environmental governance. Environmental sensor grids deploy laser scattering to monitor emissions 24/7, safeguarding clean skies.", "es": "El polvo en suspensión y las partículas industriales retan la gestión ambiental urbana. Redes de sensores láser monitorizan en tiempo real las obras y fábricas, levantando un escudo digital para preservar el aire limpio."}]}, {"meanings_summary": {"en": "bright; shining; resonant; clear; to shine; to reveal; to dawn", "es": "brillante; claro; luminoso; sonoro; encenderse; amanecer; exhibir"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Gazing outward from a high open pavilion (亠) reveals a clear and wonderfully bright (亮) morning horizon.", "composite_memory_hook_es": "Mirar al horizonte desde un pabellón elevado (亠) descubre una mañana diáfana y brillante (亮).", "cultural_and_cognitive_roots": "In classical aesthetics, '亮' unites ocular luminosity with moral clarity (as in Zhuge Liang's courtesy name 'Kongming' 孔明 / 亮), embodying transparency, nobility, and enlightenment.", "tone_sandhi_and_pitch_modulation": "Pronounced in the 4th tone with a decisive dropping pitch: 'liàng' (51). Vowel articulation is open, resonant, and crisp."}, "semantic_boundary_contrasts": {"core_nuance": "亮 describes the optical property of emitting or reflecting strong visible illumination or acoustic sonority.", "contrasts": [{"id": "1", "compared_word": "亮 vs. 暗", "pinyin": "àn", "analysis": "亮 indicates abundant illumination and visibility, whereas 暗 is its direct antonym, signifying darkness, dimness, or obscurity."}, {"id": "2", "compared_word": "亮 vs. 明", "pinyin": "míng", "analysis": "亮 emphasizes the immediate optical sensation of shining brightness (e.g. 屋里很亮), while 明 encompasses conceptual clarity, wisdom, and transparency (e.g. 明白, 聪明)."}, {"id": "3", "compared_word": "亮 vs. 晴", "pinyin": "qíng", "analysis": "亮 describes light intensity anywhere, while 晴 specifically describes weather without cloud or rain (e.g. 晴天)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "高", "pinyin": "gāo", "meaning_en": "high; tall", "distinction_note": "Has 口 in the lower portion instead of 冖 and 儿"}, {"character": "毫", "pinyin": "háo", "meaning_en": "fine hair; milli-", "distinction_note": "Has 毛 (hair) at the bottom instead of 儿"}, {"character": "亨", "pinyin": "hēng", "meaning_en": "prosperous; smooth", "distinction_note": "Middle and lower components differ from 亮"}, {"character": "景", "pinyin": "jǐng", "meaning_en": "view; scenery", "distinction_note": "Has 日 (sun) on top of 京 instead of 亠"}], "etymological_cognates": [{"character": "月亮", "pinyin": "yuè liang", "gloss_en": "the moon"}, {"character": "亮堂", "pinyin": "liàng tang", "gloss_en": "brightly lit; spacious and airy"}, {"character": "漂亮", "pinyin": "piào liang", "gloss_en": "pretty; beautiful"}, {"character": "光亮", "pinyin": "guāng liàng", "gloss_en": "bright light; luster"}]}, "id": "29", "hanzi": "亮", "pinyin": "liàng", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "bright; radiant; giving off or reflecting plentiful light", "definition_es": "brillante; luminoso; bien iluminado", "example_phrase": "屋里很亮 (the room is very bright)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to illuminate; to light up; to shine; to dawn (of morning)", "definition_es": "iluminar; encenderse; amanecer", "example_phrase": "天刚亮 (the sky just dawned)"}, {"sense_number": "3", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "loud, clear, and sonorous in vocal tone or pitch", "definition_es": "sonoro; claro y potente de voz", "example_phrase": "嗓门很亮 (a very resonant voice)"}], "example_sentences": [{"id": "#1", "hanzi": "经过母亲一整天的擦拭收拾，客厅的地板和每扇玻璃窗都被擦得锃亮发光。", "pinyin": "Jīngguò mǔqīn yì zhěng tiān de cāshì shōushi, kètīng de dìbǎn hé měi shàn bōliboli dōu bèi cā de zèngliàng fāguāng.", "en": "Through mother's full day of wiping and tidying, the living room floor and every window pane were polished brilliantly shiny.", "es": "Gracias a la jornada de limpieza de mi madre, el suelo del salón y cada cristal de las ventanas quedaron relucientes como espejos."}, {"id": "#2", "hanzi": "该新能源汽车搭载了全新一代矩阵式自适应激光大灯，夜间行车时能够智能照亮前方数百米道路并避免炫目。", "pinyin": "Gāi xīnnéngyuán qìchē dāzài le quánxīn yídài jùzhènshì zìshìyìng jīguāng dàdēng, yèjiān xíngchē shí nénggòu zhìnéng zhàoliàng qiánfāng shù bǎi mǐ dàolù bìng bìmiǎn xuànmù.", "en": "The new energy vehicle sports adaptive matrix laser headlights that smartly illuminate hundreds of meters ahead at night without dazzling others.", "es": "Este vehículo eléctrico incorpora faros matriciales láser inteligentes que iluminan cientos de metros de carretera nocturna sin deslumbrar a otros conductores."}], "collocations": [{"hanzi": "天亮", "en": "dawn; daybreak"}, {"hanzi": "明亮", "en": "bright; well-lit"}, {"hanzi": "眼前一亮", "en": "one's eyes light up / deeply impressed"}, {"hanzi": "照亮", "en": "illuminate; light up"}, {"hanzi": "响亮", "en": "loud and clear; resonant"}, {"hanzi": "发亮", "en": "shine; glisten"}], "idioms": [{"hanzi": "高风亮节", "pinyin": "gāo fēng liàng jié", "meaning_en": "noble character and integrity; high moral exemplary standards"}, {"hanzi": "打开天窗说亮话", "pinyin": "dǎ kāi tiān chuāng shuō liàng huà", "meaning_en": "open the skylight and speak frankly; speak plain truth"}, {"hanzi": "灯火辉煌", "pinyin": "dēng huǒ huī huáng", "meaning_en": "brilliantly illuminated with blazing lights"}, {"hanzi": "明察秋毫", "pinyin": "míng chá qiū háo", "meaning_en": "perceive the finest detail with piercing clarity"}], "character_decomposition": [{"character": "亮", "pinyin": "liàng", "meaning_en": "bright; clear; shine", "meaning_es": "brillante; luminoso; alumbrar", "radical": "亠", "radical_meaning_en": "lid / roof", "meaning_component": "亠 (high lookout tower)", "sound_component": "儿 (standing person)", "stroke_count": "9", "composition_type": "上中下结构", "etymology_and_mnemonic": "Ancient compound depicting a high elevated tower overlooking the horizon, catching the very first rays of morning light.", "visual_mnemonic_story_en": "Standing tall atop a high lookout tower (亠+儿) as the morning sun breaks, illuminating the world in bright light (亮).", "visual_mnemonic_story_es": "Erguido sobre una torre de vigía (亠+儿) al romper el alba, bañando el mundo con un resplandor brillante (亮).", "tone_mnemonic_anchor": "51", "cangjie": "YBRN", "traditional": "亮"}], "extended_reading_passages": [{"id": "#1", "hanzi": "无论走多远，故乡窗口那一抹温暖的亮光，始终是照亮游子归途的灯塔。每当穿过漆黑的乡村小道，望见母亲在窗前翘首以盼的身影，一路的风霜与疲惫便全都在那片光晕中消散了。", "pinyin": "Wúlùn zǒu duō yuǎn, gùxiāng chuāngkǒu nà yì mǒ wēnnuǎn de liàngguāng, shǐzhōng shì zhàoliàng yóuzǐ guītú de dēngtǎ. Měidāng chuānguò qīhēi de xiāngcūn xiǎodào, wàngjiàn mǔqīn zài chuāngqián qiáoshǒu-yǐpàn de shēnyǐng, yílù de fēngshuāng yǔ píbèi biàn quán dōu zài nà piàn guāngyùn zhōng xiāosàn le.", "en": "No matter how far I wander, the warm glow in my hometown window remains a lighthouse illuminating the path home. Sighting mother waiting at the window through black lanes, all road fatigue vanishes in that halo.", "es": "Por lejos que viaje, el cálido resplandor en la ventana de mi aldea natal es un faro que guía el regreso. Al divisar a mi madre aguardando tras el cristal, las fatigas del camino se desvanecen en su luz."}, {"id": "#2", "hanzi": "现代化城市照明设计正由传统的单一功能性照明向“绿色光环境”跃升。利用低能耗发光二极管与物联网智能调光矩阵，城市景观照明在夜间按需点亮，既展现了都市璀璨魅力，又实现了显著节能降碳。", "pinyin": "Xiàndàihuà chéngshì zhàomíng shèjì zhèng yóu chuántǒng de dānyī gōngnéngxìng zhàomíng xiàng \"lǜsè guāng huánjìng\" yuèshēng. Lìyòng dī nénghào fāguāng'èjíguǎn yǔ wùliánwǎng zhìnéng tiáoguāng jùzhèn, chéngshì jǐngguān zhàomíng zài yèjiān ànxū diǎnliàng, jì zhǎnxiàn le dūshì cuǐcàn mèilì, yòu shíxiàn le xiǎnzhù jiénéng jiàngtàn.", "en": "Urban lighting design has jumped from simple illumination to green optical environments. Smart IoT dimming matrices light up cityscapes on demand, showcasing modern beauty while curbing carbon emissions.", "es": "El diseño del alumbrado urbano evoluciona hacia una iluminación ecológica inteligente. Matrices LED controladas por sensores iluminan las avenidas según la demanda, aunando esplendor estético y ahorro energético."}]}, {"meanings_summary": {"en": "to smile; smile (gentle, unspoken facial expression)", "es": "sonreír; sonrisa; gesto de agrado suave"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A subtle, tiny movement (微) of curved lips like swaying bamboo (笑) produces a peaceful smile (微笑).", "composite_memory_hook_es": "Un sutil y leve movimiento (微) de labios que se curvan como bambú (笑) compone una dulce sonrisa (微笑).", "cultural_and_cognitive_roots": "In Chan (Zen) philosophy, the '拈花微笑' (holding a flower and subtly smiling) encapsulates transcendent enlightenment communicating supreme truth beyond spoken words, epitomizing inner peace.", "tone_sandhi_and_pitch_modulation": "Pronounced with a 55-51 pitch contour (1st tone high and level, followed by 4th tone dropping with pleasant clarity). Keep transitions smooth."}, "semantic_boundary_contrasts": {"core_nuance": "微笑 is specifically a silent, gentle, mild curving of the lips denoting benevolence and friendliness.", "contrasts": [{"id": "1", "compared_word": "微笑 vs. 大笑", "pinyin": "dàxiào", "analysis": "微笑 is silent, gentle, and composed without showing wide open mouth or sound, whereas 大笑 is hearty, audible, roaring laughter."}, {"id": "2", "compared_word": "微笑 vs. 冷笑", "pinyin": "lěngxiào", "analysis": "微笑 carries genuine warmth, friendliness, and benevolence, while 冷笑 conveys sneering sarcasm, disdain, or chilling mockery."}, {"id": "3", "compared_word": "微笑 vs. 苦笑", "pinyin": "kǔxiào", "analysis": "微笑 radiates pleasant contentment, whereas 苦笑 is a wry, helpless, or forced bitter smile in the face of misfortune."}]}, "traps_and_cognates": {"look_alikes": [{"character": "徽", "pinyin": "huī", "meaning_en": "badge; emblem; Anhui", "distinction_note": "Has 糸 (silk) in the middle instead of 几 in 微"}, {"character": "徵", "pinyin": "zhǐ / zhēng", "meaning_en": "summon; levy; musical note", "distinction_note": "Has 王 in the middle instead of 几"}, {"character": "哭", "pinyin": "kū", "meaning_en": "cry; weep", "distinction_note": "Direct semantic antonym of 笑; has two mouths 口 and 犬"}, {"character": "笔", "pinyin": "bǐ", "meaning_en": "pen; brush", "distinction_note": "Has 竹 on top and 毛 (hair) at bottom instead of 夭"}], "etymological_cognates": [{"character": "微妙", "pinyin": "wēi miào", "gloss_en": "delicate; subtle; nuanced"}, {"character": "微小", "pinyin": "wēi xiǎo", "gloss_en": "tiny; minuscule"}, {"character": "笑声", "pinyin": "xiào shēng", "gloss_en": "sound of laughter"}, {"character": "笑容", "pinyin": "xiào róng", "gloss_en": "smiling expression"}]}, "id": "30", "hanzi": "微笑", "pinyin": "wēi xiào", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to form a gentle smile without opening the mouth wide or making laughter sounds", "definition_es": "sonreír suavemente sin emitir carcajadas", "example_phrase": "向大家微笑 (smile at everyone)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a pleasant, friendly, or peaceful facial expression; smile", "definition_es": "sonrisa; expresión risueña", "example_phrase": "迷人的微笑 (charming smile)"}], "example_sentences": [{"id": "#1", "hanzi": "看到下班归来的儿女，坐在门槛上歇息的母亲脸上露出了慈祥而欣慰的微笑。", "pinyin": "Kàndào xiàbān guīlái de énnǚ, zuò zài ménkǎn shàng xiēxi de mǔqīn liǎnshàng lùchū le cíxiáng ér xīnwèi de wēixiào.", "en": "Seeing her children returning from work, a benevolent and gratified smile appeared on mother's face as she rested on the threshold.", "es": "Al ver regresar a sus hijos del trabajo, el rostro de la madre descansando en el umbral se iluminó con una sonrisa dulce y satisfecha."}, {"id": "#2", "hanzi": "在国际航空与高端酒店服务业中，真诚亲和的微笑是拉近与客户距离、提升品牌美誉度的核心软实力。", "pinyin": "Zài guójì hángkōng yǔ gāoduān jiǔdiàn fúwùyè zhōng, zhēnchéng qīnhé de wēixiào shì lājìn yǔ kèhù jùlí, tíshēng pǐnpái měiyùdù de héxīn ruǎnshílì.", "en": "In international aviation and luxury hospitality, a sincere, warm smile is a core soft skill bridging distance with guests and elevating brand goodwill.", "es": "En la aviación comercial y la hostelería de lujo, la sonrisa sincera constituye una habilidad esencial para fidelizar clientes y prestigiar la marca."}], "collocations": [{"hanzi": "露出微笑", "en": "reveal a smile"}, {"hanzi": "面带微笑", "en": "wear a smile on one's face"}, {"hanzi": "迷人的微笑", "en": "charming / captivating smile"}, {"hanzi": "淡淡的微笑", "en": "faint / gentle smile"}, {"hanzi": "微笑面对", "en": "face with a smile (adversity)"}, {"hanzi": "微笑服务", "en": "service with a smile"}], "idioms": [{"hanzi": "微不足道", "pinyin": "wēi bù zú dào", "meaning_en": "too insignificant or small to mention"}, {"hanzi": "眉开眼笑", "pinyin": "méi kāi yǎn xiào", "meaning_en": "brows spread and eyes laugh; beaming with joy"}, {"hanzi": "拈花微笑", "pinyin": "niān huā wēi xiào", "meaning_en": "hold a flower with a subtle smile (Zen enlightenment; unspoken mutual understanding)"}, {"hanzi": "喜笑颜开", "pinyin": "xǐ xiào yán kāi", "meaning_en": "face lit up with joyful smiles"}], "character_decomposition": [{"character": "微", "pinyin": "wēi", "meaning_en": "tiny; minute; subtle; slight", "meaning_es": "diminuto; sutil; leve; microscópico", "radical": "彳", "radical_meaning_en": "step / walk", "meaning_component": "彳 (delicate measured footsteps)", "sound_component": "山+一+儿+攵 (subtle motion of hand)", "stroke_count": "13", "composition_type": "左中右结构", "etymology_and_mnemonic": "Ideogrammic and phono-semantic compound where gentle footsteps (彳) and delicate tapping hands (攵) convey micro-subtlety.", "visual_mnemonic_story_en": "Taking gentle tiny steps (彳) while observing minute delicate details (微) without disturbing anyone.", "visual_mnemonic_story_es": "Pasos casi imperceptibles (彳) que avanzan con suma delicadeza prestando atención a lo sutil (微).", "tone_mnemonic_anchor": "55", "cangjie": "HOUBK", "traditional": "微"}, {"character": "笑", "pinyin": "xiào", "meaning_en": "smile; laugh; chuckle", "meaning_es": "sonreír; reír; carcajada", "radical": "竹", "radical_meaning_en": "bamboo", "meaning_component": "竹 (bamboo swaying softly in breeze)", "sound_component": "夭 (yāo, supple young person)", "stroke_count": "10", "composition_type": "上下结构", "etymology_and_mnemonic": "Ancient compound depicting bamboo shoots (竹) bowing gracefully and swaying in the breeze like smiling lips.", "visual_mnemonic_story_en": "Bamboo branches (竹) bowing and rustling merrily in the wind, resembling human lips curving into laughter.", "visual_mnemonic_story_es": "Tallos de bambú (竹) que se mecen con donaire en la brisa como labios humanos curvados en una sonrisa.", "tone_mnemonic_anchor": "51", "cangjie": "HHK", "traditional": "笑"}], "extended_reading_passages": [{"id": "#1", "hanzi": "微笑是人际交往中最动人的世界通用语言。面对生活中的挫折与磨难，一个从容恬淡的微笑不仅能给予自己直面逆境的勇气，更能如春风化雨般融化人与人之间的隔阂，传递出直抵人心的温暖。", "pinyin": "Wēixiào shì rénjì jiāowǎng zhōng zuì dòngrén de shìjiè tōngyòng yǔyán. Miànduì shēnghuó zhōng de cuòzhé yǔ mónàn, yí gè cóngróng tiándàn de wēixiào bùjǐn néng jǐyǔ zìjǐ zhímiàn nìjìng de yǒngqì, gèng néng rú chūnfēng-huàyǔ bān rónghuà rén yǔ rén zhījiān de géhé, chuándǐ chū zhídǐ-rénxīn de wēnnuǎn.", "en": "A smile is the most touching universal language in human communication. Facing trials, a composed smile offers courage to confront adversity and melts estrangement like spring rain, transmitting heart-touching warmth.", "es": "La sonrisa es el idioma universal más conmovedor del ser humano. Ante los reveses vitales, una sonrisa serena brinda entereza para encarar la adversidad y disuelve distancias con la calidez de la lluvia primaveral."}, {"id": "#2", "hanzi": "神经认知科学研究表明，主动微笑能够显著刺激大脑分泌内啡肽与多巴胺，从而有效降低机体压力荷尔蒙皮质醇水平。在企业管理中推广微笑沟通机制，对于缓解员工职场焦虑、构建高韧性协作团队具有积极的生理与心理调节价值。", "pinyin": "Shénjīng rènzhī kēxué yánjiū biǎomíng, zhǔdòng wēixiào nénggòu xiǎnzhù cìjī dànǎo fēnmì nèifēitài yǔ duōbā'àn, cóng'ér yǒuxiào jiàngdī jītǐ yālì hèměng pízìchún shuǐpíng. Zài qǐyè guǎnlǐ zhōng tuīguǎng wēixiào gōutōng jīzhì, duìyú huǎnjiě yuángōng zhíchǎng jiāolǜ, gòujiàn gāorènxìng xiézuò tuánduì jùyǒu jījí de shēnglǐ yǔ xīnlǐ tiáojié jiàzhí.", "en": "Neurocognitive research reveals that voluntary smiling stimulates endorphin and dopamine secretion, reducing cortisol levels. Promoting smiling communication in enterprise management eases workplace anxiety and builds resilient teams.", "es": "La neurociencia demuestra que sonreír estimula endorfinas y dopamina, reduciendo el cortisol. Fomentar la comunicación risueña en las empresas alivia el estrés laboral y forja equipos de trabajo cohesionados y resilientes."}]}, {"meanings_summary": {"en": "warm; genial; to make warm; warmth (physical and emotional)", "es": "cálido; abrigado; reconfortante; calidez; dar calor"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Soothing warm water (温) bathed in radiant sunshine (暖) brings physical and emotional warmth (温暖).", "composite_memory_hook_es": "Agua templada y apacible (温) iluminada por el sol radiante (暖) regala una calidez infinita (温暖).", "cultural_and_cognitive_roots": "In Confucian family ethics, '温暖' embodies the quintessential virtue of maternal compassion ('温良敦厚'), representing unconditional psychological safety and ancestral belonging against life's hardships.", "tone_sandhi_and_pitch_modulation": "Pronounced with a 55-214 pitch contour (1st tone high and level, followed by 3rd tone dipping smoothly). When followed by another syllable, 'nuǎn' dips without full rising."}, "semantic_boundary_contrasts": {"core_nuance": "温暖 encompasses both physical genial temperature and emotional solace, compassion, or familial love.", "contrasts": [{"id": "1", "compared_word": "温暖 vs. 暖和", "pinyin": "nuǎnhuo", "analysis": "温暖 is formal and covers both physiological warmth and emotional/psychological comfort (e.g. 温暖的怀抱, 感到温暖), whereas 暖和 is primarily oral and restricted to physical temperature (e.g. 屋里挺暖和)."}, {"id": "2", "compared_word": "温暖 vs. 热", "pinyin": "rè", "analysis": "温暖 describes pleasant, comfortable, moderate thermal warmth, while 热 denotes intense heat or high temperature, often uncomfortable (e.g. 天气太热)."}, {"id": "3", "compared_word": "温暖 vs. 温和", "pinyin": "wēnhé", "analysis": "温暖 highlights feeling warm and cared for, whereas 温和 describes mild temperament, non-extreme climate, or gentle medicinal properties (e.g. 性情温和, 气候温和)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "湿", "pinyin": "shī", "meaning_en": "wet; damp; moist", "distinction_note": "Has 显 on the right of 氵 instead of 昷"}, {"character": "援", "pinyin": "yuán", "meaning_en": "assist; aid", "distinction_note": "Has 扌 (hand) on the left instead of 日"}, {"character": "缓", "pinyin": "huǎn", "meaning_en": "slow; postpone; relax", "distinction_note": "Has 纟 (silk) on the left instead of 日"}, {"character": "爱", "pinyin": "ài", "meaning_en": "love; affection", "distinction_note": "Resembles the right component 爰 with 心 in ancient forms"}], "etymological_cognates": [{"character": "温度", "pinyin": "wēn dù", "gloss_en": "temperature"}, {"character": "温和", "pinyin": "wēn hé", "gloss_en": "gentle; mild; temperate"}, {"character": "暖和", "pinyin": "nuǎn huo", "gloss_en": "warm; comfortably warm"}, {"character": "取暖", "pinyin": "qǔ nuǎn", "gloss_en": "warm oneself (by a fire or heater)"}]}, "id": "31", "hanzi": "温暖", "pinyin": "wēn nuǎn", "level": "HSK 5", "part_of_speech": "Adjective", "senses": [{"sense_number": "1", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "pleasantly and comfortably warm in temperature", "definition_es": "cálido; templado al tacto o clima", "example_phrase": "温暖的阳光 (warm sunshine)"}, {"sense_number": "2", "part_of_speech": "Adjective", "register": "Standard", "definition_en": "emotionally heartwarming, comforting, and kind", "definition_es": "reconfortante; cariñoso; acogedor", "example_phrase": "温暖的话语 (heartwarming words)"}, {"sense_number": "3", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to warm up; to bring warmth and comfort to someone", "definition_es": "calentar; dar calidez y consuelo", "example_phrase": "温暖了大家的心 (warmed everyone's hearts)"}], "example_sentences": [{"id": "#1", "hanzi": "钻进被阳光充分晒透的棉被里，周身被融融的暖意包裹，那一刻感受到了家最温暖的滋味。", "pinyin": "Zuānjìn bèi yángguāng chōngfèn shàitòu de miánbèi lǐ, zhōushēn bèi róngróng de nuǎnyì bǎoguǒ, nà yí kè gǎnshòu dào le jiā zuì wēnnuǎn de zīwèi.", "en": "Slipping under the cotton quilt thoroughly sunned by daylight, wrapped in gentle warmth, in that moment I felt the warmest taste of home.", "es": "Al cobijarme bajo el edredón impregnado de sol, envuelto en una suave tibieza, saboreé la calidez más entrañable del hogar."}, {"id": "#2", "hanzi": "在抗震救灾第一线，社会各界捐赠的防寒物资与志愿者的无私奉献，深深温暖了受灾群众的心。", "pinyin": "Zài kàngzhèn-jiùzāi dì-yī xiàn, shèhuì gèjiè juānzèng de fánghán wùzī yǔ zhìyuànzhě de wúsī fèngxiàn, shēnshēn wēnnuǎn le shòuzāi qúnzhòng de xīn.", "en": "On the frontline of quake relief, winter relief supplies donated by society and volunteers' selfless dedication deeply warmed disaster victims' hearts.", "es": "En primera línea de auxilio ante el sismo, los víveres donados por la sociedad y la abnegación voluntaria confortaron con calidez a los damnificados."}], "collocations": [{"hanzi": "温暖的阳光", "en": "warm sunshine"}, {"hanzi": "感到温暖", "en": "feel warm / comforted"}, {"hanzi": "温暖人心", "en": "warm people's hearts"}, {"hanzi": "温暖的怀抱", "en": "warm embrace"}, {"hanzi": "送去温暖", "en": "deliver warmth / care"}, {"hanzi": "春风送暖", "en": "spring breeze brings warmth"}], "idioms": [{"hanzi": "风和日暖", "pinyin": "fēng hé rì nuǎn", "meaning_en": "gentle breeze and warm sun; genial, pleasant weather"}, {"hanzi": "春暖花开", "pinyin": "chūn nuǎn huā kāi", "meaning_en": "spring warmth arrives and flowers bloom; bright new beginnings"}, {"hanzi": "饱食暖衣", "pinyin": "bǎo shí nuǎn yī", "meaning_en": "adequately fed and warmly clad; living in comfort"}, {"hanzi": "嘘寒问暖", "pinyin": "xū hán wèn nuǎn", "meaning_en": "inquire solicitously after someone's welfare and comfort"}], "character_decomposition": [{"character": "温", "pinyin": "wēn", "meaning_en": "warm; mild; lukewarm", "meaning_es": "tibio; templado; suave; apacible", "radical": "氵", "radical_meaning_en": "water (three drops)", "meaning_component": "氵 (water heated to genial temperature)", "sound_component": "昷 (wēn, vessel on fire)", "stroke_count": "12", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where water radical 氵 combines with 昷 (food vessel warmed over heat), signifying gentle warmth.", "visual_mnemonic_story_en": "Clear spring water (氵) heated gently over an earthenware basin (昷) to a soothing, comfortable warmth.", "visual_mnemonic_story_es": "Agua de manantial (氵) calentada suavemente en una vasija (昷) hasta alcanzar una temperatura reconfortante.", "tone_mnemonic_anchor": "55", "cangjie": "EABT", "traditional": "溫"}, {"character": "暖", "pinyin": "nuǎn", "meaning_en": "warm; genial; toast", "meaning_es": "cálido; calentar; abrigado", "radical": "日", "radical_meaning_en": "sun / day", "meaning_component": "日 (radiant sunshine)", "sound_component": "爰 (yuán, helping hand / phonetic)", "stroke_count": "13", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound combining sun radical 日 with phonetic 爰, conveying the comforting thermal embrace of sunlight.", "visual_mnemonic_story_en": "The bright midday sun (日) extending warm rays like gentle helping hands (爰) to dispel winter chill.", "visual_mnemonic_story_es": "El sol radiante (日) que tiende sus rayos como manos amigas (爰) para ahuyentar el frío y dar cobijo.", "tone_mnemonic_anchor": "214", "cangjie": "ABME", "traditional": "暖"}], "extended_reading_passages": [{"id": "#1", "hanzi": "家是风浪中最温暖的港湾。无论在外面经历了多少坎坷与委屈，只要推开家门，看到母亲端上那一碗热气腾腾的面条，耳边响起轻声的叮咛，所有的疲惫都会瞬间被这股融融的温暖彻底化解。", "pinyin": "Jiā shì fēnglàng zhōng zuì wēnnuǎn de gǎngwān. Wúlùn zài wàimiàn jīnglì le duōshǎo kǎnkě yǔ wěiqu, zhǐyào tuīkāi jiāmén, kàndào mǔqīn duān shàng nà yì wǎn rèqì-téngténg de miàntiáo, ěrbiān xiǎngqǐ qīngshēng de dīngníng, suǒyǒu de píbèi dōu huì shùnjiān bèi zhè gǔ róngróng de wēnnuǎn chèdǐ huàjiě.", "en": "Home is the warmest haven amid life's storms. No matter what trials or grievances occur outside, opening the door to steaming noodles from mother and gentle words, fatigue dissolves completely in this pervasive warmth.", "es": "El hogar es el puerto más cálido ante las tempestades. Pese a las adversidades del mundo, cruzar el umbral y recibir el tazón humeante de fideos de madre con dulces palabras disuelve toda pena en su tibieza."}, {"id": "#2", "hanzi": "现代化城市基层社区建设正注重提升公共服务的“温度”。从设立老年助餐点到建设全天候户外劳动者爱心驿站，细致入微的民生举措让城市不仅具备钢筋水泥的现代高度，更洋溢着人本主义的社会温暖。", "pinyin": "Xiàndàihuà chéngshì jīcéng shèqū jiànshè zhèng zhùzhòng tíshēng gōnggòng fúwù de \"wēndù\". Cóng shèlì lǎonián zhùcāndiǎn dào jiànshè quántiānhòu hùwài láodòngzhě àixīn yìzhàn, xìzhì-rùwēi de mínshēng jǔcuò ràng chéngshì bùjǐn jùbèi gāngjīn-shuǐní de xiàndài gāodù, gèng yángyì zhe rénběnzhǔyì de shèhuì wēnnuǎn.", "en": "Modern municipal grassroots community building emphasizes improving public service warmth. From senior dining centers to 24/7 rest hubs for workers, attentive measures endow cities with humanistic social warmth.", "es": "Las comunidades vecinales urbanas priorizan hoy la calidez del servicio público. Comedores para ancianos y áreas de descanso para obreros dotan a las urbes modernas de un hondo sentido de solidaridad humana."}]}, {"meanings_summary": {"en": "immediately; at once; right away; promptly without delay", "es": "inmediatamente; enseguida; al instante; en el acto; de inmediato"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Standing upright in readiness (立) at that precise notched moment (刻) means springing into action immediately (立刻).", "composite_memory_hook_es": "Ponerse de pie al instante (立) en el segundo marcado por el reloj (刻) significa actuar de inmediato (立刻).", "cultural_and_cognitive_roots": "In ancient Chinese chronometry, time on sundials and water clocks was measured in 'kè' (刻 = 1/100 of a day, roughly 14.4 minutes); combined with 'lì' (stand upright), it conveyed instant kinetic readiness.", "tone_sandhi_and_pitch_modulation": "Pronounced with paired 4th tones: 'lì kè' (51-51). Articulate both syllables with decisive, clipped staccato without softening the second tone."}, "semantic_boundary_contrasts": {"core_nuance": "立刻 emphasizes zero elapsed time or absence of hesitation between stimulus and response.", "contrasts": [{"id": "1", "compared_word": "立刻 vs. 马上", "pinyin": "mǎshàng", "analysis": "立刻 denotes zero time delay or instant reaction (e.g. 立刻停止), whereas 马上 can allow a brief practical buffer before execution (e.g. 我马上就来, often implies within a few minutes)."}, {"id": "2", "compared_word": "立刻 vs. 顿时", "pinyin": "dùnshí", "analysis": "立刻 is an adverb modifying an intentional action or command, while 顿时 describes a sudden change in atmosphere, mood, or situation occurring in the past (e.g. 掌声顿时响了起来)."}, {"id": "3", "compared_word": "立刻 vs. 逐渐", "pinyin": "zhújiàn", "analysis": "立刻 is instantaneous action, which is the exact antonym of 逐渐 (gradual, step-by-step progress over time)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "该", "pinyin": "gāi", "meaning_en": "should; ought to", "distinction_note": "Has 讠 (speech) on the left instead of 亥 with 刂"}, {"character": "咳", "pinyin": "hāi / ké", "meaning_en": "cough", "distinction_note": "Has 口 (mouth) on the left of 亥"}, {"character": "孩", "pinyin": "hái", "meaning_en": "child; kid", "distinction_note": "Has 子 (child) on the left of 亥"}, {"character": "位", "pinyin": "wèi", "meaning_en": "place; position", "distinction_note": "Has 亻 (person) on the left of 立"}], "etymological_cognates": [{"character": "立即", "pinyin": "lì jí", "gloss_en": "immediately; instantly"}, {"character": "时刻", "pinyin": "shí kè", "gloss_en": "moment; constantly"}, {"character": "深刻", "pinyin": "shēn kè", "gloss_en": "profound; deep"}, {"character": "立场", "pinyin": "lì chǎng", "gloss_en": "stance; position"}]}, "id": "32", "hanzi": "立刻", "pinyin": "lì kè", "level": "HSK 5", "part_of_speech": "Adverb", "senses": [{"sense_number": "1", "part_of_speech": "Adverb", "register": "Standard", "definition_en": "immediately; without a moment's hesitation or delay", "definition_es": "inmediatamente; de inmediato; al instante", "example_phrase": "立刻出发 (depart at once)"}], "example_sentences": [{"id": "#1", "hanzi": "刚进家门闻到厨房里飘出的饭菜香味，长途奔波的饥饿感立刻涌了上来。", "pinyin": "Gāng jìn jiāmén wéndào chúfáng lǐ piāochū de fàncài xiāngwèi, chángtú bēnbō de jī'ègǎn lìkè yǒng le shànglái.", "en": "Stepping into the house and smelling meal aromas wafting from the kitchen, hunger from long-distance travel immediately surged up.", "es": "Al cruzar la puerta y aspirar el aroma que salía de la cocina, el hambre del largo viaje emergió de inmediato."}, {"id": "#2", "hanzi": "监测系统一旦发现核心服务器遭遇异常流量攻击，应急防护脚本将立刻自动阻断风险端口。", "pinyin": "Jiāncè xìtǒng yídàn fāxiàn héxīn fúwùqì zāoyù yìcháng liúliàng gōngjī, yìngjí fánghù jiǎoběn jiāng lìkè zìdòng zǔduàn fēngxiǎn duānkǒu.", "en": "The moment the monitoring system detects anomalous traffic attacks on core servers, emergency defense scripts will immediately block risky ports automatically.", "es": "En cuanto el sistema detecta un tráfico anómalo sobre los servidores centrales, el protocolo de defensa bloquea al instante los puertos en riesgo."}], "collocations": [{"hanzi": "立刻执行", "en": "execute immediately"}, {"hanzi": "立刻停止", "en": "stop at once"}, {"hanzi": "立刻动身", "en": "set off immediately"}, {"hanzi": "立刻回复", "en": "reply promptly"}, {"hanzi": "立刻生效", "en": "take effect immediately"}, {"hanzi": "立刻明白", "en": "understand at once"}], "idioms": [{"hanzi": "立竿见影", "pinyin": "lì gān jiàn yǐng", "meaning_en": "erect a pole and see its shadow immediately; produce prompt, tangible results"}, {"hanzi": "风驰电掣", "pinyin": "fēng chí diàn chè", "meaning_en": "swift as the wind and quick as lightning; rapid motion"}, {"hanzi": "刻不容缓", "pinyin": "kè bù róng huǎn", "meaning_en": "brook not a moment's delay; extremely urgent"}, {"hanzi": "兵贵神速", "pinyin": "bīng guì shén sù", "meaning_en": "speed is precious in warfare; act with lightning swiftness"}], "character_decomposition": [{"character": "立", "pinyin": "lì", "meaning_en": "stand; erect; immediate", "meaning_es": "estar de pie; erigir; inmediato", "radical": "立", "radical_meaning_en": "stand / upright", "meaning_component": "立 (person standing firmly erect on earth)", "sound_component": "", "stroke_count": "5", "composition_type": "独体结构", "etymology_and_mnemonic": "Ancient oracle script depicting a human figure standing upright with feet planted firmly on ground line, denoting instant readiness.", "visual_mnemonic_story_en": "A person standing upright and poised on two feet (立), prepared to spring into prompt action.", "visual_mnemonic_story_es": "Una persona erguida y firme sobre el suelo (立), preparada para actuar en el acto sin vacilar.", "tone_mnemonic_anchor": "51", "cangjie": "YT", "traditional": "立"}, {"character": "刻", "pinyin": "kè", "meaning_en": "engrave; carve; moment", "meaning_es": "tallar; grabar; cuarto de hora; instante", "radical": "刂", "radical_meaning_en": "knife / blade", "meaning_component": "刂 (sharp cutting knife)", "sound_component": "亥 (hài, boar / phonetic)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where knife radical 刂 denotes carving notches on a water clock (clepsydra) to measure fleeting moments.", "visual_mnemonic_story_en": "A sharp knife (刂) notching marks into a water clock to divide time into precise fleeting moments (刻).", "visual_mnemonic_story_es": "Una cuchilla (刂) grabando muescas en el reloj de agua para marcar instantes precisos y veloces (刻).", "tone_mnemonic_anchor": "51", "cangjie": "YOLN", "traditional": "刻"}], "extended_reading_passages": [{"id": "#1", "hanzi": "离家千里的游子推开久违的门扉，迎面撞见母亲含泪的眼眸，心中积攒的所有委屈与疲惫立刻烟消云散。那一刻，无需千言万语，紧紧的拥抱便足以将漫长岁月里的思念彻底填满。", "pinyin": "Líjiā qiānlǐ de yóuzǐ tuīkāi jiǔwéi de ménfēi, yíngmiàn zhuàngjiàn mǔqīn hánlèi de yǎnmóu, xīnzhōng jīzǎn de suǒyǒu wěiqu yǔ píbèi lìkè yānxiāo-yúnsàn. Nà yí kè, wúxū qiānyán-wànyǔ, jǐnjǐn de yōngbào biàn zúyǐ jiāng màncháng suìyuè lǐ de sīniàn chèdǐ tiánmǎn.", "en": "Pushing open the long-absent door and meeting mother's tearful eyes, grievances and exhaustion accumulated in my heart vanished immediately. In that moment, a tight embrace filled the yearning of long years without words.", "es": "Al empujar la puerta familiar y hallar la mirada emocionada de madre, los pesares del viaje se desvanecieron de inmediato. No hacían falta palabras: un abrazo apretado colmó la añoranza de años de distancia."}, {"id": "#2", "hanzi": "现代应急管理机制强调“黄金响应时间”。突发灾害发生后，综合指挥中心必须立刻激活跨部门联勤联动预案，在数分钟内统筹调度救援梯队与医疗资源，最大限度保障人民群众生命财产安全。", "pinyin": "Xiàndài yìngjí guǎnlǐ jīzhì qiángdiào \"huángjīn xiǎngyìng shíjiān\". Tūfā zāihài fāshēng hòu, zōnghé zhǐhuī zhōngxīn bìxū lìkè jīhuó kuàbùmén liánqín liándòng yù'àn, zài shù fēnzhōng nèi tǒngchóu diàodù jiùyuán tīduì yǔ yīliáo zīyuán, zuìdà xiàndù bǎozhàng rénmín qúnzhòng shēngmìng cáichǎn ānquán.", "en": "Modern emergency management emphasizes the 'golden response window.' Following sudden disasters, central command must immediately activate cross-department protocols, dispatching rescue and medical teams within minutes.", "es": "La gestión de emergencias exige una respuesta inmediata. Ante catástrofes repentinas, el mando central activa al instante los protocolos de auxilio para desplegar equipos médicos y salvaguardar vidas humanas con celeridad."}]}, {"meanings_summary": {"en": "to throw oneself on; to pounce on; to rush forward; to flap; to extinguish (fire)", "es": "abalanzarse; arrojarse sobre; lanzarse; abofetear; apagar (fuego)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Reaching out both hands (扌) with a sudden thrust (卜) allows you to throw yourself onto (扑) the bed.", "composite_memory_hook_es": "Extender las manos (扌) con impulso decidido (卜) para arrojarse de lleno (扑) sobre el lecho.", "cultural_and_cognitive_roots": "In Chinese vernacular imagery, '扑' captures unfiltered kinetic emotion: a joyful child leaping into a mother's arms, or an exhausted wanderer collapsing headlong into a fresh quilt.", "tone_sandhi_and_pitch_modulation": "Pronounced in the 1st tone with a sustained high pitch: 'pū' (55). Distinct from 4th tone 'pù' (as in 铺铺)."}, "semantic_boundary_contrasts": {"core_nuance": "扑 emphasizes a sudden, forceful, whole-body forward lunging movement toward an object.", "contrasts": [{"id": "1", "compared_word": "扑 vs. 跳", "pinyin": "tiào", "analysis": "扑 emphasizes forward bodily lunging or throwing oneself flat onto a surface (e.g. 扑在床上), whereas 跳 emphasizes vertical leaping, bounding, or hopping (e.g. 跳高, 跳绳)."}, {"id": "2", "compared_word": "扑 vs. 冲", "pinyin": "chōng", "analysis": "扑 implies landing directly onto a target to grab or cover it, while 冲 emphasizes high linear velocity charging through space (e.g. 冲向终点)."}, {"id": "3", "compared_word": "扑 vs. 倒", "pinyin": "dǎo", "analysis": "扑 is an intentional kinetic lunging action, whereas 倒 indicates tumbling, falling down, or collapsing due to loss of balance (e.g. 摔倒)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "补", "pinyin": "bǔ", "meaning_en": "repair; mend; supplement", "distinction_note": "Has 衤 (clothing) on left with 卜 on right"}, {"character": "朴", "pinyin": "pǔ", "meaning_en": "simple; plain; surname", "distinction_note": "Has 木 (wood) on left with 卜 on right"}, {"character": "挂", "pinyin": "guà", "meaning_en": "hang; suspend", "distinction_note": "Has 扌 with 圭 instead of 卜"}, {"character": "打", "pinyin": "dǎ", "meaning_en": "strike; hit", "distinction_note": "Has 丁 on the right instead of 卜"}], "etymological_cognates": [{"character": "扑灭", "pinyin": "pū miè", "gloss_en": "extinguish; put out"}, {"character": "扑击", "pinyin": "pū jī", "gloss_en": "pounce and strike"}, {"character": "打扑克", "pinyin": "dǎ pū kè", "gloss_en": "play poker cards (loanword)"}, {"character": "扑腾", "pinyin": "pū teng", "gloss_en": "flap wings; struggle"}]}, "id": "33", "hanzi": "扑", "pinyin": "pū", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to throw one's whole body forward onto something (a bed, person, prey)", "definition_es": "arrojarse sobre; abalanzarse hacia delante", "example_phrase": "扑向母亲的怀抱 (throw oneself into mother's embrace)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to waft or blow directly into one's face (aroma, heat, wind)", "definition_es": "dar de lleno en el rostro (olor, calor, brisa)", "example_phrase": "扑面而来 (blow right into one's face)"}, {"sense_number": "3", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to stamp out or extinguish (a blaze or flames)", "definition_es": "sofocar o apagar (las llamas)", "example_phrase": "扑灭大火 (extinguish a fire)"}], "example_sentences": [{"id": "#1", "hanzi": "闻到被子上浓浓的阳光味道，疲惫的孩子迫不及待地猛扑到床上，把脸深深埋进柔软的棉被里。", "pinyin": "Wéndào bèizi shàng nóngnóng de yángguāng wèidao, píbèi de háizi pòbùjídài de měng pū dào chuáng shàng, bǎ liǎn shēndìng máijìn róuruǎn de miánbèi lǐ.", "en": "Smelling the rich scent of sunshine on the quilt, the exhausted child impatiently threw himself onto the bed, burying his face in soft cotton.", "es": "Al oler la densa fragancia a sol en el edredón, el niño rendido se abalanzó ansioso sobre la cama enterrando la cara en el algodón."}, {"id": "#2", "hanzi": "森林消防特勤支队顶着滚滚浓烟与灼人热浪冲上火场，经过数小时连续奋战终于扑灭了多处蔓延的山火。", "pinyin": "Sēnlín xiāofáng tèqín zhīduì dǐng zhe gǔngǔn nóngyān yǔ zhuórén rèlàng chōng shàng huǒchǎng, jīngguò shù xiǎoshí liánxù fènzhàn zhōngyú pūmiè le duō chù mànyán de shānhuǒ.", "en": "Braving billowing smoke and scorching heat waves, forest firefighting detachments charged the fireground, extinguishing several spreading wildfires after hours of combat.", "es": "Afrontando el humo y el calor sofocante, los bomberos forestales cargaron contra el fuego sofocando tras varias horas las llamas en la sierra."}], "collocations": [{"hanzi": "扑面而来", "en": "blow / waft right into one's face"}, {"hanzi": "猛扑", "en": "pounce violently; throw oneself forward"}, {"hanzi": "扑灭", "en": "extinguish; put out (fire)"}, {"hanzi": "扑空", "en": "fail to find someone; miss an appointment"}, {"hanzi": "扑通", "en": "splash; thud (onomatopoeia)"}, {"hanzi": "扑向", "en": "rush toward; throw oneself into"}], "idioms": [{"hanzi": "飞蛾扑火", "pinyin": "fēi é pū huǒ", "meaning_en": "moths fly into the flame; rush to one's own destruction"}, {"hanzi": "饿虎扑食", "pinyin": "è hǔ pū shí", "meaning_en": "hungry tiger pouncing on its prey; pounce with ferocious eagerness"}, {"hanzi": "扑朔迷离", "pinyin": "pū shuò mí lí", "meaning_en": "complicated and bewildering; confusingly intricate"}, {"hanzi": "前赴后继", "pinyin": "qián fù hòu jì", "meaning_en": "advance wave upon wave as those ahead fall"}], "character_decomposition": [{"character": "扑", "pinyin": "pū", "meaning_en": "throw oneself on; pounce; tap", "meaning_es": "arrojarse; abalanzarse; golpear", "radical": "扌", "radical_meaning_en": "hand", "meaning_component": "扌 (hands reaching out vigorously)", "sound_component": "卜 (bǔ, divining crack / phonetic)", "stroke_count": "5", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound combining hand radical 扌 with phonetic 卜; simplified from traditional 撲.", "visual_mnemonic_story_en": "Hands outstretched (扌) lunging forward with explosive energy like a sudden crack (卜) to clasp something.", "visual_mnemonic_story_es": "Brazos abiertos (扌) que se lanzan con fuerza súbita (卜) hacia delante para arrojarse sobre algo.", "tone_mnemonic_anchor": "55", "cangjie": "QY", "traditional": "撲"}], "extended_reading_passages": [{"id": "#1", "hanzi": "无论年纪多大，只要回到母亲身边，我们便依然是个依恋温暖的孩子。推开房门，闻着被褥间扑鼻而来的阳光气息，整个人猛地扑了上去，所有的疲惫与烦恼在这一瞬间被彻底治愈。", "pinyin": "Wúlùn niánjì duō dà, zhǐyào huídào mǔqīn shēnbiān, wǒmen biàn yīrán shì gè yīliàn wēnnuǎn de háizi. Tuīkāi fángmén, wén zhe bèirù jiān pūbí ér lái de yángguāng qìxī, zhěnggè rén měng de pū le shàngqù, suǒyǒu de píbèi yǔ fánnǎo zài zhè yí shùnjiān bèi chèdǐ zhìyù.", "en": "No matter our age, returning to mother's side we remain children craving warmth. Pushing open the room and breathing sunlit fragrance wafting from bedding, collapsing onto it heals all fatigue and trouble.", "es": "Sin importar los años, junto a la madre seguimos siendo niños en busca de cobijo. Al abrir el cuarto y oler la fragancia a sol de las mantas, arrojarse sobre ellas sana toda congoja al instante."}, {"id": "#2", "hanzi": "生态环保应急部门建立了重点林区无人机巡查与红外热成像预警网络。一旦发现早期火点，专业防灭火直升机便能在半小时内扑向险情核心区域实施精准洒水，将森林火灾扼杀在萌芽状态。", "pinyin": "Shēngtài huánbǎo yìngjí bùmén jiànlì le zhòngdiǎn línqū wúrénjī xúnchá yǔ hóngwài rèchéngxiàng yùjǐng wǎngluò. Yídàn fāxiàn zǎoqī huǒdiǎn, zhuānyè fáng-mièhuǒ zhíshēngjī biàn néng zài bàn xiǎoshí nèi pū xiàng xiǎnqíng héxīn qūyù shíshī jīngzhǔn sǎshuǐ, jiāng sēnlín huǒzāi èshā zài méngyá zhuàngtài.", "en": "Environmental agencies deploy drone patrols and infrared early warning in forests. Sighting early fire spots, specialized helicopters rush to disaster centers within half an hour, extinguishing blazes in the bud.", "es": "Los equipos forestales patrullan con drones y cámaras térmicas. Ante cualquier foco de humo, los helicópteros de extinción se lanzan a la zona crítica descargando agua para sofocar el fuego en su origen."}]}, {"meanings_summary": {"en": "bedroom; sleeping chamber; private bedchamber", "es": "dormitorio; alcoba; recámara; habitación para dormir"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Reclining your body (卧) inside a protected sheltered chamber (室) defines a restful bedroom (卧室).", "composite_memory_hook_es": "Reclinar el cuerpo a descansar (卧) dentro de una estancia protegida (室) es la esencia del dormitorio (卧室).", "cultural_and_cognitive_roots": "In ancient architectural cosmology, the '室' was the most sacred, private chamber located behind the public hall ('堂'), reserved for intimate marital life, ancestral sleep, and personal tranquility.", "tone_sandhi_and_pitch_modulation": "Pronounced with paired 4th tones: 'wò shì' (51-51). Articulate both syllables with steady, crisp falling pitch."}, "semantic_boundary_contrasts": {"core_nuance": "卧室 is strictly designated for sleeping, bed rest, and private nightly repose.", "contrasts": [{"id": "1", "compared_word": "卧室 vs. 客厅", "pinyin": "kètīng", "analysis": "卧室 is a private interior chamber designated for sleep and rest, whereas 客厅 is the public communal hall for receiving guests, dining, and family entertainment."}, {"id": "2", "compared_word": "卧室 vs. 书房", "pinyin": "shūfáng", "analysis": "卧室 is furnished with a bed for nocturnal rest, while 书房 is dedicated to reading, writing, and intellectual study."}, {"id": "3", "compared_word": "卧室 vs. 屋子", "pinyin": "wūzi", "analysis": "卧室 denotes the specific functional room for sleeping, while 屋子 can colloquially refer to any room or an entire domestic house."}]}, "traps_and_cognates": {"look_alikes": [{"character": "屋", "pinyin": "wū", "meaning_en": "house; room", "distinction_note": "Has 尸 on top of 至 instead of 宀"}, {"character": "臣", "pinyin": "chén", "meaning_en": "minister; official", "distinction_note": "Left component of 卧 without the right 卜"}, {"character": "到", "pinyin": "dào", "meaning_en": "arrive; reach", "distinction_note": "Has 至 on the left with 刂 (knife) on the right"}, {"character": "宝", "pinyin": "bǎo", "meaning_en": "treasure; precious", "distinction_note": "Has 宀 on top with 玉 (jade) below instead of 至"}], "etymological_cognates": [{"character": "房间", "pinyin": "fáng jiān", "gloss_en": "room; chamber"}, {"character": "卧铺", "pinyin": "wò pù", "gloss_en": "sleeping berth (on trains)"}, {"character": "室内", "pinyin": "shì nèi", "gloss_en": "indoor; interior"}, {"character": "温室", "pinyin": "wēn shì", "gloss_en": "greenhouse; hothouse"}]}, "id": "34", "hanzi": "卧室", "pinyin": "wò shì", "level": "HSK 5", "part_of_speech": "Noun", "senses": [{"sense_number": "1", "part_of_speech": "Noun", "register": "Standard", "definition_en": "a private room in a house or apartment used specifically for sleeping and resting", "definition_es": "dormitorio; estancia de la casa destinada al descanso y sueño", "example_phrase": "主卧室 (master bedroom)"}], "example_sentences": [{"id": "#1", "hanzi": "母亲把朝南采光最好的大卧室留给了我们夫妻俩，自己却坚持要住背阴偏小的那一间客房。", "pinyin": "Mǔqīn bǎ cháo nán cǎiguāng zuì hǎo de dà wòshì liú gěi le wǒmen fūqī liǎ, zìjǐ què jiānchí yào zhù bèiyīn piān xiǎo de nà yì jiān kèfáng.", "en": "Mother reserved the large south-facing bedroom with the best sunlight for our couple, while insisting on staying in the smaller guest room.", "es": "Mi madre reservó el dormitorio principal con sol del sur para nosotros dos, insistiendo ella en ocupar el cuarto de invitados más fresco."}, {"id": "#2", "hanzi": "现代化智能家居系统支持根据睡眠阶段自动调节卧室的温度、湿度与遮光窗帘，为居民打造深度睡眠环境。", "pinyin": "Xiàndàihuà zhìnéng jiājū xìtǒng zhīchí gēnjù shuìmián jiēduàn zìdòng tiáojié wòshì de wēndù, shīdù yǔ zhēguāng chuānglián, wèi jūmín dǎzào shēndù shuìmián huánjìng.", "en": "Modern smart home systems automatically calibrate bedroom temperature, humidity, and blackout curtains based on sleep phases, creating an ideal sleep haven.", "es": "La domótica moderna regula la temperatura, humedad y cortinas del dormitorio según la fase del sueño, favoreciendo un descanso nocturno reparador."}], "collocations": [{"hanzi": "主卧室", "en": "master bedroom"}, {"hanzi": "次卧室", "en": "secondary bedroom / guest bedroom"}, {"hanzi": "走进卧室", "en": "walk into the bedroom"}, {"hanzi": "卧室门", "en": "bedroom door"}, {"hanzi": "收拾卧室", "en": "tidy up the bedroom"}, {"hanzi": "卧室设计", "en": "bedroom interior design"}], "idioms": [{"hanzi": "藏龙卧虎", "pinyin": "cáng lóng wò hǔ", "meaning_en": "hidden dragons and crouching tigers; undiscovered talents"}, {"hanzi": "引狼入室", "pinyin": "yǐn láng rù shì", "meaning_en": "introduce a wolf into the house; bring danger upon oneself"}, {"hanzi": "登堂入室", "pinyin": "dēng táng rù shì", "meaning_en": "pass the hall and enter the chamber; attain high proficiency in learning"}, {"hanzi": "卧薪尝胆", "pinyin": "wò xīn cháng dǎn", "meaning_en": "sleep on brushwood and taste gall; undergo self-imposed hardships to achieve ambition"}], "character_decomposition": [{"character": "卧", "pinyin": "wò", "meaning_en": "lie down; recline; crouch", "meaning_es": "acostarse; reclinar; yacer; agazapado", "radical": "卜", "radical_meaning_en": "divining line / minister", "meaning_component": "臣 (downward gazing eye / leaning body)", "sound_component": "卜 (bǔ, phonetic / posture marker)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Depicts a weary human body (臣) leaning over horizontally to recline and rest on a mat.", "visual_mnemonic_story_en": "A person leaning their head down (臣) to rest horizontally on a quiet sleeping mat.", "visual_mnemonic_story_es": "Una persona que reclina la cabeza (臣) para descansar el cuerpo sobre una estera nocturna.", "tone_mnemonic_anchor": "51", "cangjie": "SLY", "traditional": "臥"}, {"character": "室", "pinyin": "shì", "meaning_en": "room; chamber; office", "meaning_es": "habitación; sala; estancia; cámara", "radical": "宀", "radical_meaning_en": "roof with chimney", "meaning_component": "宀 (protective residential roof)", "sound_component": "至 (zhì, reach / settle)", "stroke_count": "9", "composition_type": "上下结构", "etymology_and_mnemonic": "Ideogrammic compound of roof (宀) over arrive (至), meaning the ultimate chamber where a traveler reaches domestic rest.", "visual_mnemonic_story_en": "Reaching (至) safety beneath the family roof (宀) to dwell securely inside a private room (室).", "visual_mnemonic_story_es": "Llegar (至) al cobijo bajo el techo hogareño (宀) para descansar en una estancia íntima (室).", "tone_mnemonic_anchor": "51", "cangjie": "JMGI", "traditional": "室"}], "extended_reading_passages": [{"id": "#1", "hanzi": "穿过客厅推开卧室的门，阳光透过白色纱帘柔柔地洒在大床上。母亲提前铺好的棉被散发着清新的气息，枕边还细心摆放着安神的香囊。这方寸之间的小天地，永远是抵御风尘最安宁的港湾。", "pinyin": "Chuānguò kètīng tuīkāi wòshì de mén, yángguāng tòuguò báisè shālián róuróu de sǎ zài dà chuáng shàng. Mǔqīn tíqián pū hǎo de miánbèi sànfā zhe qīngxīn de qìxī, zhěnbiān hái xìxīn bǎifàng zhe ānshén de xiāngnáng. Zhè fāngcùn zhījiān de xiǎotiāndì, yǒngyuǎn shì dǐyù fēngchén zuì ānníng de gǎngwān.", "en": "Crossing the living room and opening the bedroom door, sunlight filtered softly through white lace curtains onto the bed. The quilt mother smoothed smelled fresh, a soothing sachet by the pillow. This haven guards from the world.", "es": "Cruzando el salón al abrir el dormitorio, el sol entraba tamizado por el visillo blanco. El edredón estirado por la madre olía a pureza, con un saquito aromático junto a la almohada. Aquel rincón es un puerto de paz ante el mundo."}, {"id": "#2", "hanzi": "现代人居健康建筑标准将卧室声学与微气候环境置于核心考量。通过安装双层中空隔音玻璃、低噪声新风置换系统与昼夜节律光谱灯具，高品质卧室设计有效保障了现代高压人群深度睡眠与机能恢复。", "pinyin": "Xiàndài rénjū jiànkāng jiànzhù biāozhǔn jiāng wòshì shēngxué yǔ wēiqìhòu huánjìng zhìyú héxīn kǎoliàng. Tōngguò ānzhuāng shuāngcéng zhōngkōng géyīn bōli, dīzàoshēng xīnfēng zhìhuàn xìtǒng yǔ zhòuyè jiélǜ guāngpǔ dēngjù, gāopǐnzhì wòshì shèjì yǒuxiào bǎozhàng le xiàndài gāoyā rénqún shēndù shuìmián yǔ jīnéng huīfù.", "en": "Healthy building standards place bedroom acoustics and microclimate at the center. Soundproof double glazing, fresh-air exchange, and circadian lighting in bedroom design safeguard deep sleep for stressed populations.", "es": "La arquitectura del bienestar prioriza la acústica y el microclima del dormitorio. Dobles acristalamientos, ventilación silenciosa e iluminación circadiana garantizan un sueño profundo y reparador en la vida moderna."}]}, {"meanings_summary": {"en": "to spread; to pave; to unfold; to make (a bed); store / shop / berth (read pù)", "es": "extender; desplegar; tender (la cama); pavimentar; tienda / litera (leído pù)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Fastening broad plates of metal (钅) or unrolling fabric wide (甫) smoothly spreads out (铺) a surface.", "composite_memory_hook_es": "Extender planchas resistentes (钅) o desplegar telas a lo ancho (甫) sirve para tender (铺) la cama con esmero.", "cultural_and_cognitive_roots": "In traditional Chinese domestic hospitality, '铺床' (making a bed with fresh quilts) is a heartfelt ritual welcoming weary travelers, signaling total familial embrace and maternal solicitude.", "tone_sandhi_and_pitch_modulation": "When used as a verb (spread/pave), pronounced in 1st tone: 'pū' (55). When used as a noun (shop/store/berth, e.g. 店铺, 上铺), pronounced in 4th tone: 'pù' (51)."}, "semantic_boundary_contrasts": {"core_nuance": "铺 indicates spreading, unfolding, or smoothing an object horizontally across a flat surface.", "contrasts": [{"id": "1", "compared_word": "铺 vs. 盖", "pinyin": "gài", "analysis": "铺 means spreading something beneath or horizontally flat onto a mattress or floor (e.g. 铺床单, 铺地砖), whereas 盖 means draping over or covering from above (e.g. 盖被子, 盖上盖子)."}, {"id": "2", "compared_word": "铺 vs. 展", "pinyin": "zhǎn", "analysis": "铺 emphasizes smoothing flat onto a supporting base, while 展 emphasizes unfolding, expanding, or putting on display in 3D space (e.g. 展开翅膀, 展览)."}, {"id": "3", "compared_word": "铺 vs. 垫", "pinyin": "diàn", "analysis": "铺 is horizontal spreading, while 垫 emphasizes placing something underneath to provide cushioning, elevate, or pad (e.g. 垫高, 垫子)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "浦", "pinyin": "pǔ", "meaning_en": "riverbank; shore", "distinction_note": "Has 氵 (water) on the left instead of 钅 (metal)"}, {"character": "捕", "pinyin": "bǔ", "meaning_en": "catch; seize; arrest", "distinction_note": "Has 扌 (hand) on the left of 甫"}, {"character": "辅", "pinyin": "fǔ", "meaning_en": "assist; auxiliary", "distinction_note": "Has 车 (cart) on the left of 甫"}, {"character": "傅", "pinyin": "fù", "meaning_en": "tutor; teacher", "distinction_note": "Has 亻 (person) with 寸 on the right"}], "etymological_cognates": [{"character": "铺设", "pinyin": "pū shè", "gloss_en": "lay down; pave; install"}, {"character": "平铺", "pinyin": "píng pū", "gloss_en": "spread flat"}, {"character": "床铺", "pinyin": "chuáng pù", "gloss_en": "bed; sleeping berth"}, {"character": "店铺", "pinyin": "diàn pù", "gloss_en": "shop; retail store"}]}, "id": "35", "hanzi": "铺", "pinyin": "pū", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to spread out, unfold, or smooth bedding, rugs, or tablecloths", "definition_es": "extender; desplegar; tender la cama o manteles", "example_phrase": "铺床 (make the bed / spread sheets)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to lay down or pave a road, floor, or pipeline", "definition_es": "pavimentar; tender baldosas, raíles o tuberías", "example_phrase": "铺路 (pave a road)"}, {"sense_number": "3", "part_of_speech": "Noun", "register": "Standard", "definition_en": "(read pù) a shop, store, or sleeping berth / bunk", "definition_es": "(leído pù) tienda; comercio; litera", "example_phrase": "卧铺 (sleeping berth on train)"}], "example_sentences": [{"id": "#1", "hanzi": "母亲把刚在日头下晒得干爽蓬松的棉被小心翼翼地抱进屋，平平整整地铺在大床上。", "pinyin": "Mǔqīn bǎ gāng zài rìtou xià shài de gānshuǎng péngsōng de miánbèi xiǎoxīnyìyì de bào jìn wū, píngpíng-zhěngzhěng de pū zài dà chuáng shàng.", "en": "Mother carried the fluffy, dry cotton quilt freshly sunned under the daylight into the room, spreading it neat and smooth over the large bed.", "es": "Mi madre llevó a la habitación el mullido edredón bien soleado y lo extendió con mimo sobre la cama matrimonial sin una arruga."}, {"id": "#2", "hanzi": "为了改善山区农村群众的出行条件，交通运输局组织大型机械加班加点铺设沥青路面。", "pinyin": "Wèile gǎishàn shānqū nóngcūn qúnzhòng de chūxíng tiáojiàn, jiāotōng yùnshū jú zǔzhī dàxíng jīxiè jiābān-jiādiǎn pūshè lìqīng lùmiàn.", "en": "To improve travel conditions for mountain villagers, the transport bureau organized heavy machinery working overtime to pave asphalt roads.", "es": "Para mejorar los caminos de los pueblos de la sierra, transportes desplegó maquinaria pesada trabajando horas extras para pavimentar la calzada con asfalto."}], "collocations": [{"hanzi": "铺床", "en": "make the bed / spread bedding"}, {"hanzi": "铺路", "en": "pave a road"}, {"hanzi": "铺满", "en": "spread all over; carpeted with"}, {"hanzi": "铺平", "en": "smooth out; flatten"}, {"hanzi": "铺盖", "en": "bedding / bedroll"}, {"hanzi": "床铺", "en": "bed; sleeping place (read pù)"}], "idioms": [{"hanzi": "铺天盖地", "pinyin": "pū tiān gài dì", "meaning_en": "blot out the sky and cover the earth; overwhelming in scale"}, {"hanzi": "节衣缩食", "pinyin": "jié yī suō shí", "meaning_en": "live frugally; tighten one's belt"}, {"hanzi": "铺张浪费", "pinyin": "pū zhāng làng fèi", "meaning_en": "extravagant and wasteful; excessive luxury"}, {"hanzi": "平铺直叙", "pinyin": "píng pū zhí xù", "meaning_en": "speak or write in a dull, straightforward narrative style"}], "character_decomposition": [{"character": "铺", "pinyin": "pū", "meaning_en": "spread; pave; store; bed", "meaning_es": "extender; desplegar; pavimentar; tienda", "radical": "钅", "radical_meaning_en": "metal / gold", "meaning_component": "钅 (metal door-knocker / hardware)", "sound_component": "甫 (fǔ, broad / phonetic)", "stroke_count": "12", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where metal 钅 originally referred to flat metal door-plates, expanding to spreading materials flat.", "visual_mnemonic_story_en": "Spreading shiny flat metal tiles (钅) broad and wide (甫) across an open floor to pave it smoothly.", "visual_mnemonic_story_es": "Extender planchas de metal pulido (钅) a lo largo y ancho (甫) para allanar y pavimentar el suelo con tersura.", "tone_mnemonic_anchor": "55", "cangjie": "CIBY", "traditional": "鋪"}], "extended_reading_passages": [{"id": "#1", "hanzi": "秋末初冬的落叶铺满了古朴的庭院，金黄一片。踩在厚厚的落叶上，脚下发出清脆细碎的声响。屋里母亲早已把新棉絮铺在木床上，那份沉静而踏实的暖意，让归家的游子倍感宁静。", "pinyin": "Qiūmò-chūdōng de luòyè pūmǎn le gǔpǔ de tíngyuàn, jīnhuáng yí piàn. Cǎi zài hòuhòu de luòyè shàng, jiǎoxià fāchū qīngcuì xìsuì de shēngxiǎng. Wūlǐ mǔqīn zǎoyǐ bǎ xīn miánxù pū zài mùchuáng shàng, nà fèn chénjìng ér tàshi de nuǎnyì, ràng guījiā de yóuzǐ bèi gǎn níngjìng.", "en": "Late autumn fallen leaves carpet the courtyard in pure gold. Treading upon the leaves makes crisp rustling whispers. Indoors mother had smoothed fresh cotton onto the bed, its calm warmth comforting the returning traveler.", "es": "Las hojas secas de otoño alfombran de oro el patio rústico. Al pisarlas crujen con suave susurro. Dentro, madre ha extendido el algodón nuevo sobre el lecho; esa paz sólida sosiega al viajero de vuelta al hogar."}, {"id": "#2", "hanzi": "国家高速铁路与轨道交通网络的快速铺设，构筑起现代综合立体交通网的大动脉。先进的长钢轨无缝焊接与精准铺轨施工技术，确保了列车在时速三百五十公里高速行驶下的极佳平稳性与舒适度。", "pinyin": "Guójiā gāosù tiělù yǔ guǐdào jiāotōng wǎngluò de kuàisù pūshè, gòuzhù qǐ xiàndài zōnghé lìtǐ jiāotōngwǎng de dàmàimài. Xiānjìn de cháng gāngguǐ wúfèng hànjiē yǔ jīngzhǔn pūguǐ shīgōng jìshù, quèbǎo le lièchē zài shísù sān bǎi wǔshí gōnglǐ gāosù xíngshǐ xià de jí jiā píngwěnxìng yǔ shūshìdù.", "en": "Rapid laying of high-speed rail networks forms arteries of modern transit. Advanced continuous welded rail and precision track-laying techniques ensure supreme stability and passenger comfort at speeds of 350 km/h.", "es": "El tendido de líneas férreas de alta velocidad articula las arterias del transporte moderno. La soldadura continua de raíles y el tendido milimétrico de vías garantizan suavidad y confort a 350 kilómetros por hora."}]}, {"meanings_summary": {"en": "to float; to drift; to flutter in the wind; to waft (of scents or sounds)", "es": "flotar; flotar en el aire; ondear al viento; esparcirse (aroma o sonido)"}, "mnemonics_and_roots": {"composite_memory_hook_en": "A light paper sheet (票) caught in a gust of wind (风) gracefully flutters and drifts (飘) across the sky.", "composite_memory_hook_es": "Una leve cuartilla de papel (票) atrapada por la brisa del viento (风) flota y ondea (飘) por el aire.", "cultural_and_cognitive_roots": "In classical Chinese lyrical poetry, '飘' evokes transient, ethereal beauty—petals falling at dusk, banners waving over distant ramparts, or drifting wanderers ('飘零') searching for home.", "tone_sandhi_and_pitch_modulation": "Pronounced in the 1st tone with a sustained, light, elevated pitch: 'piāo' (55). Keep the articulation buoyant and breathy to mirror its floating meaning."}, "semantic_boundary_contrasts": {"core_nuance": "飘 emphasizes being suspended and carried lightly through the atmosphere by air or wind currents.", "contrasts": [{"id": "1", "compared_word": "飘 vs. 漂", "pinyin": "piāo", "analysis": "飘 implies floating or wafting through the air or wind (e.g. 飘雪, 飘香), whereas 漂 strictly requires floating on the surface of liquid or water (e.g. 漂在水面上)."}, {"id": "2", "compared_word": "飘 vs. 飞", "pinyin": "fēi", "analysis": "飘 is passive, gentle fluttering propelled solely by air currents, while 飞 involves active, powered self-propulsion through wings or engines (e.g. 鸟在飞, 飞机起飞)."}, {"id": "3", "compared_word": "飘 vs. 落", "pinyin": "luò", "analysis": "飘 highlights the graceful mid-air drifting trajectory, whereas 落 emphasizes the final downward descent or landing impact (e.g. 落在地上)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "漂", "pinyin": "piào / piāo", "meaning_en": "float on water; bleach", "distinction_note": "Has 氵 (water) on the left instead of 风 (wind)"}, {"character": "膘", "pinyin": "biāo", "meaning_en": "fat; meat", "distinction_note": "Has 月 (flesh) on the left of 票"}, {"character": "瓢", "pinyin": "piáo", "meaning_en": "gourd ladle", "distinction_note": "Has 瓜 (melon/gourd) on the right of 票"}, {"character": "飘", "pinyin": "piāo", "meaning_en": "float in air", "distinction_note": "Simplified with left 票 and right 风; traditional has left 票 right 飄"}], "etymological_cognates": [{"character": "飘扬", "pinyin": "piāo yáng", "gloss_en": "wave in the wind; flutter"}, {"character": "飘渺", "pinyin": "piāo miǎo", "gloss_en": "faintly discernable; misty"}, {"character": "漂泊", "pinyin": "piāo bó", "gloss_en": "drift aimlessly; lead a nomadic life"}, {"character": "风吹", "pinyin": "fēng chuī", "gloss_en": "wind blows"}]}, "id": "36", "hanzi": "飘", "pinyin": "piāo", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to blow, drift, or flutter lightly in the air or on wind currents", "definition_es": "flotar en el aire; revolotear; ondear al viento", "example_phrase": "红旗迎风飘扬 (red flags flutter in the wind)"}, {"sense_number": "2", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to waft, drift, or spread gently across space (smell, fragrance, melody)", "definition_es": "esparcirse; flotar en el ambiente (aromas, música)", "example_phrase": "飘来阵阵清香 (waves of fresh fragrance waft in)"}], "example_sentences": [{"id": "#1", "hanzi": "刚走上楼梯，母亲在厨房炖土鸡的浓郁香味就从门缝里悄悄飘了出来，勾起了满满的食欲。", "pinyin": "Gāng zǒu shàng lóutī, mǔqīn zài chúfáng dùn tǔjī de nóngyù xiāngwèi jiù cóng ménfèng lǐ qiāoqiāo piāo le chūlái, gōuqǐ le mǎnmǎn de shíyù.", "en": "Just stepping onto the stairs, the rich aroma of free-range chicken stewed by mother drifted softly through the door crack, stirring an appetite.", "es": "Al subir por la escalera, el apetitoso aroma del guiso de pollo que preparaba madre se filtró por la rendija de la puerta despertando el apetito."}, {"id": "#2", "hanzi": "初春的细雨夹杂着微风，漫天洁白的樱花花瓣如雪花般在校园林荫道上随风缓缓飘落。", "pinyin": "Chūchūn de xìyǔ jiāzá zhe wēifēng, màntiān jiébái de yīnghuā huābàn rú xuěhuā bān zài xiàoyuán línyīndào shàng suí fēng huǎnhuǎn piāoluò.", "en": "Early spring drizzle mingled with gentle breeze as pure white cherry blossom petals drifted softly like snowflakes along the shaded campus avenue.", "es": "La llovizna primaveral se mezclaba con la brisa mientras los pétalos de cerezo flotaban y caían como copos de nieve por la alameda del campus."}], "collocations": [{"hanzi": "飘扬", "en": "flutter in the breeze; fly"}, {"hanzi": "飘荡", "en": "drift gently; waft"}, {"hanzi": "飘落", "en": "flutter down; drift down"}, {"hanzi": "飘香", "en": "waft fragrance; emit sweet scent"}, {"hanzi": "飘来", "en": "waft over; drift in"}, {"hanzi": "随风飘动", "en": "drift / float with the wind"}], "idioms": [{"hanzi": "随波逐流", "pinyin": "suí bō zhú liú", "meaning_en": "drift with the waves and follow the current; lack independent conviction"}, {"hanzi": "凤泊鸾飘", "pinyin": "fèng bó luán piāo", "meaning_en": "phoenix stranded and luan bird drifting; talented people wandering in exile"}, {"hanzi": "天女散花", "pinyin": "tiān nǚ sàn huā", "meaning_en": "heavenly maiden scatters blossoms; petals or snow drifting everywhere"}, {"hanzi": "风雨飘摇", "pinyin": "fēng yǔ piāo yáo", "meaning_en": "tottering in wind and rain; unstable and precarious situation"}], "character_decomposition": [{"character": "飘", "pinyin": "piāo", "meaning_en": "float; drift; flutter; waft", "meaning_es": "flotar; ondear; esparcirse", "radical": "风", "radical_meaning_en": "wind", "meaning_component": "风 (gusts of wind carrying items)", "sound_component": "票 (piào, light paper slip / phonetic)", "stroke_count": "15", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where wind radical 风 carries light objects resembling fluttering tickets (票) gracefully through the air.", "visual_mnemonic_story_en": "A light paper slip (票) lifted high into the sky by a sudden breeze of wind (风), drifting effortlessly.", "visual_mnemonic_story_es": "Una leve tira de papel (票) alzada por una racha de viento (风) que flota grácilmente por el aire sin peso.", "tone_mnemonic_anchor": "55", "cangjie": "MFHN", "traditional": "飄"}], "extended_reading_passages": [{"id": "#1", "hanzi": "黄昏漫步在故乡的小巷，缕缕炊烟在暮色中随风轻盈飘荡。空气里飘来柴火燃烧的青涩香气与煎鱼的诱人芬芳，这熟悉的烟火气息瞬间驱散了游子心中的清冷，化作了无尽的眷恋。", "pinyin": "Huánghūn mànbù zài gùxiāng de xiǎoxiàng, lǚlǚ chuīyān zài mùsè zhōng suí fēng qīngyíng piāodàng. Kōngqì lǐ piāolái cháihuǒ ránshāo de qīngsè xiāngqì yǔ jiānyú de yòurén fēnfāng, zhè shúxī de yānhuǒ qìxī shùnjiān qūsàn le yóuzǐ xīnzhōng de qīnglěng, huàzuò le wújìn de juànliàn.", "en": "Strolling home lanes at dusk, cooking smoke drifted gracefully into twilight. Familiar scents of burning wood and fried fish wafted on the air, dispelling chills and awakening boundless affection.", "es": "Paseando al atardecer por los callejones natales, el humo de las cocinas flotaba en la penumbra. Los aromas a leña y pescado frito disiparon el frío del viajero convirtiéndose en ternura."}, {"id": "#2", "hanzi": "大气气溶胶颗粒在大尺度环流驱动下的远距离飘移与沉降，是全球生物地球化学循环的关键环节。科学家利用卫星激光雷达监测沙尘微粒跨洋飘散路径，为精准预警跨区域沙尘天气提供了重要科学依据。", "pinyin": "Dàqì qìróngjiāo kēlì zài dàchǐdù huánliú qūdòng xià de yuǎnjùlí piāoyí yǔ chénjiàng, shì quánqiú shēngwù-dìqiú-huàxué xúnhuán de guānjiàn huánjié. Kēxuéjiā lìyòng wèixīng jīguāng léidá jiāncè shāchén wēilì kuàyáng piāosàn lùjìng, wèi jīngzhǔn yùjǐng kuàqūyù shāchén tiānqì tígōng le zhòngyào kēxué yījù.", "en": "Long-range drifting and deposition of aerosols driven by global atmospheric circulation forms a vital biogeochemical cycle. Satellite lidars track dust transoceanic drift paths to warn of transboundary dust storms.", "es": "La dispersión y deriva de aerosoles atmosféricos por corrientes globales es clave en los ciclos biogeoquímicos. Satélites con sónar láser rastrean el polvo transoceánico para pronosticar temporales de arena."}]}, {"meanings_summary": {"en": "a wave; a spell; a burst of; brief period (wind, rain, applause); battle array", "es": "racha; ráfaga; golpe; chaparrón; periodo breve; formación de combate"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Chariots (车) lined up against the hillside rampart (阝) advance in sudden tactical waves and bursts (阵).", "composite_memory_hook_es": "Carros de guerra (车) ordenados frente a la colina (阝) avanzan en oleadas y rachas coordinadas (阵).", "cultural_and_cognitive_roots": "Originating from the ancient art of warfare (八卦阵), '阵' transitioned from battlefield ranks into a temporal measure word capturing episodic bursts of nature—gusts of autumn wind or waves of nostalgia.", "tone_sandhi_and_pitch_modulation": "Pronounced in the 4th tone with a decisive falling pitch: 'zhèn' (51). When paired with '一' (yī), '一' shifts to 2nd tone: 'yí zhèn' (35-51)."}, "semantic_boundary_contrasts": {"core_nuance": "阵 acts as a measure word for intermittent, wave-like, or temporary phenomena that surge and subside.", "contrasts": [{"id": "1", "compared_word": "阵 vs. 场", "pinyin": "cháng", "analysis": "阵 classifies sudden, short-lived bursts of rain or wind (e.g. 一阵风, 一阵雨), whereas 场 classifies extended, complete events, shows, or prolonged storms (e.g. 一场大雨, 一场电影)."}, {"id": "2", "compared_word": "阵 vs. 串", "pinyin": "chuàn", "analysis": "阵 implies periodic waves surging and ebbing, while 串 emphasizes discrete physical items strung together along a single linear thread (e.g. 一串钥匙)."}, {"id": "3", "compared_word": "阵 vs. 番", "pinyin": "fān", "analysis": "阵 describes sudden physical bursts of sensations or weather, whereas 番 designates an extensive expenditure of mental or physical effort (e.g. 一番番苦心)."}]}, "traps_and_cognates": {"look_alikes": [{"character": "陈", "pinyin": "chén", "meaning_en": "display; old; surname", "distinction_note": "Has 东 on the right of 阝 instead of 车"}, {"character": "车", "pinyin": "chē", "meaning_en": "cart; vehicle", "distinction_note": "Standalone right component of simplified 阵"}, {"character": "附", "pinyin": "fù", "meaning_en": "attach; close", "distinction_note": "Has 付 on the right of 阝 instead of 车"}, {"character": "阶", "pinyin": "jiē", "meaning_en": "steps; ladder", "distinction_note": "Has 介 on the right of 阝 instead of 车"}], "etymological_cognates": [{"character": "阵雨", "pinyin": "zhèn yǔ", "gloss_en": "shower of rain"}, {"character": "阵痛", "pinyin": "zhèn tòng", "gloss_en": "labor pains; spasm; short sharp pain"}, {"character": "排兵布阵", "pinyin": "pái bīng bù zhèn", "gloss_en": "deploy troops in battle formations"}, {"character": "助阵", "pinyin": "zhù zhèn", "gloss_en": "cheer on; back up; support"}]}, "id": "37", "hanzi": "阵", "pinyin": "zhèn", "level": "HSK 5", "part_of_speech": "Measure Word", "senses": [{"sense_number": "1", "part_of_speech": "Measure Word", "register": "Standard", "definition_en": "classifier for events occurring in short bursts, waves, spells, or gusts", "definition_es": "clasificador para rachas breves, oleadas o ráfagas", "example_phrase": "一阵风 (a gust of wind)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "battle array; front; position in military combat or struggle", "definition_es": "formación militar; frente de combate; trinchera", "example_phrase": "摆开阵势 (set out battle array)"}], "example_sentences": [{"id": "#1", "hanzi": "钻进刚被母亲晒过、铺得平平整整的被子里，鼻尖立刻涌上一阵阵混合着阳光与棉花香甜的暖意。", "pinyin": "Zuānjìn gāng bèi mǔqīn shài guò, pū de píngpíng-zhěngzhěng de bèizi lǐ, bíjiān lìkè yǒng shàng yí zhènzhèn hùnhé zhe yángguāng yǔ miánhua xiāngtián de nuǎnyì.", "en": "Slipping into the quilt freshly sunned and neatly made by mother, waves of sweet warmth blending sunlight and cotton immediately surged to my nose.", "es": "Al meterme en la colcha bien soleada y estirada por mi madre, oleadas de calor suave con aroma a sol y algodón envolvieron mi rostro."}, {"id": "#2", "hanzi": "报告厅内演讲刚一结束，全场听众便自发爆发出了一阵阵经久不息的热烈掌声与真挚欢呼。", "pinyin": "Bàogàotīng nèi yǎnjiǎng gāng yì jiéshù, quánchǎng tīngzhòng biàn zìfā bàofā chū le yí zhènzhèn jīngjiǔ-bùxī de rèliè zhǎngshēng yǔ zhēnzhì huānhū.", "en": "As the lecture concluded in the auditorium, the entire audience spontaneously burst into waves of prolonged enthusiastic applause and cheers.", "es": "Apenas concluida la conferencia, el auditorio entero rompió de forma unánime en sucesivas salvas de aplausos prolongados y vítores."}], "collocations": [{"hanzi": "一阵风", "en": "a gust of wind"}, {"hanzi": "一阵雨", "en": "a shower / spell of rain"}, {"hanzi": "一阵阵", "en": "wave upon wave / repeated bursts"}, {"hanzi": "掌声雷动", "en": "thunderous applause in bursts"}, {"hanzi": "上阵", "en": "go into battle; take the field"}, {"hanzi": "阵地", "en": "battleground; position; bastion"}], "idioms": [{"hanzi": "冲锋陷阵", "pinyin": "chōng fēng xiàn zhèn", "meaning_en": "charge forward and breach enemy battle arrays; fight courageously"}, {"hanzi": "严阵以待", "pinyin": "yán zhèn yǐ dài", "meaning_en": "remain in tight battle formation ready for the enemy"}, {"hanzi": "临阵磨枪", "pinyin": "lín zhèn mó qiāng", "meaning_en": "sharpen spears on the battlefield; make hurried preparations at the last minute"}, {"hanzi": "赤膊上阵", "pinyin": "chì bó shàng zhèn", "meaning_en": "strip to the waist and go into battle; throw oneself headlong into struggle"}], "character_decomposition": [{"character": "阵", "pinyin": "zhèn", "meaning_en": "array; battlefront; spell of", "meaning_es": "formación; racha; oleada; frente", "radical": "阝", "radical_meaning_en": "mound / hill (left mound)", "meaning_component": "阝 (defensive earthen rampart)", "sound_component": "车 (chē, war chariot / phonetic)", "stroke_count": "6", "composition_type": "左右结构", "etymology_and_mnemonic": "Phono-semantic compound where military chariots (车) align along an earthen defensive rampart (阝) in combat formations.", "visual_mnemonic_story_en": "War chariots (车) deployed in orderly rows against a defensive hillside (阝), advancing in sudden coordinated waves.", "visual_mnemonic_story_es": "Carros de combate (车) desplegados junto a una colina (阝) que avanzan en sucesivas oleadas tácticas.", "tone_mnemonic_anchor": "51", "cangjie": "NLKQ", "traditional": "陣"}], "extended_reading_passages": [{"id": "#1", "hanzi": "秋风乍起，卷起院角一堆金黄的落叶，在半空中打着旋儿。门缝里吹进一阵阵清凉的微风，伴随着远处隐约的笛声，给久居喧嚣都市的心灵送来了一阵难得的清宁与释怀。", "pinyin": "Qiūfēng zhàqǐ, juǎnqǐ yuànjiǎo yì duī jīnhuáng de luòyè, zài bànkōng zhōng dǎ zhe xuán'ér. Ménfèng lǐ chuījìn yí zhènzhèn qīngliáng de wēifēng, bànsuí zhe yuǎnchù yǐnyuē de dísheng, gěi jiǔjū xuānxiāo dūshì de xīnlíng sònglái le yí zhèn nándé de qīngníng yǔ shìhuái.", "en": "Autumn wind stirred, swirling golden leaves in the courtyard corner. Breezes blew through door cracks in waves, accompanied by distant flutes, delivering rare serenity and release to urban-weary souls.", "es": "El viento otoñal alzó remolinos de hojas secas en el patio. Por la rendija entraban oleadas de brisa fresca que, con el eco lejano de una flauta, trajeron un sosiego reconfortante al espíritu."}, {"id": "#2", "hanzi": "气象雷达监测显示，强对流冷锋过境引发了一阵阵剧烈的短时雷暴大风。防汛抗旱指挥部迅速启动应急预案，通过高频次气象卫星云图研判风暴走向，保障了沿海航运与电网设施的安全稳定。", "pinyin": "Qìxiàng léidá jiāncè xiǎnshì, qiángduìliú lěngfēng guòjìng yǐnfā le yí zhènzhèn jùliè de duǎnshí léibào dàfēng. Fángxùn-kànghàn zhǐhuībù xùnsù qǐdòng yìngjí yù'àn, tōngguò gāopíncì qìxiàng wèixīng yúntú yánpàn fēngbào zǒuxiàng, bǎozhàng le yánhǎi hángyùn yǔ diànwǎng shèshī de ānquán wěndìng.", "en": "Radar monitoring showed convective cold fronts triggering waves of violent short-duration thunderstorms. Flood control headquarters activated emergency plans, tracking clouds via satellites to safeguard maritime shipping.", "es": "El radar meteorológico detectó un frente frío que desató ráfagas violentas de tormenta. El centro de control analizó imágenes satelitales en tiempo real para proteger la navegación costera y las redes eléctricas."}]}, {"meanings_summary": {"en": "to feel; to experience; to perceive; subjective impression; feeling", "es": "sentir; experimentar; percibir; sensación; vivencia subjetiva"}, "mnemonics_and_roots": {"composite_memory_hook_en": "The heart (感) receiving and absorbing (受) the world's impressions produces a profound feeling (感受).", "composite_memory_hook_es": "El corazón que siente (感) recibiendo y acogiendo (受) las vivencias del mundo da lugar a un sentimiento hondo (感受).", "cultural_and_cognitive_roots": "In Chinese epistemology, '感受' signifies organic experiential unity between sensory stimulus and emotional internalisation, contrasting mere dispassionate intellectual observation with holistic bodily immersion.", "tone_sandhi_and_pitch_modulation": "Pronounced with a 214-51 pitch contour (3rd tone dipping smoothly, followed by 4th tone falling resolutely)."}, "semantic_boundary_contrasts": {"core_nuance": "感受 emphasizes subjective emotional impressions, inner resonance, or psychological absorption of experiences.", "contrasts": [{"id": "1", "compared_word": "感受 vs. 感觉", "pinyin": "gǎnjué", "analysis": "感觉 covers both raw physical sensory reception (cold, pain, light) and intuition (e.g. 感觉有点冷), whereas 感受 emphasizes deeper subjective psychological evaluation and emotional resonance (e.g. 谈谈你对这部作品的感受)."}, {"id": "2", "compared_word": "感受 vs. 体会", "pinyin": "tǐhuì", "analysis": "感受 focuses on emotional and affective impression, while 体会 stresses intellectual appreciation, practical comprehension, or philosophical insight gained through hands-on practice."}, {"id": "3", "compared_word": "感受 vs. 感动", "pinyin": "gǎndòng", "analysis": "感受 is a broad neutral awareness of an experience, whereas 感动 is specifically the intense emotion of being moved to tears or inspired by virtue."}]}, "traps_and_cognates": {"look_alikes": [{"character": "爱", "pinyin": "ài", "meaning_en": "love; affection", "distinction_note": "Has 心 in middle with 友-like bottom instead of 又 alone"}, {"character": "妥", "pinyin": "tuǒ", "meaning_en": "proper; settled", "distinction_note": "Has 女 at the bottom instead of 又"}, {"character": "咸", "pinyin": "xián", "meaning_en": "salty; all", "distinction_note": "Top component of 感 without lower 心"}, {"character": "惑", "pinyin": "huò", "meaning_en": "confused; doubt", "distinction_note": "Has 或 over 心 instead of 咸"}], "etymological_cognates": [{"character": "感情", "pinyin": "gǎn qíng", "gloss_en": "emotion; feeling; sentiment"}, {"character": "感觉", "pinyin": "gǎn jué", "gloss_en": "sense; feeling; perceive"}, {"character": "接受", "pinyin": "jiē shòu", "gloss_en": "accept; receive"}, {"character": "体会", "pinyin": "tǐ huì", "gloss_en": "learn through experience; empathize"}]}, "id": "38", "hanzi": "感受", "pinyin": "gǎn shòu", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to perceive or experience emotionally or sensory-wise from an external stimulus", "definition_es": "sentir; experimentar o percibir por los sentidos o el ánimo", "example_phrase": "感受大自然的美好 (experience the beauty of nature)"}, {"sense_number": "2", "part_of_speech": "Noun", "register": "Standard", "definition_en": "subjective feeling, inner impression, or experiential insight", "definition_es": "impresión subjetiva; sensación; vivencia interior", "example_phrase": "谈谈你的感受 (share your impressions)"}], "example_sentences": [{"id": "#1", "hanzi": "躺在母亲刚晒过的蓬松棉被里，闻着阳光的味道，我真真切切地感受到了家无可替代的温暖。", "pinyin": "Tǎng zài mǔqīn gāng shài guò de péngsōng miánbèi lǐ, wén zhe yángguāng de wèidao, wǒ zhēnzhēn-qièqiè de gǎnshòu dào le jiā wúkětìdài de wēnnuǎn.", "en": "Lying in the fluffy cotton quilt freshly sunned by mother and smelling sunshine, I truly and deeply felt the irreplaceable warmth of home.", "es": "Tumbado bajo el esponjoso edredón recién soleado por mi madre, respirando aroma a sol, sentí con nitidez la insustituible calidez del hogar."}, {"id": "#2", "hanzi": "为了深入了解基层消费者的实际需求，产品研发团队深入农村开展驻点调研，切身感受当地居民的生活痛点。", "pinyin": "Wèile shēnrù liǎojiě jīcéng xiāofèizhě de shíjì xūqiú, chǎnpǐn yánfā tuánduì shēnrù nóngcūn kāizhǎn zhùdiǎn diàoyán, qièshēn gǎnshòu dāngdì jūmín de shēnghuó tòngdiǎn.", "en": "To understand actual needs of grassroots consumers, the product R&D team embedded in rural villages, experiencing local residents' daily pain points firsthand.", "es": "Para conocer las demandas reales de los usuarios populares, el equipo técnico convivió en aldeas rurales experimentando de primera mano sus dificultades cotidianas."}], "collocations": [{"hanzi": "切身感受", "en": "firsthand feeling / personal experience"}, {"hanzi": "谈谈感受", "en": "talk about one's impressions / thoughts"}, {"hanzi": "深有感受", "en": "feel deeply / relate intensely"}, {"hanzi": "感受生活", "en": "experience life"}, {"hanzi": "主观感受", "en": "subjective feeling / perception"}, {"hanzi": "感受温暖", "en": "feel warmth / kindness"}], "idioms": [{"hanzi": "身临其境", "pinyin": "shēn lín qí jìng", "meaning_en": "be personally on the scene; experience firsthand"}, {"hanzi": "感同身受", "pinyin": "gǎn tóng shēn shòu", "meaning_en": "empathize deeply as if experiencing it oneself"}, {"hanzi": "多愁善感", "pinyin": "duō chóu shàn gǎn", "meaning_en": "sentimental and melancholic; easily stirred to sadness"}, {"hanzi": "大有感触", "pinyin": "dà yǒu gǎn chù", "meaning_en": "deeply moved and stirred with impressions"}], "character_decomposition": [{"character": "感", "pinyin": "gǎn", "meaning_en": "feel; sense; emotion; move", "meaning_es": "sentir; emoción; conmover", "radical": "心", "radical_meaning_en": "heart / mind", "meaning_component": "心 (seat of human empathy and sensation)", "sound_component": "咸 (xián, harmonious touch / all)", "stroke_count": "13", "composition_type": "上下结构", "etymology_and_mnemonic": "Phono-semantic compound where external touch (咸) harmoniously resonates in the human heart-mind (心).", "visual_mnemonic_story_en": "An external touch that resonates through every fiber of the sensitive human heart (心), awakening deep feelings.", "visual_mnemonic_story_es": "Una vivencia exterior que conmueve las cuerdas íntimas del corazón (心), despertando hondas emociones.", "tone_mnemonic_anchor": "214", "cangjie": "IRP", "traditional": "感"}, {"character": "受", "pinyin": "shòu", "meaning_en": "receive; accept; endure; feel", "meaning_es": "recibir; aceptar; soportar; experimentar", "radical": "又", "radical_meaning_en": "hand", "meaning_component": "又 (hand receiving below)", "sound_component": "爫 (hand giving above)", "stroke_count": "8", "composition_type": "上下结构", "etymology_and_mnemonic": "Ancient ideogram showing an upper hand (爫) passing an object to a lower hand (又), signifying receiving.", "visual_mnemonic_story_en": "An upper hand passing a treasure to an outstretched lower hand (又) that receives and absorbs it.", "visual_mnemonic_story_es": "Una mano superior entregando un don a otra mano inferior (又) que lo acoge y asimila en su interior.", "tone_mnemonic_anchor": "51", "cangjie": "BME", "traditional": "受"}], "extended_reading_passages": [{"id": "#1", "hanzi": "生活的美好往往不在于轰轰烈烈的成就，而在于静下心来去感受每一个平凡的瞬间。清晨的第一缕微风、母亲端来的一碗热汤，只要用心去感受，生活中那些细碎的日常便都闪耀着幸福的光泽。", "pinyin": "Shēnghuó de měihǎo wǎngwǎng bú zàiyú hōnghōng-lièliè de chéngjiù, ér zàiyú jìng xià xīn lái qù gǎnshòu měi yí gè píngfán de shùnjiān. Qīngchén de dì-yī lǚ wēifēng, mǔqīn duān lái de yì wǎn rètāng, zhǐyào yòngxīn qù gǎnshòu, shēnghuó zhōng nàxiē xìsuì de rìcháng biàn dōu shǎnyào zhe xìngfú de guāngzé.", "en": "Beauty in life lies not in grand achievements, but in quietly experiencing each ordinary moment. The first morning breeze, a warm soup from mother—feeling with heart illuminates ordinary days with happiness.", "es": "La belleza de la vida radica en sosegar el ánimo y sentir la magia de lo cotidiano. La brisa del alba o el tazón de sopa tibia de madre, sentidos con el alma, iluminan la rutina con destellos de dicha."}, {"id": "#2", "hanzi": "用户体验设计研究正深度融合认知心理学与人机工程学方法。通过量化眼动轨迹、脑电生理指标与微表情，评估工程师能够客观解析用户在使用交互界面时的真实感受，推动软件产品在易用性与情感共鸣维度的迭代优化。", "pinyin": "Yònghù tǐyàn shèjì yánjiū zhèng shēndù rónghé rènzhī xīnlǐxué yǔ rénjī gōngchéngxué fāngfǎ. Tōngguò liànghuà yǎndòng guǐjì, nǎodiàn shēnglǐ zhǐbiāo yǔ wēibiǎoqíng, pínggū gōngchéngshī nénggòu kèguān jiěxī yònghù zài shǐyòng jiāohù jièmiàn shí de zhēnshí gǎnshòu, tuīdòng ruǎnjiàn chǎnpǐn zài yìyòngxìng yǔ qínggǎn gòngmíng wéidù de diédài yōuhuà.", "en": "UX research integrates cognitive psychology and ergonomics. Quantifying eye tracking and EEG signals enables engineers to analyze users' authentic feelings, refining software usability and emotional resonance.", "es": "El diseño de experiencia de usuario combina psicología cognitiva y ergonomía. Analizando la mirada y las señales neuronales, los analistas evalúan las sensaciones reales del usuario optimizando interfaces digitales con empatía."}]}, {"meanings_summary": {"en": "to shed tears; to weep; to cry", "es": "derramar lágrimas; llorar; soltar lágrimas"}, "mnemonics_and_roots": {"composite_memory_hook_en": "Water drops flowing (流) straight from the eyes (泪) are warm tears (流泪) shed in love and longing.", "composite_memory_hook_es": "Agua que fluye (流) brotando directamente de los ojos (泪) compone las lágrimas (流泪) de la emoción.", "cultural_and_cognitive_roots": "In Chinese literary tradition, tears shed at parting ('执手相看泪眼') or upon homecoming represent the pinnacle of emotional sincerity ('真情实感'), honoring genuine human affection beyond worldly pretension.", "tone_sandhi_and_pitch_modulation": "Pronounced with a 35-51 pitch contour (2nd tone rising cleanly, followed by 4th tone dropping with pathos). Keep the vocal transition fluid."}, "semantic_boundary_contrasts": {"core_nuance": "流泪 emphasizes the physical physiological phenomenon of teardrops flowing from the eyes.", "contrasts": [{"id": "1", "compared_word": "流泪 vs. 哭泣", "pinyin": "kūqì", "analysis": "流泪 denotes the physical tears trickling from eyes (often quiet or moved), whereas 哭泣 involves vocal sobbing, whimpering, and crying sounds of sadness."}, {"id": "2", "compared_word": "流泪 vs. 抽泣", "pinyin": "chōuqì", "analysis": "流泪 can occur peacefully in joy or grief, while 抽泣 describes convulsive sobbing with shuddering gasps for breath."}, {"id": "3", "compared_word": "流泪 vs. 流汗", "pinyin": "liúhàn", "analysis": "流泪 is weeping tears from eyes, while 流汗 is sweating perspiration through pores due to physical exertion or heat."}]}, "traps_and_cognates": {"look_alikes": [{"character": "相", "pinyin": "xiāng", "meaning_en": "mutual; appearance", "distinction_note": "Has 木 on the left of 目 instead of 氵 (water)"}, {"character": "泪", "pinyin": "lèi", "meaning_en": "tears", "distinction_note": "Has 氵 on the left of 目; traditional 淚 has 戾"}, {"character": "盲", "pinyin": "máng", "meaning_en": "blind", "distinction_note": "Has 亡 on top of 目 instead of 氵 on left"}, {"character": "梳", "pinyin": "shū", "meaning_en": "comb", "distinction_note": "Has 木 on left with 𠫓 and 川 on right instead of 氵"}], "etymological_cognates": [{"character": "眼泪", "pinyin": "yǎn lèi", "gloss_en": "tears"}, {"character": "流淌", "pinyin": "liú tǎng", "gloss_en": "flow; trickle"}, {"character": "流行", "pinyin": "liú xíng", "gloss_en": "popular; prevalent; flow"}, {"character": "泪水", "pinyin": "lèi shuǐ", "gloss_en": "teardrops; weeping"}]}, "id": "39", "hanzi": "流泪", "pinyin": "liú lèi", "level": "HSK 5", "part_of_speech": "Verb", "senses": [{"sense_number": "1", "part_of_speech": "Verb", "register": "Standard", "definition_en": "to shed tears from the eyes due to sadness, grief, joy, or eye irritation", "definition_es": "derramar lágrimas; llorar por pena, alegría o irritación ocular", "example_phrase": "感动得流泪 (moved to tears)"}], "example_sentences": [{"id": "#1", "hanzi": "临行前看着母亲那双布满老茧的手把省下的积蓄塞进我衣兜，我转过身去忍不住悄悄流下了眼泪。", "pinyin": "Línxíng qián kàn zhe mǔqīn nà shuāng bùmǎn lǎojiǎn de shǒu bǎ shěng xià de jīxù sāijìn wǒ yīdōu, wǒ zhuǎn guò shēn qù rěnbúzhù qiāoqiāo liú xià le yǎnlèi.", "en": "Before departing, seeing mother's callused hands stuff saved money into my pocket, I turned around and could not help weeping silently.", "es": "Antes de partir, al ver las manos agrietadas de madre meter sus ahorros en mi bolsillo, me di la vuelta conteniendo las lágrimas a duras penas."}, {"id": "#2", "hanzi": "当看到被困数日的矿工全部安全升井脱险时，守候在井口的家属与救援队员们无不激动得热泪盈眶。", "pinyin": "Dāng kàndào bèikùn shù rì de kuànggōng quánbù ānquán shēngjǐng tuōxiǎn shí, shǒuhòu zài jǐngkǒu de jiāshǔ yǔ jiùyuán duìyuánmen wúbù jīdòng de rèlèi-yíngkuàng.", "en": "When miners trapped for days were brought up safely, families and rescue personnel waiting at the pithead were moved to tears of relief.", "es": "Al ver a los mineros atrapados salir sanos y salvos a la superficie, los familiares y rescatistas congregados en la bocamina rompieron a llorar de emoción."}], "collocations": [{"hanzi": "流下眼泪", "en": "shed tears"}, {"hanzi": "忍不住流泪", "en": "cannot help crying / shedding tears"}, {"hanzi": "感动流泪", "en": "moved to tears"}, {"hanzi": "暗自流泪", "en": "weep in secret"}, {"hanzi": "伤心流泪", "en": "weep from sorrow"}, {"hanzi": "眼眶流泪", "en": "eyes welling with tears"}], "idioms": [{"hanzi": "热泪盈眶", "pinyin": "rè lèi yíng kuàng", "meaning_en": "eyes brimming with warm tears of deep emotion"}, {"hanzi": "声泪俱下", "pinyin": "shēng lèi jù xià", "meaning_en": "shed tears while speaking; speak in a voice choked with weeping"}, {"hanzi": "潸然泪下", "pinyin": "shān rán lèi xià", "meaning_en": "tears trickling down cheeks quietly"}, {"hanzi": "催人泪下", "pinyin": "cuī rén lèi xià", "meaning_en": "bring tears to one's eyes; deeply moving"}], "character_decomposition": [{"character": "流", "pinyin": "liú", "meaning_en": "flow; stream; shed; drift", "meaning_es": "fluir; corriente; derramar", "radical": "氵", "radical_meaning_en": "water (three drops)", "meaning_component": "氵 (flowing water stream)", "sound_component": "𠫓 (newborn infant floating in stream / phonetic)", "stroke_count": "10", "composition_type": "左右结构", "etymology_and_mnemonic": "Depicts a newborn child floating gently along a winding river stream (氵), abstracting into continuous flowing.", "visual_mnemonic_story_en": "Drops of fresh water (氵) cascading continuously down a stream without impediment.", "visual_mnemonic_story_es": "Gotas de agua fresca (氵) que fluyen sin cesar formando un arroyo continuo y constante.", "tone_mnemonic_anchor": "35", "cangjie": "EYIU", "traditional": "流"}, {"character": "泪", "pinyin": "lèi", "meaning_en": "tears; weep", "meaning_es": "lágrimas; llorar", "radical": "氵", "radical_meaning_en": "water (three drops)", "meaning_component": "氵 (water / droplets)", "sound_component": "目 (eye)", "stroke_count": "8", "composition_type": "左右结构", "etymology_and_mnemonic": "Ideogrammic compound of water (氵) welling from the eye (目), graphically illustrating human tears.", "visual_mnemonic_story_en": "Crystal clear water drops (氵) spilling softly out of the corners of the eyes (目).", "visual_mnemonic_story_es": "Gotas cristalinas de agua (氵) que brotan suavemente de los ojos (目) de una persona.", "tone_mnemonic_anchor": "51", "cangjie": "EBU", "traditional": "淚"}], "extended_reading_passages": [{"id": "#1", "hanzi": "离别总是在不经意间到来。车轮缓缓转动，透过弥漫雾气的车窗，望着站台上母亲渐渐模糊的身影与挥动的手帕，眼眶里打转的泪水终于忍不住夺眶而出，浸湿了整个衣领。", "pinyin": "Líbié zǒngshì zài bùjīngyì jiān dàolái. Chēlún huǎnhuǎn zhuàndòng, tòuguò mímàn wùqì de chēchuāng, wàng zhe zhàntái shàng mǔqīn jiànjiàn móhu de shēnyǐng yǔ huīdòng de shǒupà, yǎnkuàng lǐ dǎzhuàn de lèishuǐ zhōngyú rěnbúzhù duókuàng-érchū, jìnshī le zhěnggè yīlǐng.", "en": "Parting arrives unawares. Wheels turning, peering through foggy windows at mother's blurring silhouette waving her handkerchief, tears welled in my eyes and overflowed, soaking my collar.", "es": "La despedida llega sin aviso. El tren arranca y, tras el vaho del cristal, la silueta de madre agitando el pañuelo se nubla; las lágrimas contenidas brotan al fin empapando el abrigo."}, {"id": "#2", "hanzi": "心理学实证研究表明，“情绪性流泪”是人类特有的非言语心理宣泄与社会联结机制。泪液中富含应激诱发的催乳素与促肾上腺皮质激素，适度流泪不仅有助于机体缓解心理压力，更能在社交互动中有效激发同理心。", "pinyin": "Xīnlǐxué shízhèng yánjiū biǎomíng, \"qíngxùxìng liúlèi\" shì rénlèi tèyǒu de fēi-yányǔ xīnlǐ xuānxiè yǔ shèhuì liánjié jīzhì. Lèiyè zhōng fùhán yìngjī yòufā de cuīrǔsù yǔ cùshènshàngxiàn-pízhì jīsù, shìdù liúlèi bùjǐn yǒuzhùyú jītǐ huǎnjiě xīnlǐ yālì, gèng néng zài shèjiāo hùdòng zhōng yǒuxiào jīfā tónglǐxīn.", "en": "Empirical psychological research indicates that emotional crying is a uniquely human mechanism for psychological release. Emotional tears contain stress hormones; shedding tears relieves neuro-stress and evokes social empathy.", "es": "Estudios de psicología confirman que el llanto emocional es un mecanismo de desahogo humano. Las lágrimas eliminan hormonas de estrés y su expresión en sociedad estimula la empatía comunitaria profunda."}]}];
